window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220610-10","meetingId":"r04-cm06","date":"2022年6月10日","dateIso":"2022-06-10","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"湯澤委員","kind":"質問・要望","question":"１枚目は、物価上昇にともなう経済支援への要望であります。それから、２枚目は、環境に関する要望で、前段は省きますけれども、気温上昇に伴う災害クラスの豪雨に対して、各種施策の拡充を求めたいと考えています。それで、１点だけ訂正がありまして、環境に関する要望のところで、東京都への要望にも「国の責任」となっているところがありますが、それは、「都の責任」としていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"物価高騰に対する支援と、子ども・若者の支援というところと、最後の帯状疱疹を予防するワクチンに関する要望ということで、それ以外は去年と項目としては変わっておりません。国と都への要望が混在しておりますが、便宜上、一括してご説明します。１枚目のところで、これは新型コロナウイルス感染症対策に関する引き続きの要望です。７番目です。足りていない。高齢者施設に関する要望は、例年のとおりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"４番目が、住居確保給付金も継続していくということと、多くの方がコロナで苦労していますけれども、恒久的な制度にしていくことが重要だということで求めています。２番目が、介護保険料を引き下げるために、国の公費負担を大幅に引き上げることを求めます。２番目が、私立保育園の保育士と品川区の処遇改善と財政支援も求めています。２番目が、中学校も早期に３５人学級の実施を求める。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、要望としまして、まず、保育士の賃金を増やすということ。次が、学校教員の人事権と教員給与を東京都から２３区へ移譲することについて。したがって、東京都も学校教員の人事権と教員給与を２３区へ移譲することを要望します。４番目に、感染症などで大勢の感染者が生まれた場合に対応する医療従事者等の宿泊できる施設など、上記の場合に備えて必要な設備を持った大型施設をつくることを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"のだて委員","kind":"提案","question":"１点、羽田新ルートについては、２会派の提案なのですが、都内の１５区に関わる問題で、広範囲に及ぶものですし、品川区は市街地を低空で飛ぶ自治体ですから、２番目、３番目など、一致できるところで意見を挙げるということも重要だと思いますので、そういったところで調整できたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、拝見すると、物価上昇に伴う経済支援への要望というところについては、会派がかぶっているというところで、ここは国民の喫緊の課題であって、国に対するもの、東京都に対するものということで、大きな項目として一致しているのではないかということと、それに新型コロナウイルスが重なるかどうかというところも一部ではあったのですけれども、我々はワクチン寄りというところで縦分けたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今日、この段階で、頭出しだけさせていただきたいと考えていますが、区長の専決処分事項の追加指定についてということで、議員提出議案にさせていただきたいと考えています。それを参考にしていただき、最終的には本会議で議決できるように、我々としても動いていきたいと考えていますので、今日は頭出しだけしますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5468#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":13504,"voices":41}},{"id":"r04-20220622-10","meetingId":"r04-cm06","date":"2022年6月22日","dateIso":"2022-06-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","topics":[{"id":"topic-01","title":"の２、区長の専決処分事項の指定","agenda":"の２、区長の専決処分事項の指定","exchanges":[{"speaker":"石田（秀）委員","kind":"提案","question":"その理由も調べすると、それぞれ契約金額の何％以内、この場合は１００分の５としていますけれども、そういう文言が入ってきたりするということなので、これは行政側から提案をするのではなく、専決に対して付加していく部分については、議員提案のほうがいいだろうという話を、我々は公明党ともいろいろ話をさせていただいて、今日に至っているということでありますので、その部分について。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"の４その他","agenda":"の４その他","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"当然議長としての責任になってしまうので、その辺は会派としてどう考えているのか、会派なのか個人なのか、この辺は不明な点があるので、確認できればと思ったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"私としても、通告したからにはきちんと質問事項、内容を既定の期日までに行政機関にちゃんと提出するようにというのは再三申し上げておりました。そして、火曜日、水曜日、先週１週間前に突然、急激に体調が悪化したということなので、それならばということで、我々もちょっと連絡をしたのですが、電話がなかなかつながらない状況にまで至りました。心からおわびする次第です。本当にすみませんでした。","respondent":"本多議長","answer":"議会としてというところでお答えをします。通告の日に通告されて、本来であれば先週の木曜日までに原稿提出、提供ということなのですけれども、木曜日に提供されなかったので、金曜日から総務部が、当然通告はされているので当然担当の部署もそうだと思います。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今の部分で確認させていただきたいのですけれども、先週の木曜日が期限で、今の議長のご説明だと、金曜日から連絡を取ろうと、先ほど幹事長からご報告があった、取り下げますというのはいつの時点でされたかというのを時系列的に教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"確認","question":"慌ててショートメールから何から、様々な手段を講じて何度も連絡をして、ようやく、電話は出られないのだけれども、今回体調が非常に思わしくないということだったので、これ以上待っていたら、行政機関に多大な迷惑がかかるし、議会としても中途半端に本会議を運営するという話ではないですから、できないならできないと申し上げてくれということを本人に確認を取りましたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"それはさっき伺ったのですけれども、取り下げたのはいつなのですかと聞いたのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"体調ということが理由ならば、やむを得ない部分もあるとは思うのですけれども、現在の状況として、ご本人から、例えば、議長なりにご連絡はされたのでしょうか。今も連絡できないと言われたら、しようがないけれども、当然議会の中の議員ですから、議長に通すべき話だと私は思います。そこら辺はどうなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"須貝委員","kind":"意見","question":"私から、本人が連絡できるなら、もちろん本人がすべきだという話は申し上げました。ですが、体調的に自ら電話して連絡する、お断りする、辞退するということが、ちょっとかなわない状況だということで、その状況は、僕らは会っていなくて分からないので、私が、幹事長から皆さんに連絡しますという話を申し上げまして、私から連絡した次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"確認","question":"それはさっき聞いたのですけれども、その後、今現在の段階で、取り下げた後に弁解をするべき問題はあると思うのです。その辺の対応がされたのかということを確認したい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須貝委員","kind":"意見","question":"だから、私は本人の体調が元に戻って、元気になれば、そういうふうにできると思います。ただ、今はそういう状況にないということなので、私は回復するまで待って、本人の体調がよくなったら、議長をはじめ、皆さんにちゃんとご挨拶に上がると考えています。そういうふうに指導するつもりです。誠に申し訳ありませんでした。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"分からないけれども、普通だと奥さんが看病されて、奥さんからすぐに電話が１本あってもおかしくないわけだし、何かその辺があまりにもずさんなのではないかということと、申し訳ないのだけれども、会派を組んでいる幹事長として、家に行ったのですか。もっと言えば、明日からの本会議はどうされるのですか。どう聞いているのですか。そこを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"確認","question":"八潮のほうに住まれているということで、もちろん行こうと思いました。ですが、本人が電話すらできないということは、恐らく応対も難しいかなと私のほうで判断しまして、それはやめました。それで本会議等について、あと委員会もまた続けてありますので、それも確認しました。あくまで体調が戻ってからしっかり対応するようにとは指導しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、幹事長の中ではどういう状態なのか、ただ体調が悪いというわけではなくて、病院に行っているのかとか、どうなのかということとかを聞いているのかどうかというところ、奥さんも含めて、どこまでプライバシーの部分に踏み込むのか分かりませんけれども、普通だとその辺のところはあってしかるべきなのかなと思うのですけれども、その辺のところはどうなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"今回のことは、私からすると異常かなというぐらい、ひょっとしたら相当悪いのかなという判断をさせていただきました。行くのはもうすぐ近くですから、全然問題もないし、本人に根掘り葉掘り聞くのは構わないのですが、今回の状況に関してもう成人した大人の方ですから、それがそういう行動に出るというのは、よっぽど体調がすぐれないのかなと私のほうで判断して、今のところ静観している次第です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"確認","question":"そこまで調子が悪いと、普通だと病院に行っているはずなのです。即入院ですよ。命に関わることなので、そこは確認しているのですかということと、申し訳ないけれども、さっき議長にも謝罪したとおっしゃったけれども、我々も議会の一人として、少なくともそういう可能性があるかもしれないですよ。申し訳ない言い方だけれども、その辺をどう考えていらっしゃるのかなというのはちょっとありますね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問","question":"みんながそう思っていると私は思っています。重大なことが起きたのですと先ほど議長からの報告があって、議会側が執行機関に謝罪をしたのです。それに対して静観する。それが幹事長としてのご説明なのですかというところなのです。要するに、また同じことが起きないために、どういうことをされるのかということをみんなは聞いているのだと思うのですけれども、そこのところのご説明をお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"須貝委員","kind":"意見","question":"何度も申し上げますが、彼が過去３年の間に、こういうことを起こした状況がないということと、私としても、そこまで体調を崩されているというのは非常に心配しています。必ずお大事にしてください、何かあったら連絡してくださいとは連絡しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"確認","question":"最後に１ついいですか。会派で確認すべきものを、していなかったわけです。そういうところで今回こうした事態に陥っている。静観するとかしないとか、そこが問題なだけではなくて、それに対して今後何か確認をしていくとか、そういうことはお考えにならないのですかということです。そこについての会派としてのお考えは何かないのでしょうかということを先ほどから申し上げているつもりなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝委員","kind":"確認","question":"何度も申し上げますけれども、会派として確認するのは当たり前のことだし、それに提出するというのは、議会の議員になって、当たり前のように私は考えていましたから、ましてや本人に過去にそういうことがない限り、本人を信用するというのは、会派の幹事長ならば、皆さん個々の議員の活動、行動は信用して、信頼して見ていると私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それは皆さんがちゃんとどこかで確認をしているわけです。行政に対して施策の提言、要望をすることは、我々議員の職務上の責務だとまで議会の一般質問で言っている。それはこの場でしっかり確認をするとか、今はお答えをいただくということではなくても、それは確認をしていただいて、こういう形でちゃんとしっかりしたものを、提出物があるかどうか、別になくてもいいのですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"結局病状とか、今どうなのだというのを言っていかなければいけないことになってしまうので、本人には聞きました。ここで、彼はこういう病気でこうなのだというのは、ここからは今、皆さんに申し上げるのは簡単なのだけれども、そういうふうに言えないということは、申し訳ないのですが、こちらの対応も分かっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今みたいな発言が欲しいわけですよ。それは、発表されたのかどうか私は確認していないので知りませんが、どうぞ私の会派は発表しても構いませんと言いました。だから、ここでこう言ってくださいということを、個人の病名を言ってくださいとか、そういうことを私は言っているわけではないので、議会のルールがあるわけですから、そこら辺の話はしっかりやっていただきたいなと思っているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"だから、本人のご病気については、やはり本人がしっかり話されたほうがいいと私は思うので、私は本人から聞いてこうだああだ、過去にこういうことがあって云々、多少は聞きました。私からも今皆さんから言われたことに関して、きちっと本人にもお話ししますし、今後に対してもきちんと指導していきますので、誠に中途半端な返答で恐縮ですが、どうぞご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"須貝委員","kind":"確認","question":"はい、医師の診断書云々に関しては、本人も申しておりました。それは本人にもう一度確認して、私から議長に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"一般質問は、住民から付託された議員として最も重要な仕事の一つです。様々な事情があるかもしれませんけれども、区民の期待を裏切ったことになりますので、重要な仕事を放棄したことを重く受け止めてもらいたいと思います。会派としても再発防止に取り組んでもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"提案","question":"今回、国への要望事項ということで、第３位の公立中学等の部活動支援に関する要望がありましたけれども、それが提案されたのが自民党から、今、要望が順位の３番目ということでしたけれども、その中で、５会派から共通して出された介護従事者の処遇改善ですとか、共産党が提出しました環境、脱炭素の取組よりも優先して、区議会全体として要望するものとしてはふさわしくないと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/369281?Template=document&Id=5470#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":20291,"voices":80}},{"id":"r04-20220627-6","meetingId":"r04-cm06","date":"2022年6月27日","dateIso":"2022-06-27","committee":"区民委員会","time":"午前１０時００分～午前１０時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件抜き出しています。","topics":[{"id":"topic-01","title":"第４２号議案、令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第４２号議案、令和４年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"このプレミアム商品券にしろ、このキャッシュレス決済ポイント還元事業にしろ、物価高騰への対策として一定の効果がありますし、区民の方からも本当に歓迎されている、待ち望まれている事業で、本当にいいことだと思うのです。ポイント還元率も上がりますし、そういう声も伺っております。ただ、物価高騰がどのぐらい続くのか。そのことを少し伺っておきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"それからもう一つは、円安というのが一つ大きな原因です。いわゆる金利格差の問題で、その分どうしてもコストがかかってくるというようなことが大きく２つ、物価高騰の原因としてあるのかなと考えているところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、そう簡単に終わらない。ウクライナ侵攻にしろ、円安にしろ、すぐに終わってしまうようなものではないと思うのですけれども、やはりさらなる対策も必要になるかもしれないという見通しは持たれているという理解でよろしいのでしょうか。どうでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"ただ、一方で区民の下支えという部分がありますので、対応策という形になろうかと思うのですが、まだ現時点では何とも言えないところありますので、国や都とかいろいろな様々な施策が出てくるかと思いますので、そちらを見ながら、区としてできる支援ということで。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"もちろん区だけでどうこうできる話ではないと思います。それで、これは昨年の決算特別委員会のことなのですけれども、物価高騰というか、区が打つ経済対策として、私たちは例えば業者の方に、融資だけではなくて、直接給付をもっとしていただきたいということを何度か求めてきました。これは今もそういうお考えなのか。その点を伺いたいと思います。その辺のことを伺いたいと思います。いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"何度かこちらはご質問いただいているところかと思います。私ども、融資あっせんという形を軸にやらせていただいておりまして、おかげさまでこちらの影響で、いわゆる倒産件数が少ないという部分で、大きな効果が出ているかなと認識しています。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"その時期にやっていただきたいということなのですけれども、それに対して、給付というのは本当に一時的で経済的効果もないからやりたくないのだというような趣旨のことを、その決算特別委員会の時に一言おっしゃったように思うのですが、そこら辺のことをもう少し伺いたいと思ったのですけれども、直接給付はやらないで、融資あっ旋だけでやっていきたいというような趣旨はなぜなのか。","respondent":"遠藤商業・ものづくり課長","answer":"そういう面では業態転換だとか、様々な別の方法でということで、支援を実施させていただいているところです。そういう部分も今年は特に手厚くしていますので、そういう部分で事業者にも支援をしているということで考えているところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"でも、その直接給付を受けることができれば、今を乗り切って事業を続けていくことができるわけです。それでいいのですか。そういう意味で、直接給付の救済策もきちんと用意していただきたいと思うのですけれども、そこら辺、頭から直接給付は経済効果が薄いからやらないのだと、融資さえ用意すればいいのだというようなことはおっしゃらないでいただきたいのですけれども、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"国のほうで持続化給付金とか、今ですと事業復活支援金とか、様々な給付金を実施していただいているところですので、そちらですといわゆる融資でなくても、申請すればお金をいただける部分なのでご活用いただいているのかと考えています。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"国としては、そういう持続化給付金のようなメニューも用意しているわけですので、区のほうも、ですから融資だけではなくて、給付というメニューも決して閉ざさないでいただきたいと思うのですけれども、その辺のお考えは、閉ざす考えはないという理解でよろしいのでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもはこういう支援策を考えていく時には、あらゆるものを一度検討しています。テーブルには全て載せた上で、一番効果の高いものを今後も検討、継続させていただければと思います。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"ぜひともそういうふうに、あらゆるメニューを載せた上で、区民の要求を本当に第一に考えてやっていただきたいと思います。本当にこの物価高騰は深刻になっておりますので、そういう考えでやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"松本委員","kind":"意見","question":"そういう中で、では果たして当区のお金の使い方として、これが本当にこの物価高の中で物すごく困っている方たちに一番ベストなのかというのは考えないといけないのかなと思っていまして、例えばこの地方創生臨時交付金の使い道としては、給食費の無償化とかそういったものもある中で、当区としてそういう選択肢ではなくて。","respondent":"遠藤商業・ものづくり課長","answer":"私どもは今回歳出ということで、こういうものをやりたいというような話をさせていただき、キャッシュレスということで、東京都のほうで補助金がつくというところまでで、ぜひやらせてほしいということで内部のほうで上げたところなのですけれども。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問・要望","question":"多分今おっしゃられたところで、所管は多分総務委員会とかそちら側になるのだと思っています。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"少し細かいことをお聞きしたいと思います。そういった時のために、第一次販売して余った時、どういった形で第二次販売みたいなことをきっちり皆さんに活用していただくためにやっていくのか。特にこのキャッシュレスのほうはどうなのかなというのが気になって、この３点を教えていただけますでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"キャッシュレス決済につきましては、昨年は１か月間という形でやらせていただいたのですけれども、それを見込みまして、今回は１か月半程度という形で延ばさせていただいているところです。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"１点、質問します。キャッシュレス決済ポイント還元事業で、世の中のデジタル化がどんどん進んでいくということで、ぜひ進めていただきたいと思うのですけれども、こういったシステムがどんどん時代とともに変わっていくことに対して、各お店のレジの機能を対応させるのに、その辺のところをどのようにお考えなのか。この補正予算で網羅できるのか、その辺を教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"なかなかキャッシュレスが進まないという現状がございまして、区の場合ですと店舗で導入するのがなかなか難しいというようなところで聞いているところです。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問・要望","question":"物価高騰に対して助けになりますし、区民の方にも喜ばれるので、さらなる充実を求めて賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":12069,"voices":40}},{"id":"r04-20220627-7","meetingId":"r04-cm06","date":"2022年6月27日","dateIso":"2022-06-27","committee":"厚生委員会","time":"午前１０時００分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を60件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本日は、お手元の審査・調査予定表のとおり、議案審査、請願・陳情審査およびその他を予定しております。そのため、所管質問については会議の効率的運用の観点から、なるべくご配慮をいただきたいと考えています。その上でなおご発言を希望される方は、今の時点でお申出いただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"マイクロチップのところなのですが、これは今回、犬のということで、今現在、飼われている方は、このマイクロチップは努力義務だと思うのですけれども、新たに６月以降、販売店で買われる方には、必ずマイクロチップが犬にも猫にも装着されているということで、今、飼われている犬は区内にどれだけいるのかという把握は、区のほうでできるのか伺いたいのと、ふぐの加工製品のほうですが。","respondent":"舩木生活衛生課長","answer":"そちらにつきましては、資料でお付けしております別紙１の２ページ目の下のところ、ふぐ加工製品取扱届出制度を廃止とするというところの理由に３点ほどありますが、主に、いわゆる一般食品と区別して取り扱う必要がないということで、確認がされているものと聞いております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"確認","question":"マイクロチップのほうは、今のところ１万３,２９２頭がもう飼われていて、その１万３,２９２頭がマイクロチップを入れたことというのは、区は確認できるのでしょうか。それで、どれだけ進んでいるかというのは把握していけるのかというのを伺いたいのと、あと、ふぐのほうは分かりました。そこをもう一度お願いします。","respondent":"舩木生活衛生課長","answer":"今後マイクロチップを努力義務ということで、装着された方の把握につきましては、装着した場合には、国のほうにしっかりと登録をしなければならないということが併せて義務化されておりますので、区においても、先ほどご説明いたしました国に求めを行うことにより。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。リフォームは対象に入るのかというのを伺いたいのと、この長期優良住宅というのが、割と環境に配慮した住宅になっているのだなと思うのですけれども、やはりこれが進んでくれるといいなという思いはしているのですが、区としては、既存住宅が長期優良住宅になっていく促進というか、区として進めていくという計画や方針はあるのか、伺いたいと思います。","respondent":"長尾建築課長","answer":"ですので、リフォームによってその水準を超えることができれば、認定を受けていくという可能性はあります。２つ目については、区として長期優良住宅を進める方針等があるのかというところですが、長期優良住宅につきましては、認定を受けますと様々メリットがあります。","id":"exchange-004"},{"speaker":"あくつ副委員長","kind":"確認","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"確認をさせていただきたいのですが、今と何か登録上、変わってしまうことがあるのでしょうか。","respondent":"舩木生活衛生課長","answer":"この法律の改正の背景につきましては、やはり主たる事務所の所在地に登記する、それから従たる事務所の所在地に登記するということで、どうしても登記漏れがあったり、あと、今や従たる事務所のところを所轄する法務局でも。","id":"exchange-006"},{"speaker":"あくつ副委員長","kind":"確認","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ご異議なしと認めます。よって、本案は全会一致で原案のとおり可決決定いたしました。以上で、本件および議案審査を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"予定表２の請願・陳情審査を行います。本陳情は初めての審査でありますので、書記に朗読させます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問","question":"この地域猫活動ですね、この間、議会の中でも様々な会派が取り上げている問題だと思います。ということは、地域からそれだけ何とかならないかなという声が上がっているということだと思うのです。この陳情にもあるように、地域猫活動は、地域住民、行政、そして、アドバイザーであるボランティアの三者が共通認識を持って取り組むものと考えているのか、区の認識をまず伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"区のほうからお願いをしているといいますか、飼い主のいない猫モデル地区活動についての問題であるとか、それから、それを解消していく方法については、共通の認識を持っていただいた上で、町会を通じて活動していただいているものと認識しております。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、三者で解決していくという、まだそこは地域の中ではあまり広がっていないけれども、区としては、この三者で地域猫活動を進めていくという認識であるということでいいかというのを、すみません、もう１回確認させてください。","respondent":"舩木生活衛生課長","answer":"具体的なアドバイザーにつきましては、特定の方に頼めば何でも分かるといったアドバイザーという方が選任されていない現状がありますけれども、活動の中でどういった問題があるのかといったところは、常にご意見を伺いながら対応を考えているところですので、そういった部分では。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"この陳情の中でも書かれている自民党の一般質問のときに、町会だけで対応し切れない場合が出てきたり、理解をまとめることに苦労するなど、地域での合意を得るためのハードルが高いということもおっしゃっていて、さらにお金もかかってくるということで、ここは私も予算特別委員会等で質問させていただきましたけれども、そういう状況なので。","respondent":"舩木生活衛生課長","answer":"飼い切れなくなった猫を捨ててしまうとか、そういうことにより、その飼い主のいない猫が、外で新たなそういう飼い主のいない猫を産んでしまうという、そういうようなことを減らしていくために、やはり行政としてもしっかりと、その目的であるとか、活動いただいている方も。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"その地域に認識をしてもらうとか、区が啓発をしていくというのはいいのですが、区としての役割というのもあると思うのです。この陳情もそうですが、このホームページの作成は区がやることですよね。それで、東京都と国からもガイドブック、またガイドラインが出ています。その中での区の役割が果たされていると今現在で思われているのか、伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"今年度、準備を進めておりますのは、猫が大好きの方というか、命あるものはやはり大切にということで、そのようにお考えになっている方もいらっしゃれば、実際に飼い主のいない猫によりふん尿等の被害を受けていらっしゃる方、そしてまた、そのいずれでもない方。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから少し具体的にやられていくということなのですが、やはり現時点で大変な、この陳情にも苦しい声が出されていますよね。先ほど、これから現状の調査、把握をしていくということでした。こうした肉体的疲労や精神的苦痛、経済的困窮というのは、今のところ把握はあまりされていないのでしょうか。されている部分があれば、教えていただきたいと思います。","respondent":"舩木生活衛生課長","answer":"区としましては、やはりモデル地区で活動されている方、現場にも当然見に行っておりますし、窓口で様々なご意見をお寄せいただいたり、お電話でも様々な意見をお寄せいただいておりますので、繰り返しになりますが、やはり経費ではなく、労力や時間であるとか。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、私は予算特別委員会のときに、資金の面でさらなる援助をしてほしいということは述べさせていただきました。やはり具体的に、これから始めていくということですけれども、今のこうした苦難を解決していく方法が必要だと。こうした、進めてほしいというマニュアルだったりホームページだったり冊子だったりというところでは、作成していくというお考えはあるのかどうかを伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"ですので、そのためのホームページも含めまして、どうしてこういう課題が存在してしまっているのか、そして、その課題を少しでも減らしていくためにはどうすればよいのかといったところに行き届くような啓発の準備を進めているところです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、この陳情にあるように、活動の公共性を保障するという、そこも含めて、今後ぜひ、広げていくべきだな、宣言していただきたいなと思うのですけれども、そこはいかがでしょうか。","respondent":"舩木生活衛生課長","answer":"ですので、そういったところを踏まえまして、そこにしっかりと、今、公共性という話もございましたので、もちろんこれはしっかりと区の腕章をつけていただいて、公共性のある事業として行っていただいているわけですから、猫が好きとか嫌いとかという対立構造を生むのではなく。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"スピード感がすごく大事だと思うのです。陳情にも書かれていますが、８月がまた増えていってしまう時期ということで、それを見過ごしてまた増えていくという状況にさせないためにも、やはり調査・把握は大事なのですが、それをスピード感を持ってやっていただきたいなと思うのですけれども、そこのスピード感的には、区としてはどういうふうに説明していくことを考えているのか、伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"飼い主のいない猫をこれ以上地域に増やさないためには、やはりペットは一時のかわいらしいということだけではなく、しっかりと責任を持って飼っていただくということが、何よりもこのような課題を新たに増加させないためのものだと認識しておりますので。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうやって陳情者の方にも大田区の事例を出していただいて、私も見ましたが、本当に丁寧に、１２ページにわたって、これがまずどういう問題なのか、そして、どうやって解決していくのか、そして、こういうふうにみんなで取り組みましょうというのが、地域に向けても、行政の役割としても、そしてアドバイザーたちにも訴えるような中身になっているので、せめてそういう中身にしていかないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"渡辺委員","kind":"質問","question":"もちろんこの方は今、苦労されているのだなという前提でお伺いします。ここでまず前提が違ってしまうので、行政としてこれまでの取組で、このように成果としてあった部分を把握されているかどうか、一つ聞きたいのと、あと、下に改善を要求という項目で１から４まであります。同趣旨の対応が検討されているかどうか、それは、今後、大田区を含めて最善の方法を模索されているのかどうか、お知らせください。","respondent":"舩木生活衛生課長","answer":"そういった中で、現状を把握しています。最善の方法ですけれども、私も大田区のパンフレット等を拝見しておりますが、この中身そのものについては、非常にわかりやすいものだと認識しております。","id":"exchange-019"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"渡辺委員","kind":"質問","question":"結論を出すで、不採択。理由は、今、質問でもありましたが、少し前提のところで違う部分がある部分、そしてまた、限定した改善要求だと厳しいのですが、ただ、そうはいっても、今ご答弁にあったように、それを踏まえた検討がもう既になされているというところから、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"意見","question":"なので、そうした部分ではもっと区が入って、東京都や国のガイドライン、ガイドブックにあるように、しっかりと地域に対策として区が入っていくということをしていかないと、解決しないよということも、このガイドでも言われていますし、そして、この紹介されているアドバイザーの方々も言われているので、もう明らかに足りないというところは、解決していかなければいけないのではないかなと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"木村委員","kind":"意見","question":"不採択でお願いします。猫は自宅で飼って、人間と一緒に生活をする生き物だと思っています。そういう飼い主のいない猫をつくり出すような活動というか、これは、そういう意味では、人と猫の共存できる街づくりというのを、私は違った形で、本当に自宅で家族とともに生活できるような、そういうものをつくるのは私はいいと思いますけれども、この陳情に対しては不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出す、不採択でお願いします。そこの中で、課題と今後の方向性を出していくと。ただ、その中で、こちらの陳情の中にあるようなことも踏まえて、先ほど、ホームページも改善していくというのも計画にあるとお聞きしたので、そういったところもしっかりと、東京だけでなく、ほかの都市部の例なども参考にして、様々な取組、これまでの課題を整理し、さらに進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。この課題ついて取り組んでいかなければならないというのは、もちろん理解しております。今現在、モデル事業ということですので、そこでしっかり現状把握をしていただいて、品川区での課題解決に向けては何が必要なのかを、しっかり検討していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問","question":"本陳情につきましては、結論を出すとのご意見でまとまったようですので、そのような取扱いでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本件は結論を出すことに決定いたしました。先ほどそれぞれの方のご意見を伺いましたので、本陳情につきましては、挙手により採決を行います。本件を採択とすることに賛成の方は挙手願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"意見","question":"賛成者少数です。よって、本件は不採択と決定いたしました。以上で、本件を終了いたします。ここで、理事者の入替えを行いますので、暫時休憩といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本請願は初めての審査でありますので、書記に朗読させます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"この補聴器購入費助成ですが、先日の一般質問でも、実施に向けて取り組んでいくというふうに区長もご答弁されていまして、いよいよだなと、ようやく実施に向けて動いたなと思っています。今、いろいろ説明いただきましたけれども、実施に向けて取り組むというようになった、２月は実施しないと言っていたものが取り組むようになった、この大きな理由は何なのかを伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"そういったことで今回、補聴器の普及・啓発、それから、その結果を見まして、購入費の助成等についても、実施の方向で進めていきたいと、このように考えたところです。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが今回、こういう実施に向けて進んでいくというところでは、今まで言われてきていたことが、やはり専門家の皆さんの認識と一緒だということで認めて、進めていくということをしないと、国も提言を出しましたし、こういったところで進んでいかないと思うので、そこの認識のところを改めて伺っていきたいのですが、いかがでしょう。","respondent":"寺嶋福祉計画課長","answer":"区として難聴に関することを特定するのは大変難しいという考え方は、今でも変わっておりません。しっかり医療機関、それから業界団体と連携して、普及・啓発に努めていくことが重要と考えております。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"特定は難しいではなくて、要は専門家等々が言われてきた必要性について、ここを認めていかないと、実施という方向にはなかなか進まないよということを、私たちは指摘させていただいていたのです。要は、家族や周りが気づくとおっしゃっていたのですね。だから、そうではないということが改めて認識されたということで、よろしいのでしょうか。","respondent":"寺嶋福祉計画課長","answer":"我々もそういった趣旨の情報を参考にしながら、専門家の意見を聞きつつ、しっかりコミュニケーション、それから、認知症予防については取り組んでいきたい、このように考えております。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも、区としてはそういう認識ではない」ということで言われてきたのですよね。課長が言うとおりの提言だと思うのですけれども、これで進んでいくとなると、この提言、この請願にも１から５まで出ていますが、これからになってくると思うのですけれども、どういうところから始められていくのかなというのを伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"今後については、まさにこれからということにはなりますけれども、しっかり医療機関等と連携して進めていくという考えは、先ほど申し上げたとおりです。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"考え方が変わっていないとちょっと大変だなと私は思うのですが、それで、この間の一般質問の答弁のところでは、普及・啓発をして、その上で実施に向けて取り組んでいきたいと答弁されたのですけれども、その普及・啓発に向けて周知した上でという、その取組というのは、どういう具体化がされるのか、今、分かっていれば教えていただきたいのですが。","respondent":"寺嶋福祉計画課長","answer":"先ほど説明の中で触れましたけれども、今年度、組織改正で、認知症サポート係と、それから高齢者活動支援担当を高齢者地域支援課の中に置きまして、まさにこれから区としてしっかり取り組んでいきたいという一つの意思表示でもあります。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういうところでとどまっていては、なかなか進まないのではないかな。ほかの区は進んでいますが、結構購入されている方、この助成を受けている方も多く出ているので、あるということがやはり大事なのだなとは思うのですけれども、さらに進めていくためには、港区レベルにやはりしていく必要があるのではないかなと思うのですけれども、今後になってくると思うのですが、そこについていかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"先週の本会議の中での区長のご答弁のように、ご質問、意見をいただきまして、それに対して前向きに取り組んでいくという、まさにこれからその仕組みについては考えていくという段階なので、今日、具体的なことをお示しできるものはありませんけれども、今。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この補聴器購入費助成を進めていくに当たっては、先ほども、民間企業が調査した厚生労働省の研究、それから、そこから出されている提言の中では、陳情にもあるとおり、早期発見する仕組みの構築、そして、受診勧奨できる認定補聴器技能者の周知、その他、１から５まで挙げられているわけですけれども、なので、こうした今、品川区の現状として、補聴器相談員。","respondent":"寺嶋福祉計画課長","answer":"内容、取組につきましては、再三申し上げているとおりこれからの検討になりますので、今の段階でお答えできる内容はございません。","id":"exchange-036"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これからということで、引き続きいろいろお聞きしながら充実させたものにしていく機会は、議会としてもあると思うので、そこは、こちらのほうの質問や、充実をさせる、実効性あるものにしていくための意見は言っていきたいなと思っているのですが、今の段階では何もお答えいただけないということなので、ここにとどめますけれども、やはりやるからには実効性あるものに、そして、その大きな目的としては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"渡辺委員","kind":"質問","question":"それぞれ今、説明等を聞いている中で、まず、先般の本会議の一般質問の中で、方向性、実施の運びという答弁がなされている、これが大きなポイントになるかと思っています。もう既に方向性が示されている。そして、もう１点は、内容のところで、これはあまり深めていくことは得策ではないと思っています。それはまさに先般の本会議の一般質問は、私どもは本当に、何でしょうね、感心したというか刺激を受けた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。この補聴器購入費助成制度を求める請願、陳情は、今回で７度目。批判屋という声もありましたけれども、やられていないので、それが認知症を広げてしまうということにもなりかねないということで、これを進める必要があるのだということで、追求し、求めさせていただいたものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"木村委員","kind":"意見","question":"結論を出すということで、不採択でお願いします。今、港区では、６０歳以上の方々を対象にして助成をやっているみたいですけれども、やはり本当に補聴器を必要としている人たち、これは年齢に関係なく、そういう人たちにはしっかりと補助をしていく、助成をしていくべきであろうと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ほかのものにも様々な助成があると思うのですけれども、あるいは助成をしないという例もあると思いますが、公的な助成ですので、そういったものとのバランスを取りながらスキームをつくっていただきたいということと、もう一つは、助成することが最終的な目標ではなく、全体的にこういった難聴の方々への支援スキーム、そういったものも今、検討していかれると思うのですが、そういったところで十分。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"せお委員","kind":"質問","question":"結論を出すで、不採択でお願いします。一般質問や今の答弁からもありましたけれども、取り組んでいくということでご答弁がありましたので、ここに関しては不採択でよろしいのではないかと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"あくつ副委員長","kind":"質問","question":"本請願につきましては、結論を出すとのご意見でまとまったようですので、そのような取扱いでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本件は結論を出すことに決定いたしました。先ほどそれぞれの方のご意見を伺いましたので、本請願につきましては、挙手により採決を行います。本件を採択とすることに賛成の方は挙手願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"賛成者少数です。よって、本件は不採択と決定いたしました。以上で、本件を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本陳情は初めての審査でありますので、書記に朗読させます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"障害者７団体と言われている中に入っているかもめ会の皆さんに、この陳情が出たので少しお話を伺ったのですが、聞いていないというか、これはどこからの要望なのでしょうかねというのを、かもめ会からも返答をいただいたので、あ、違うのだなと思いまして、どこからのって、様々利用されている方だと思うのですけれども、そこを伺いたいのと、あと、精神障害のどういう状況の方への入浴施設になってくるのか。","respondent":"松山障害者支援課長","answer":"こちらのほうは、地域活動支援センターの中の事業の１つとして、入浴サービスをご利用いただくということを考えております。現在、区にも、やはり利用しにくい方ですとか、これがあったらもう少し施設に通えるといったお声も届いております。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"確認","question":"分かりました。肢体不自由児者等々の皆さんからも、入浴サービスが少し縮小されたりする部分もあって、なかなか困難だという声も届いていますけれども、障害児者総合支援施設のほうでは、入浴サービスはほかの障害であったかどうか、確認させてください。","respondent":"松山障害者支援課長","answer":"障害児者総合支援施設にまずは通っていただくために、対象者を拡大するために、どういったようなサービスが必要かというところで、今回考えたものです。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、こういう、入浴施設も作っていきますということで、そういった理解というのでしょうか、そうしたものを得ていかないと、せっかく作ったものがいい形にならなくなってしまうのではないかなと、少し心配もあるので、そこは次期指定管理者からの要望ということですけれども、ぜひ障害者団体の、精神の部分の団体の皆さんにも声は聞いていただいて、当事者や団体との協働でと書かれていますので。","respondent":"松山障害者支援課長","answer":"入浴設備につきましては、地下１階を予定しています。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、この陳情にもある中で、計画に掲載されていない事業というのもありますが、今、課長も説明したように、様々、拠点の整備の強い要望だったり、そういう、適宜実施されていくということはあり得ると思いますので、そこは、だからこそ当事者の声を聞いて、進めていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。よろしいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"渡辺委員","kind":"質問","question":"自民党は結論を出すでお願いします。そして、不採択。理由は、先ほど区の状況説明を踏まえ、願意に沿い難い内容だと判断し、不採択とお願いしたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いします。当然、当事者や障害者団体に声を聞いて、バリアフリーを充実させていくということは重要だと思いますけれども、この計画に記載されていない事業だとか、不適切な設計が多々あるというところでは、私たちはそこは賛同できない部分がありますので、趣旨採択で、ぜひ皆さんの声を聞いて、充実させていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"提案","question":"結論を出すで、不採択ということでお願いします。今、ご説明ありましたように、指定管理者候補者のほうからこういった提案があり、様々な意見を吸い上げて、こういった改築に進めてきたのだということを伺いました。そういうことですので、不採択。ただ、区としては今後の運営を、次期指定管理者に、区民の皆さんの声を聞いて運営に反映させていくという形で、支援をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"「現在のレイアウトはとてももったいない使い方をしている」というのは、私かと思うのですが、少し細かい話になるのですが、１階の飲食できるところなども少し工夫をしていけば、それは工事が必要かどうかは分からないのですが、工夫をしていけば、利用者もそうですが、いろいろな方に、地域の方に来ていただける施設になるのかなと思っていますので、そういったところも検討していっていただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問","question":"本陳情につきましては結論を出すとのご意見でまとまったようですので、そのような取扱いでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"本件は結論を出すことに決定いたしました。先ほどそれぞれの方のご意見を伺いましたので、本陳情につきましては、挙手により採決を行います。本件を趣旨採択とすることに賛成の方は挙手願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ副委員長","kind":"意見","question":"賛成者少数です。よって、本件は不採択と決定いたしました。以上で、本件および請願・陳情審査を終了いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"あくつ副委員長","kind":"意見","question":"ないようですので、以上でその他を終了いたします。以上で、本日の予定は全て終了いたしました。明日も午前１０時からの開会です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3632#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":29053,"voices":117}},{"id":"r04-20220627-8","meetingId":"r04-cm06","date":"2022年6月27日","dateIso":"2022-06-27","committee":"建設委員会","time":"午前１０時００分～午後 ３時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を88件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(2)第６２号議案、広町二丁目地内特別区道路線の廃止ならびに広町二丁目および大井一丁目地内特別区道路線の認定","agenda":"会議の運営上、予定表の順番を入れ替えまして、(2)第６２号議案、広町二丁目地内特別区道路線の廃止ならびに広町二丁目および大井一丁目地内特別区道路線の認定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、広町二丁目の道路の廃止と認定ということですけれども、この道路の廃止と認定がされるに至った経緯を伺いたい。ＪＲ広町開発がこの地区で行われますけれども、そのＪＲ広町開発との関係性、そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"開発についてのご質問なので、私からご説明いたします。広町二丁目地区につきましては、これまでも、この地区の大きな土地利用転換が図られることで、地区内の権利者で、これからのまちづくりということで検討してまいりました。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のＪＲの広町開発の区画整理事業のところで、区画整理の認可がされたというところでこの手続きをやっていくというご説明だったというふうに思うのですが、そうすると、やはりこの道路の幅員が最低でも約１６メートルの道路を造っていくというところで、やはりこうした幅員を広げることで、ＪＲ広町開発の超高層の建物も可能になっていくのではないかと思いますが。","respondent":"多並都市開発課長","answer":"もう一つの、面積につきましては、明日詳しくご説明いたしますが、区有地等につきまして共有地も含めまして、もともと従前が２万１５３３.５３平米だったところが、仮換地後は２万３７３.４６平米となるところです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今回、地区計画の下で容積緩和をして、やはりこの超高層の開発を進めていくということだと思います。その中で、今回のこの道路の廃止や認定というのがやはり、開発を進めていく上でも必要な手続だということか、そこのところを伺いたいと思います。","respondent":"溝口土木管理課長","answer":"そういった中、まずはこの路線の認定をすることによって、品川区が今後しっかり管理をしていく、または今後いろいろまちづくりの進捗に伴って、区域の変更、そういったものを進めながら、また供用開始ということで皆さんに使っていただけるような道路ができる。","id":"exchange-003"},{"speaker":"こんの委員","kind":"質問","question":"参考までに伺いたいと思います。幅員のことですけれども、廃止前とこれから認定するものと、倍以上広くなるというイメージだと思うのですけれども、これだけ大きな土地を活用していくのですから、使い勝手のいい道路を設置していくという考え方はあると思うのです。そこで、この幅員からイメージする車線というのでしょうか。今までは１車線だった。その辺教えてください。","respondent":"多並都市開発課長","answer":"幅員が１６メートルになるということで、その周辺の道路も片側１車線、ですから２車線道路という形になっております。同じような形で、このネットワークを組むということで、片側１車線だから両側２車線という道路になる予定です。","id":"exchange-004"},{"speaker":"こんの委員","kind":"意見","question":"広く、絵から見てもそういうことになるのかなというイメージをしておりましたけど、これは認定の後、もっと詳しく知っていくことになると思いますが、いずれにしましてもここの開発について、今まで、この広い土地をどのように活用できるのか、大井町周辺のまちづくりをどうしていくのかというのは、私ごとであれですが、私も生まれ育った大井町ですので、大変にこの何十年と移り変わりを見てきた中では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、ちょっと分からないので教えていただきたいのですが、この土地区画整理事業施行区域と、黒い中であるではないですか。今度認定する路線のその１というのがありますよね。この黒いところと赤いところの間がありますよね。この高低差、よく分からないのだけど、これも、例えば駅から出たところは、庁舎のほうに来ると２階になるのか３階になるのか。","respondent":"溝口土木管理課長、多並都市開発課長","answer":"今回、区画整理事業の中でも一部は１６３号線の土地の整備とかといったものの区域に入っておりますので、あくまでも出来た道路に、将来形に合わせた形というのをにらんでおりますので。その後に、区域決定という具体的な幅を持たすような、ここが区域になりますよという手続きをして供用開始という手続きになりますので、今回の認定についてはこの間を結びますよということを決めるもので、あと具体的には。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問","question":"では今後、それは我々も気にしていきたいと考えていますけれども、あともう一点だけ。それで、線路の下から入ってくるのは、ここの青いほうは隅切りがあったのだろうけど、今度これ見ると、隅切りではなくカクカクとなっているから隅切りではないような感じになっているのですけど、こういうのはどういう判断があるのかというのを最後に教えてください。","respondent":"多並都市開発課長","answer":"計画している私のほうでお答えします。","id":"exchange-007"},{"speaker":"のだて委員","kind":"確認","question":"１点だけ確認で、この駅前広場のところの形状がいろいろ、カクカクしているのですけれども、これは何かそういう目的というか意図があって、こういった形状になっているのか伺います。","respondent":"多並都市開発課長","answer":"この駅前広場につきましては、今見ていただくと、この１６メートルの道路を真っすぐ右に引いたところ、そこから上側が地上部、いわゆる一般的な道路で、そこから下側というのですか、下の３分の２程度のところのＪＲの敷地内に立体道路を整備する予定になっています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"意見","question":"区有地を利用してＪＲ広町開発を進めるためのもので、これは進めるべきではないと考えますので、反対。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"第４２号議案、令和４年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第４２号議案、令和４年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"羽田空港アクセス線の新駅についてということで、今回、駅をつくる為の検討をするということですが、その目的というのは何なのか伺いたいと思います。今の東山手ルートの工事日程、その辺りのスケジュール感を伺えたらというふうに思います。今回、この補正予算でこの検討経費が出てきたという、なぜこのタイミングになったのか、そのところを伺います。","respondent":"鈴木都市計画課長","answer":"３点ご質問いただきましたが、まず１点目の、委託調査をかける目的ですが、先ほどご説明させていただいて、資料のほうにも記載していますが、現在進められているこのアクセス線の計画につきましては、現在進められている東山手ルート。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回、この補正予算のところで、検討経費が出されたというところですけど、話を聞く中で明らかになってきたということですが、今回、この７７０万円、業務委託をするということで、これは全て、調査は業者に委託をするということになるのか、その辺りも伺いたいと思うのですが、そうした、その中で検討というのはどういったことをされていくのか、もう少し具体的にご説明があれば伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"初めに、他区での新駅の整備状況があるかないかですが、公表されて進められている東山手ルートにつきましては、羽田空港を出発して、その次の駅が東海道線に乗り入れて新橋駅というところで聞いておりますので、その間の駅の設置はないというふうに聞いてありますし。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"以前、品川区内でも西大井駅がこの請願駅でやられてつくられたということをお聞きしまして、その西大井のときの状況など、幾ら区が負担したのかとか、そういったところも含めてご説明いただきたいというふうに思います。今のＪＲのこの３ルートの計画というのは、これは全て実施をしていくというものなのかどうか、３ルートの中で幾つか絞って実施していくということなのかどうかもちょっと併せて伺いたい。","respondent":"鈴木都市計画課長","answer":"それで、一般的に、これは広く、日本全国で新駅誘致、請願駅的な取組みの中で、駅の整備というのは進められているところの事例が多いわけですけど、そうした事例もちょっといろいろ収集をしながら、要望する地元自治体がどれぐらいの整備負担をする必要があるか。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"やはり今、コロナですとか物価高騰というところで、区民の生活が苦しくなっているという中で、こうした大きな金額、やはりそうした区民の暮らしをさらに支えていく、福祉充実をさせていくというためにこそ使うべきだというふうに思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今、コロナ禍の状況というところもご質問の中でいただきましたが、当然、将来的にこの駅の設置要望、整備が、品川区にとって持続可能な発展をもたらすと、利便性をもたらすというところも踏まえて、中長期的なまちづくり、品川区の発展を視野に入れながら。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、住民への被害も多くなってしまうのではないかというふうに思うのですが、いかがでしょうか。この各地の、五反田、大崎、大井町のさらなる活性化を図るためということで、この新駅を設置すると、なぜ活性化になるのか、そこを伺いたいと思います。持続可能な発展をしていきたいということで、そこでもこの新駅がなぜこの持続可能な発展につながるのか伺います。","respondent":"鈴木都市計画課長","answer":"羽田新ルートとの関係性ですが、ＪＲとすると、鉄道、人の輸送を事業として最優先といいますか、そこで事業を行っている企業体ですので、まず、そうした、空港と都心を結ぶというところで計画を打ち出しているということでの事業の説明ですので、私が先ほどご説明したのは。","id":"exchange-014"},{"speaker":"のだて委員","kind":"意見","question":"その持続可能性のところでも、物流は物流で必要なところもあるのでしょうし、この駅を造って、新たなまちをつくっていくということは、やはり土地が限られますので、なかなか、これを永遠に続けていくということは不可能だと思うのです。やはりそうしたまちづくりの考え方というのはちょっと変えていかないと、この持続可能なまちづくりということにはならないのではないかなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"芹澤委員","kind":"質問・要望","question":"何点かまとめてお伺いします。バスが出ていますけれども、やはり今、これから大井町がどんどん活性化しようというところで、直接行けるようになると、よりすてきだなということ。そういった可能性もあるのでしょうかというのを、３点お聞かせください。","respondent":"鈴木都市計画課長","answer":"スケジュール的なところは、非常にタイトなところで行っていかなければいけないということは認識していますが、そこは適宜、ＪＲとはその東山手ルートの件で意見交換等を行っていますので、今回、区がこうした調査委託をかけていくというところは、議会後になるとは思うのですが。","id":"exchange-016"},{"speaker":"芹澤委員","kind":"意見","question":"最後に意見、以前もお話ししているのですが、五反田のりんかい線の乗り入れというのは、当然ホームを多分造る、造らないという話もあって、少し大きな話になると思うので、単純にりんかい線のホームを造るというよりは、こういった新線の大きな動きの中でできることなのかなと思っていますので、ぜひ選択肢の一つとしてご検討いただければと思います。意見で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"単純に、このルートの箇所図を見ると、いわゆるこの３つのルートが重なっている部分、単純に言うと、利便性の向上、区民の方が使える、いわゆる羽田から来る方が乗り入れするのはそうですけれども、区民の方の利便性向上、区民の方が乗るというふうに考えると、３点が交わっている部分が駅として利便性があって、単純に、こういうのを見ると思うわけですけれども、ということも含めると、この物流拠点。","respondent":"鈴木都市計画課長","answer":"それで、この委員会資料の中にあります３ルート、これ、やはりいろいろ３ルート、先ほどのご質問にもありましたが、今回３ルート含めて、駅の可能性をかけたいですが、やはり東山手ルートのより東京寄りのところで、例えば駅を１つ設けてしまいますと、その後の西山手ルート。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問・要望","question":"大きな公園などの周辺の調査もするのですが、いわゆる、先ほども申し上げましたけど羽田から乗ってくるお客様の利用としては、この３ルート、乗ってこられるわけですので、品川区民の利便性向上といったところの、このアクセス、いわゆる、この土地をさらなるまちづくりとして展開をしていくというところまでを構想しながら進めていくというのが一つあっていいのではないかというふうに考えるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だからそういう、周りがこれだけ今動き出している部分があるのであれば、ぜひそういうことも入れていただきたいし、もちろん概算工事費が出てくると、もちろん高いのも出てくるのだろうけれども、それをしっかりどうやって扱っていけばいいのだということを、そこまで入ってほしいなというのが、どちらかというと調査したらその先、そういう人がコンサル的な形で入って事例を調べるのはいいけれども。","respondent":"鈴木都市計画課長","answer":"いろいろ、海を区民が享受できるようにというところも含めて、その動きをつくっていく中で、どうその辺を盛り込めていくのかを含めて、しっかり念頭に置いてこの検討に着手していきたいです。","id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"提案","question":"こういうことも踏まえると、ぜひそういう周りの方の、そういう蒲蒲線なり何なり、東急の人だったり京急の人だったり、そういう方も含めていろいろな提案とか、いろいろな考え方を、今こそ、片方はＪＲ東日本でもう巨大で大きいところなのだから、そういうところではないそういう沿線の人たちからも意見を聞くというほうが、我々品川区民にとっては非常にいいことだと思うので。","respondent":"鈴木都市計画課長","answer":"今現在、東山手ルートが先行しておりますが、西山手ルートについても、非常に、渋谷、新宿とつながっていく路線としては、非常に区民にとっては大きな、有益なルートになってくるですので、今、蒲蒲線のご紹介もいただきましたが、いろいろな広い視点で。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"最後に１点だけちょっとお伺いしたいのですが、土地利用の関係なども調査をしていくというところで、今、臨海部へのカジノ構想などもあるわけですが、こうしたカジノの設置の検討など、そういったことも含めた検討という調査などをされるのか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"臨海部のカジノ、今そうしたことも何か視野に入れてやっているということでは全くございません。","id":"exchange-022"},{"speaker":"のだて委員","kind":"意見","question":"超高層再開発をさらに進めるためのものですし、区の負担も莫大な金額になり得るものだという中で、やはりそれを、暮らし、福祉をさらに充実していって区民の生活を変えていくということこそ必要だと思いますので、反対。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-03","title":"第４８号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第４８号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"進行についてですけれども、この第４８号議案は、今回提出されている、小山三丁目地区の再開発の陳情に関係してきますので、先に陳情審査をしていただきたいというふうに思うのですがいかがでしょうか。","respondent":"長尾建築課長","answer":"私からは、第４８号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例について説明します。配付資料の１枚目をご覧ください。１、改正理由です。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"東中延一・二丁目、中延二・三丁目地区のところで伺いたいのですけれども、今回、壁面線の後退などをやる中で、建て替えもしやすいような工夫が取り組まれておりますけれども、今回こうした地区整備計画の内容になった経緯などを伺いたいと思います。住民とのやりとりというのをどのようにやられてきたのか、そこを伺いたいと思います。","respondent":"大石木密整備推進課長","answer":"今、ご質問いただきました壁面線後退の経緯ですが、こちらの地区ですが、まず（い）地区、主に住居地域になっているところですけれども、こちらは今現状といたしまして北側隣地境界線から ０.５メートル以上という形で制限がかかっております。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問","question":"住民協議会の中で協議をされてきたということで、こうした建て替えもしやすく、防災性も高めるというところでつくられたルールということだと思います。やはりこうしたルールをつくることで、今回の中で、容積率の緩和等、行われているというふうに思うのですけれども、そうした中で超高層のビルができるというものだと思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"武蔵小山についてお答えいたします。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"この西五反田七丁目地区ですけれども、こちらも、ビルの高さですとか計画の規模を伺いたいと思います。今回この西五反田七丁目地区は、ＴＯＣの建て替えというものですけれども、その中でこの容積率をいろいろ緩和して、このＴＯＣの建て替えが進むように、１企業に便宜を図っていくという内容になっているのではないかというふうに思うのですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今回のこの提案の内容につきましては、いわゆる先ほど申しました緑地であったり広場であったり、人々が歩ける公共空間であったりを担保するために、条例として位置づけさせていただいて進めていくというところで、そういうふうにご理解いただければよろしいかと思います。","id":"exchange-027"},{"speaker":"のだて委員","kind":"確認","question":"１５０メートルのビルを建てるということを保障するために、やはりこのルールをつくっていくものだということで、確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"１点だけ、ちょっとよく分からなかったので教えていただきたいのですが、東中延一・二丁目、中延二・三丁目地区の地区計画のところですけれども、この地区の位置で、先ほどもご答弁があった内容をちょっと質問してしまうのですが、この図の、中延二丁目の中と中延三丁目の中の、（い）の部分の中に（に）の部分と、それから（ほ）の部分があって、ここは拡大されている図もあるのですが、いわゆる。","respondent":"大石木密整備推進課長","answer":"その後、検討会やアンケート調査を行いまして、戸別訪問や意見聴取を実施してきたところです。高さの１６メートルのことですけれども、まず、現況の建物階数にちょっとばらつきがございまして、これらが既存不適格にならないように基本的に１６メートルと設定した経緯があります。","id":"exchange-029"},{"speaker":"こんの委員","kind":"確認","question":"そうすると、（に）地区も同じ考え方でという理解でいいのでしょうか。ついここを、単純にこの地図だけ見ると、中延二丁目内はほかのこの黄色い部分、（い）地区の部分もそうしたことが考えられるのではないかと思うのですけれども、ここの部分だけ、そういう（に）の地区として、高さ制限も設けているのはそういう考え方、そういう捉え方でいいのか、理解でいいのか、その辺確認させてください。","respondent":"大石木密整備推進課長","answer":"（に）地区につきましても、先ほど申したとおり、ここももともとの検討開始がとても早くて、それで議論が煮詰まっている、議論をする時間がございましたので、地域の皆様と話しまして、（に）地区についてもこのような制限をかけているような形になっております。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今、土地の値段も高いし、そういう感じでいくと、例えば５０平米だとしても、ではそこに、簡単に言えば建売りみたいなのが建っていったとしても、準防ぐらいは守られているわけだし、それで、もちろん対価とは言わないけれども、そこまでなってなくたってそういうことは守られて、そういう意味では防災上は、というのはある程度担保できるようなものもできてくると思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"東中延一・二丁目、中延二・三丁目地区は、住民ともよく話し合って、建て替えしやすいような良いルールになっていていいと思うのですが、武蔵小山賑わい軸地区、西五反田七丁目地区は、住民を追い出し、開発業者の利益のためにこの税金を投入して、超高層再開発を進めるための手続きですので、全体としては反対。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]},{"id":"topic-04","title":"長期優良住宅に関わる認定申請手数料の追加等","agenda":"長期優良住宅に関わる認定申請手数料の追加等","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それと、容積率緩和の申請の新設をされるということで、この手数料が幾らになるのか、その金額を伺います。その中でこの手数料が、ほかの仮設建築物ですとか、仮設興行場等の手数料も変更になるという、項目の中に上がっているのですけれども、これはどういった変更なのか、金額等が変わるようであればその金額も伺いたいと思います。","respondent":"長尾建築課長","answer":"その下の５番から７番については、こちら優良宅地、優良住宅、良質住宅はもう削除になりますのであれですけれども、優良宅地と優良住宅についても、法の項ずれと条文削除に伴って記載内容を修正するものでありまして、金額の変更は発生しておりません。","id":"exchange-033"}]},{"id":"topic-05","title":"令和４年陳情第３７号、リニア中央新幹線の調査掘進の大幅遅延","agenda":"令和４年陳情第３７号、リニア中央新幹線の調査掘進の大幅遅延","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、調査掘進が北品川の立坑から進められているわけですけれども、あそこから区内を横断するような形で、戸越公園や旗岡八幡の下を通って大田区へ抜けていくわけですが、その調査掘進が進んでいない現状、理由ですね、そこをＪＲ東海のほうから区として聞いているのかどうか伺います。それがいつまでに終わるのかを含めて、事業者から説明を受けていましたら伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"そこに現場の写真も、ホームページ上で公表しているというところで、こうしたことを現在行っているといった状況は、ホームページで公表しているというような認識です。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"調査掘進が進んでいない理由のところですけれども、掘進の効率が上がらないことがあったということですが、なぜ上がらなかったのかというところは、何か説明を聞いているのでしょうか。伺います。それと、調査掘進がいつまでかというところもまだ未定だというところでいきますと、このシールドマシーンの点検はいつまでなのか、説明を受けているでしょうか。伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今の点検の時期ですが、点検をしながら今確認している状況だというところで、いつ終了するかという報告は受けていないという状況です。掘進の効率が上がらないということも、今シールドマシンを点検しているというところで、今調査、点検をして原因を追及しています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、点検をしながら原因を探っているということですけれども、報道ベースでは何か土の取組みがうまくいかなかったというところは少し出ていたのですが、やはりそうした、今原因不明で止まっているということなのか、そこを確認させていただきたいと思います。こうした下で説明会を行っていくことが、やはり必要なのではないかと思うのですが、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"ですから、品川区としましては、区民の不安払拭、こちらのほうを丁寧に努めていっていただきたいといったことは引き続き求めていくとともに、一方で具体的な対応、または時期などについては、事業者であるＪＲ東海が責任を持ってやるべきというふうに考えてあります。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"具体的にはＪＲ東海の責任だということですけれども、そういったことで、やはり住民の不安に応えるということが必要だと思うのですが、いかがでしょうか。この資料の中で、家屋調査なども行っていると。昨年の８月から調査を実施しているということですが、現在、これがどこまで進んでいるのか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"区民の不安の払拭に努めるといったところですが、ＪＲ東海のほうからは、区民の不安払拭に丁寧に努めていきたいということを聞いているというところ、または今現在、より今後安全にシールドマシーンで掘進をしていくというところで、自社用地内で点検を行っているというところ。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"今やはり、先ほど来言っていますけれども、予定どおり進んでいないということと、同じシールドマシンの工事で陥没事故なども起こっているというところで、住民の方が不安を抱えているということは事実だと思いますので、やはりそういったところで説明会、区としても、この住民の不安を取り除いて安全・安心にしていくという面でも、区として求めていくということが必要ではないかなと思うのですが。","respondent":"中道まちづくり立体化担当課長","answer":"一般的なシールドの説明会はどのくらいなのかといったところと比較しますと、まず最初に全体の工事説明会をやって、仮設の工事をする前に１回やって、シールドマシンが発進するときにやってといったところが一般的に、丁寧にやっても３回なのかなというふうな認識です。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりそうした事故が発生したことで、そのための説明会などもやっているわけですけれども、そこでより丁寧な説明を行っていくということが必要だと思うのですが、その認識をぜひ改めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"中道まちづくり立体化担当課長","answer":"もちろんそこは区は認識していないですけれども、やはり区民の方に足を運んでいただく、その場で一定程度の情報量がないと、説明会、えっ、これだけの情報なのかというところで、そのようなものは事業者が一定程度。","id":"exchange-039"},{"speaker":"芹澤委員","kind":"意見","question":"一方で、ただ今回このスケジュールの遅れというものは、何か効率的にうまくいかなかったというところで、そこの情報の提供が必要なのだろうと思いますが、住民説明会というように、ある意味やり方を指定してしまうと、先ほどお話しいただいたように、場所の確保をして、周知をしてというように、一定程度期間も経過してしまいますから、そのような意味でいうと、このリアルタイムな情報が必要な今回の事案と。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"こんの委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。不採択と考えます。そうではなくて、やはり広く皆さんに情報提供をしていただきたいですし、不安払拭のためには今どのような状況なのかという説明を丁寧にＪＲにはしていただきたいというところから、今後の取組みについて４点書かれていますので、こうした中で、しっかりその説明をしていただくよう区からお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。説明会で示されたものも予定どおりに進んでいない理由や、住民の不安に応えるために説明会を実施することは必要だと考えます。説明会だけでなく広くというお話もありますが、そこで説明会を否定する必要もないので、やはり様々なところで情報提供していくべきだということで、この説明会も実施すべきだというふうに考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"この中で、やはり１つ重要なところは、住民の合意がされているのかということだと思うのです。ここで、陳情の中にも書かれておりましたけれども、地権者数などをちょっと確認させていただきたいと思うのですが、第１地区の総会の資料の中身が書かれておりますけれども、その中で地権者数などにちょっと相違があると。","respondent":"多並都市開発課長","answer":"１番目の地権者数の数の違いと先ほどの陳情の中のお話ですけれども、まず議会等でご答弁させていただいたり、区のほうからご説明するときは、土地所有者の方というのは、売られたりしたら変わる可能性がありますので、必ずその一権利という形でカウントさせていただいて。","id":"exchange-043"},{"speaker":"のだて委員","kind":"意見","question":"この準備組合の総会の資料のところの説明、今何か権利が２つある方は１人にしているという説明だったのですが、すみません、ちょっと今すぐに理解できなかったので、もう一度分かりやすくご説明いただけたらと思うのですけれども、まずそこを。","respondent":"多並都市開発課長","answer":"土地の権利をお持ちの方が何名ですという説明をいつもさせていただいています。","id":"exchange-044"},{"speaker":"のだて委員","kind":"意見","question":"分かりました。そういったところで、加入者は今ご説明があった加入者の数だと思うのですけれども、やはりその加入者が、この再開発の計画に賛同しているとも限らないというところがありますので、この再開発計画に賛成している、反対している、この数というものはどうなっているのか、その権利の別でお答えいただけたらと思います。","respondent":"多並都市開発課長","answer":"そのときの１つの目安としては、区のほうに１つの、最初に地元の方から、準備組合の組織から区のほうに都市計画の提案が、企画提案というのですけれども、企画提案を渡されるときに、その準備組合の中で総会が開かれて、その中でどのような議決があったかということで。","id":"exchange-045"},{"speaker":"のだて委員","kind":"提案","question":"それで、ほかの再開発の計画ですけれども、国に補助金をもらうために出す、いわゆる予算要望書というものがありますが、その中に都市計画決定時の賛否の数というものが、黒塗りでしたけれども、書かれて、欄があるというところで、そのようなことであれば、この武蔵小山の計画は都市計画決定をされたわけですから、その時点での賛否の数というものは今分かると思うのですけれども。","respondent":"多並都市開発課長","answer":"予算のことは、恐らく国への要望書の書式の中での賛同率というのですか、何かそのようなご質問かと思うのですけれども、これにつきましては、品川区といたしましては、組合設立認可をした後に、これから事業を行うという段階で予算要望をすることですので、必ずその。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問・要望","question":"まだ、この予算要望をしていないので空欄というのは、そうすると、ほかの計画地のものでは、その都市計画決定時のものが書かれていたわけですけれども、それは要望した際に、つまりこの武蔵小山のものでも書き込まれるという、そこのところを確認させていただきたいということと、それがいつ頃になるのかということをお聞きしたいと思います。","respondent":"多並都市開発課長","answer":"要するに予算要望は、もう一度申しますが、組合認可後に事業が実施されてから予算要望を、事業が実際にお金がかかっていることになるので、そこでの要望になります。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこの欄があるということは、そこでやはり確認をしているということではないかなと思うのですが、そこをちょっと確認させていただきたいということと、あと、次の質問にも移りたいと思うのですが、商店街の中でもこの進め方の問題が、今回陳情にも書かれておりますけれども、商店街のところでどういった形で話をされてきたのか、そして今回。","respondent":"多並都市開発課長","answer":"文書でも確認をしていると。商店街にお聞きしても、組合員の方に説明しながら進めているということで、総会などいろいろな機会を捉えながら説明しているということでお聞きしているところで、適切に進められているのだろうということで理解しているところであります。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"適切に進められていると言いますけれども、そうした中で、今知らない人もいるという声まで上がっているという状況ですので、やはり今回再開発の計画、商店会の両側でやられる計画ですので、既に陳情の中ではアーケードが一部破壊されたということで書いてありますが、そうしたアーケードなどもある中で、商店街の皆さんとやはり合意をしっかりつくっていくということが必要なのだろうと思いますので、今回。","respondent":"多並都市開発課長","answer":"商店街のほうでも、組合員の方にご説明しながら進めているということをお聞きしていますので、このように確認しているところです。","id":"exchange-049"},{"speaker":"のだて委員","kind":"質問・要望","question":"この中で、やはりこの再開発の計画自身に反対している人が多くいらっしゃると。それがなぜかといえば、やはりこうした商店街を壊されるということと、やはり住民の皆さんも、住み続けたいけれども住み続けられない再開発が進められているということがあると思います。こうした住民の暮らし、あるいは商店街を壊す、こうした再開発を進めていくべきではないと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"これまでいろいろ皆さんでご検討いただいた成果を踏まえながら、よりよいまちに進んでいく計画ということで、これからも進んでいくということで考えているところであり、区といたしましても、よく地域のご意見をお伺いしながら、よりよい形にしていきたいと。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"この再開発計画が成果というようにおっしゃるのですけれども、やはりこれまで住み続けてきた人たちの暮らしが壊されるということは解決していないと思うところです。そういった事業を区として推進していくということは、自治体のやるべきことではないと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"繰り返しになりますが、このまちの課題を解決するために地域の方が考えられた計画、また、区としてもそれを受け止めさせていただいて、より実現していくということで、そのような形で進めていくものだと考えておりますので、区としても。","id":"exchange-051"},{"speaker":"のだて委員","kind":"質問","question":"区は進めていくというのですけれども、賛同していない方もいるわけですし、この準備組合に参加をしていない人もいるわけです。そうした下で、この事業の合意ができているということは言えないと思います。少なくとも丁寧に再度説明会を開くということなどをやっていくべきだと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"今後にいたしましても、法令に基づいて、次は組合設立認可という手続きになりますけれども、今後そのような形で進めていくべきと思っておりまして、特段、今ご要望があったような住民説明会は必要ないと考えているところです。","id":"exchange-052"},{"speaker":"のだて委員","kind":"質問","question":"やはり住民が暮らしていける選択を取れないというものがこの再開発ですから、そうした下で、この間言ってきた下で品川区は選択できる、きちんと選択が保障されていますよという答弁などをしておりますけれども、この間の予算特別委員会の総括質疑の中で都市整備推進担当部長が、地域内の各権利者がそれぞれ権利を主張しているだけではまちは何も変わらないということをおっしゃいましたが。","respondent":"多並都市開発課長","answer":"繰り返しになりますが、地域への周知につきましては、これまでも事業者の説明会、また法令に基づく都市計画の説明会など、地区内の方、または区内の方々に説明させていただきながら……。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、区はこの計画によって、住民の生活が壊されるとは思っていないのか。伺います。","respondent":"多並都市開発課長","answer":"事業に際しましては、憲法に基づきまして、補償という形が法律上ありますので、また地域の方々お一人おひとりの生活についてお話合いをしながら、そのような形で、今度は組合設立後の権利変換の手続きのときになりますけれども、それに向けて。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで幾つかお聞きしたいのですが、確認をしたいのですけれども、陳情の中に、まず歴史財産の話が書かれておりました。環境課長の答弁が、アセスの評価書に関わってですけれども、虚偽答弁ということですが、その事実も確認させていただきたいと思います。問題ないのですよということが入ってきたということですけれども、実際不可分というものはどのようなもので、適切なのかどうか伺います。","respondent":"多並都市開発課長","answer":"このようないろいろなご意見も踏まえて、この審議会の中で答申されて、その評価につきましては、この書面を見る限りの言葉で申しますと、本事業の評価書案における調査予測および評価は。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"評価書については専門家の意見ということでしたけれども、やはりこの、特に朗惺寺の歴史のところは、やはり満州から帰ってきた方たちが武蔵小山商店街をつくったというお話も聞いております。そうした歴史をしっかり守っていくということが必要だと思いますので、区としてもそういった形で進めていっていただきたい、守っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。もちろん、先ほど来お話があるとおり、賛成、反対あると思います。それ以外の外圧で、区が中止させたりなどということはやるべきではないという思いで、まず、この第３２号については、特にこの戦争であったり、人口減少であったり、地域合意とは全く関係ないお話というものも出てきていますので、こちらはまず不採択でいいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"理由は、全体にも関わることですけれども、いわゆるこの合意形成というところでは、今芹澤委員のほうからもありましたとおり、賛成、反対、両方の意見が、やはりどの問題についてもある、そこを区としても、オブザーバーとしてサポートしていただいているというところもありますが、基本的には、その地域の方々の合意形成は、地域の方々の考え方で進めていくということが大前提だと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。住民の合意を得ないまま進められている、この小山三丁目地区の中止と、商店街が準備組合に加入した経緯と議事録開示についての趣旨はよく分かりますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。内容としてミスリードがあったというようなお話だと思いますが、先ほどお話しいただいたとおり、人数についても事実を述べただけでありますので、特に問題なかったと理解をしています。不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。不採択を主張いたします。この誤解を招く賛同数というところのご説明を、先ほど質疑の中で、課長から回答についてのご答弁があったものと理解をしておりますので、よって不採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、趣旨採択を主張します。私たちは都市計画決定にも反対をしましたし、小山三丁目地区は進めるべきではないと考えていますので、趣旨採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"芹澤委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。ずさんな地権者管理というようなお話ではありますが、先ほど来お話があったように、定義が若干違ったり、そもそもの権利者異動であったりなどというところで、特にずさんな作業があったというものではない。特に強引な戸別訪問があったということも事実として確認できませんでしたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。正確な情報を伝えるべきですし、訪問される側が求めていることですので、しっかり聞くべきだというふうに考えますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"芹澤委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。先ほど答弁もいただきましたが、特に虚偽答弁があったり、問題があったりということは確認できませんでしたので、不採択でお願いします。１点、これは個人的な話ですけれども、自民党だったり、議長を名指しにして、適切でないというような記載がわざわざ書いてありますので、ここは全く私同意できませんので、抗議をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。不採択を主張いたします。環境アセスは、都の審議会などで審議をされて答申をされているということですので、そちらも見ていただくと、そうしたことが分かるのかなということも理解できましたので、これについては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほど来お話ししているとおり、地域合意で進めていく事業だと思っていますので、区長や議員が勉強し直すから撤回するというようなお話ではないかと思っていますので、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。不採択でお願いいたします。専門家が審議をされたものですので、区として、それがいいとか悪いとか判断できない、このご答弁は理解できますので、よって不採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"のだて委員","kind":"確認","question":"本日結論を出すということで、趣旨採択です。環境悪化の計画を中止することや、区がデータ改ざんや捏造がないように確認するということ、この趣旨はよく分かりますので、趣旨採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。この担保するというところは、区としても難しいところだと、私も先ほどの課長の答弁で、そのように理解をいたしましたので、不採択といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。約束をほごにされれば、やはり住民の生活が壊されることになりますので、本組合が責任を持って対応すべきです。それを区のほうでもしっかり指導していくということが必要だと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"のだて委員","kind":"確認","question":"確認ですけれども、陳情の中に、この北口の停留所が迷惑になっているということで書いてあるのですが、そのことがどうなのかというところを伺いたいと思います。そして今の利用状況、しなバスの利用状況がどうなっているのかというところも伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"陳情にあります車両の通行への支障というお話ですが、検討段階で建設委員会のほうでもご報告したのですけれども、当初水神公園の横の一方通行のところをバスルートとして設定していたわけですが、警視庁協議の中で、一方通行といえども。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"支障があるという区民の声はないということですが、この陳情では支障があるということで出ておりますので、その辺りはちょっと受け止めて、今後の検討をしていっていただきたいと思うのですけれども、利便性のところは、この北口でも東口と劣らないというお話ですが、やはりここで降りて、どちらに行けばいいのか分からないということもそうですし、やはり同じ東口であれば。","respondent":"鈴木都市計画課長","answer":"東口への設置については、冒頭ご説明させていただいたとおり、区としても、この設置に向けた協議を検討段階で続けてきたわけです。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問・要望","question":"区として協議を進めてきたということは知っておりますけれども、東口のところでどうにかやり方があるのではないかと思いますので、ぜひ、ここは引き続き努力を続けていただきたい。設置に向けて頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。今いろいろお話がありましたが、東口も検討されているということで、これからアンケート等もどんどん取っていただいて、ある意味東口に固定することもなく、いろいろなところのルートも含めて、停留所も含めて、よりよいものにしていただければというふうな思いです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"こんの委員","kind":"質問","question":"不採択です。ですが、この先どういったことができるかということも考えてくださっているというご答弁をいただきましたので、それは非常にありがたいというところです。なぜかというと、あそこはほとんど交通量がないところなのです。ですから、先ほど言ってくださった、その位置が分かりやすい改善を図ってくださるということですので、どうぞそちらを進めていただければと思います。お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。空間的・時間的スペースがないというご説明が出ていたのですけれども、やはり利便性を向上していくということは重要なことですし、それに向けて引き続き知恵を絞っていただきたいと思いますので採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"区に寄せられた問合せ件数などを出していただきましたけれども、区はこれで区民の実態をきちんとつかめているというお考えなのか、伺いたいと思います。陳情のほうでも書かれておりますけれども、やはりそうした実態をつかんで公表していくということが必要だと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"調査の実施等につきましては、これはもう本当に国策であり、国の事業であります。国の責任において実施されているものでございまして、実施の必要性も含めて、国が判断していくものというふうに捉えているものです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"国のほうで判断するものだということですが、やはり区民が大きな被害を被っているわけですから、それを明らかにするために、区としてもやったほうがいいと私は思いますけれども、まずは国が事業者ということで、国に求めるということも必要だと思うのですが、いかがでしょうか。それで、港区では調査が一定行われたわけです。","respondent":"鈴木都市計画課長","answer":"区の受け止めとしますと、日々区のほうに寄せられている区民の声、それを今、国にしっかり届けているわけですが、港区でもそうしたことが行われたというような認識です。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"調査ではないというお話でしたけれども、私も不十分な点はあると思うのです。これを港区が行った目的が、この意見を集約して国に伝えると。騒音対策や新飛行ルートの固定化回避の検討に役立ててもらうということが目的として書かれておりますけれども、そのような意味では、品川区としても同様に行っていくということもできるのではないかと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"港区の意見募集といいますか、そうしたところで委員のほうからも、最終的に国に、港区のほうでは意見を取りまとめ国に届けたというところで、その中で騒音環境軽減に向けた取組み、あるいは落下物対策、固定化回避の検討に役立ててほしいと。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもにもきちんと答えてもらえるようにしていくということで、やはり区民の被害の実態を把握していく、こうしたことが必要だということで今回も求められていると思いますので、やはりそうした調査もぜひやるべきだと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"これが、今区が実施すべきことだです。やはりそうした、影響の調査ですとか、そうしたところの実施の必要性、こうしたところは判断も含めて、国が国策、国の事業として、国が責任を持って、判断も含めて国が行っていくべきです。","id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"もう実施されて２年と３か月ほど過ぎているわけですから、やはり区民の実態を明らかにしていくということが私は必要だと思いますし、区としてもそうした認識にぜひ立っていただきたいということを強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後にちょっと１点だけ、陳情に書かれている、委員からも国がぜひ実態調査をやっていただきたいという発言があったのですけれども、それが自民党からあったと思ったのですが、そのお考え、今も変わらないのかどうか、そこをちょっと、ぜひご説明いただけたらと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"石田（秀）委員","kind":"質問","question":"それを届けている。固定化回避については、本来であれば、我々でさえ第５滑走路の計画も新聞等で発表されたり、それでは、どのような形だったら、この固定化が回避できるのですか、国交省の、今までの調査の様々なご意見は伺った。ここで言う話でもないけれども、第５滑走路ぐらいは新聞に出たから、今ここで言ってもいいですが、それ以外の我々の考えも述べたりして意見交換もしてきた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"のだて委員","kind":"質問・要望","question":"やり方はいろいろあるというお話もありましたけれども、ぜひ会派の中でも検討していただいて、この実態調査、国に求めたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"芹澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。理由は先ほど石田委員からもお話しさせていただきましたが、あくまでもこれは国の事業でありますので、国が責任を持って進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。不採択です。先ほどご答弁いただいたことを理解しているということが１つと、あと人への影響を含めた調査、これは否定するものではありませんけれども、先ほどご答弁いただきましたように、様々な区民の方のご意見、それはこうした陳情の内容の調査に関するような、そうしたお声も、国のほうにしっかり届けてくださっているといったこともご答弁でありました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、採択を主張します。様々なやり方があるかもしれませんが、やはり区民からこういった陳情も出されているわけですから、それを実施していく、１つの方法としてやっていくということは必要であると思いますし、否定するものでないということであれば、そうしたところを区議会としても後押しをしながら、実態調査を求めていくということが必要だと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":64912,"voices":269}},{"id":"r04-20220627-9","meetingId":"r04-cm06","date":"2022年6月27日","dateIso":"2022-06-27","committee":"文教委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"子ども未来部所管のほうで所管質問したいのですが、これは後のほうがいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"６月２４日、西本議員が保育園需要と区立保育園の今後の在り方について質問されましたけれども、今年度、区立保育園の在り方について検討する中で示していくという答弁でございましたが、何をどのような形で検討するのか、スケジュール等も含め、もう少し具体的に伺いたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"私は、６月２３日の渡部委員の質問で、品川区の教育について、まちづくりなどで、子どもの人数が増えてしまった地域についての質問のところの、学校選択制の部分で、暫定的な学校選択制の停止と、もう一つ何か理由をお話しされていたので、そのもう一つの部分を伺いたいのと、暫定についての理解ができなかったので、もう少し詳しく知りたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"手当の支給の実態ですけれども、修学旅行や対外運動競技引率等に従事した場合というのは、今回金額が改定されるわけですが、一律にこういう手当というのは支払われているのかどうか、伺いたいと思います。昨年の今頃の委員会で審議して議決したわけですが、そのタイミングについて伺いたいと思います。","respondent":"中谷指導課長","answer":"それから最後に、義務教育等教員特別手当の見直しをしたタイミングというところなのですけれども、昨年度に統括副校長級の設置をしましたところでして、これを受けて、今回、いざ進めていくに当たりまして。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問","question":"せっかくの議案審査なので、改めて、区の固有教員が何名いるか教えてください。東京都のほうだと、普通の教員の方がいて、その上に主任がいて、主幹教諭の先生がいて、たしか副校長の先生までいらっしゃると認識しているのですが、改めて、今、安藤委員が質問されて、統括副校長のことが出てきたということは、今、統括の副校長職の方がいらっしゃるのかどうか、もしくは上がれそうな方がいるのかどうか。","respondent":"中谷指導課長","answer":"そして最後に、３つ目としまして、統括副校長級のその後の行方ということなのですけれども、設置を昨年度果たしまして進んでいるところなのですが、昨年度の時点でこちらにふさわしい方というのは残念ながらおりませんでしたので、今年また募集していく予定ではありますが。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"できれば、一般の教員が何名で、主任が何名でとか、働かれている年次とかで、主幹の方、副校長の方とかも教えてほしかったのですけれども、それは後でもいいのですが、あともう１個大事なのが、品川区で働いていただいて校長先生にまでなっていただきたいという思いが私たちなり区民なりにある中で、東京都の制度の中で動きますから、その辺がなかなか難しいという話も当時頂いていたと思うのですけれども。","respondent":"中谷指導課長","answer":"こちら、制度的な部分については、前回話題になったとおり、これ以上、上にはできないというところがありますが、統括副校長になっていただいた方のお仕事の内容については、校長と同等もしくは東京都の校長先生がやっていただいていること以上の。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問","question":"非常災害時等の緊急業務ということは分かるのですけれども、引率指導業務または学校の管理下において行われる部活動の指導業務に従事した場合で、当該業務が心身に著しい負担を与える程度のもののときに支給するということなのですけれども、どういった想定がされているのかということを伺いたいというのが１つです。","respondent":"中谷指導課長","answer":"修学旅行もその意味で考えていただくと同様という考えになるのですけれども、もう一つの非常災害時の緊急業務については、こちらも終日に及ぶ程度ということで、日中８時間という数字が出ているところなのですけれども、具体的にこちらについては。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"結論は、支給の額は１万６,０００円ですね。過程をもう一回、お伺いしたい。それから、これは東京都の教育委員会だから、２３区と、あと、いわゆる市区町村ですか、あわせて６２、ここら辺が全体的に一律なのか、区で、ある意味で地域実情に合わせて独自に決定されているのかの結果なのかということ。ちょっと多いですけれども、確認させてください。","respondent":"中谷指導課長","answer":"金額についてのご質問なのですけれども、今回１万６,０００円を最大の額ということにしていますが、こちらの条例が通りましたら、この後、規則でつくっていく予定ですが、細かいところでご紹介すると、今、この１万６,０００円という最大の額は、非常災害時の緊急業務における。","id":"exchange-008"}]},{"id":"topic-02","title":"令和４年陳情第３４号、ゲノム編集トマト苗の無償提供を受けないことと、学校給食からゲノム編集食品を排除することを求める陳情","agenda":"令和４年陳情第３４号、ゲノム編集トマト苗の無償提供を受けないことと、学校給食からゲノム編集食品を排除することを求める陳情","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"なかなか難しいというご意見も分かるのですけれども、やはり陳情理由の中にもある、栽培によってゲノム編集食物が自然界に流出することと、子どもたちが食べていってしまうことについては、保護者の一人としてもとても不安を感じておりますので、この陳情にはぜひ皆さんに賛成していただきたいということと、またいろいろな議論がされたらいいなと思います。質問になっていなかったですね。ごめんなさい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"安藤委員","kind":"確認","question":"質問なのですけれども、先ほど説明があったのですけれども、区のゲノム編集食品についての現状認識についてもう一度確認させてもらいたいのですが、学校給食から可能な限り避けるという立場に立つのでしょうかということを伺いたいのと、遺伝子組換え食品についてはそういうふうに今対応しているということなので、そういう対応をすべきだという立場なのかというのを伺いたいと思います。","respondent":"勝亦学務課長","answer":"そういった意味では、ゲノム編集技術に関しましても、人為的に遺伝子に手を加えて切断しているという、少し事象は違うのですけれども、類似の技術であるということで、可能な限り避けるという、当面はそういった考え方がよろしいかなと考えています。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。そうですね、新しい技術ですし、やはり食品の安全に関してすごく慎重になるべき立場なのが学校だし行政だと思いますので、そうした対応をぜひお願いしたいと思います。この陳情についても、そういう対応を求めているということだと私は理解しておりますので、非常に理解ができる内容だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"そもそも個人や企業から、学校の食材にこういうのを使ってねというような寄附の申入れは今まであったのか。例えば友好自治体とかだったらいろいろそういうのはあるのかなと思うのですけれども、実際どうなのでしょうか。","respondent":"勝亦学務課長","answer":"そういった意味では、品川区の区政ですとか、そういった地域の産品、交流といったものを知っていただく目的で頂いているものです。それ以外で食品という形で頂いている事例は、基本的にはないと認識しております。","id":"exchange-012"},{"speaker":"渡部委員","kind":"確認","question":"確認させていただきました。先ほどの課長からのご説明で十分だと思いますし、引き続き可能な限りというような表現の中で、ずっとなさるということが大事だと思いますので、その確認だけさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"松澤副委員長","kind":"質問","question":"たしか学校でたまに、低学年のうちの子どもが持ってきて、パパ、リンゴという形で、家の中で洗ってそのままがっと丸かじりしてしまうという、すごく楽しそうにやっているイメージが強くて、うちなんかは子どもが多いので、この日は全部リンゴかみたいな印象があったのですけれども、先ほどのご答弁で友好団体というのがありましたけれども、そういうリンゴなども、教育委員会でしっかりと許可を得て。","respondent":"勝亦学務課長","answer":"ただ、給食の食材として、そういった一企業の方から寄附等を頂いて、そのまま給食に使うという事例はないと考えています。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すです。なので、それ以上の対応をここで教育委員会に求めるということはないだろうなと。他の委員のお話を聞いても、それ以上踏み込むということは、それは、教育委員会もゲノムについては素人でしょうし、私たちも素人だし、国の公式見解にのっとって、これからも適切に保護者・子どもたちの心理・心情に寄り添って対応していただきたいというお願いも含めて、意見を申し述べて、不採択で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、これは採択だと思うのですけれども、区教育委員会の説明も頂きましたが、決してこの内容と矛盾するものではないですし、品川区の場合、学校給食というのが、保護者とも連携しつつ、かなり独自に進化させてきたというか、そういう伝統があるというか、すごくこだわってきている事業の１つだと、教育活動だと思いますので、やはりそうした立場でしっかりと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"結論を出すで、賛成です。先ほど説明の中で、科学的な面と保護者の心情というところがあったのですけれども、科学的な面でも、まだまだきちんとした調査がされていないというか、安全性の確保がきちんとされていないゲノム編集については、排除したいという保護者の気持ちはとてもよく分かりますし、本来であれば、表示義務についても、国に対して区としてきちんと求めてほしいと本当は思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"６月２４日、西本議員が、保育園需要と区立保育園の今後の在り方について質問されました。今年度、区立保育園の在り方について検討する中で示していくとのご答弁でしたけれども、今年度、何をどこで、どのような形で検討するのか、スケジュール等も含め、もう少し具体的に伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"に戻りまして、(3)第４２号議案、令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"に戻りまして、(3)第４２号議案、令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"子ども未来部のほうですけれども、補正予算の３事業について、補正予算を組んだそもそもの目的なのですが、先ほど長期化するコロナでという話もありましたが、今、家計を直撃している物価上昇などの関係等もやはりあるのでしょうかというのを伺いたいと思います。対象が、子育てサポート等のほうは１歳・２歳なのですが、この理由について伺いたいと思います。伺いたいと思います。","respondent":"染谷子ども家庭支援センター長、飛田子育て応援課長","answer":"対象の１歳・２歳につきましては、物価高騰自体は全ての世帯に影響しているものとは思いますけれども、区としましては、１歳・２歳について、食料費、子どもの衣服等の子育てに係る家計について、世帯主の年齢が比較的若い世帯。こちらの対象の方なのですが、ひとり親家庭医療証を郵送する際に、一緒にこちらの食品配送の希望の申請の調査をしました。そちらの方々で希望された方が４２０名ほどおりましたので、そちらの方に食品を配送するものとなっております。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"来年度についても、国の交付金の有無にかかわらず、品川区として、区教育委員会として、給食費の値上げにならないように措置すべきだと思いますけれども、今の時点でのお考えを伺いたいのと、あと、保護者の自己負担と給食の質を連動させる、今の受益者負担のような考え方を、何で憲法で無償と定められている義務教育の給食なのに、導入されるのかというのがやはり理解できないところがありまして。","respondent":"飛田子育て応援課長、染谷子ども家庭支援センター長、勝亦学務課長","answer":"今回の募集期間は、令和３年１２月１６日から令和４年１月２３日で、今回、しあわせ食卓事業では１年間配送しますよということで。もう１点、子育てサポート商品券事業につきましては、対象は家事育児支援用品購入支援と同様の１歳・２歳児という形にはなってありますけれども。こういった補助につきましては、今後の物価の上昇ですとか、子育て世帯の方の経済の状況ですとか。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひそういう発信も区としてしていただきたいなと。これは要望です。そこら辺をつかむ努力をしていただきたいと要望しますし、それについての考え方がもしあれば、最後に伺って、終わりにします。","respondent":"飛田子育て応援課長","answer":"こちらは寄附の中での食品配送というところなので、その辺の周知の仕方等では、ホームページ、また、広報等で行っていきたいと考えています。","id":"exchange-021"},{"speaker":"田中委員","kind":"確認","question":"先ほどのご説明でもよく理解できなかった部分で、ゼロ歳児についてはなぜ対象にならなかったのかというところで、ほかにサービスや支援策があるのかというところを確認したいということが１点と、あと、子育てサポート商品券事業も家事支援用品購入支援事業も、どちらも申請と申込みなのですよね。一律配布、なぜプッシュ型にできなかったのかというところを伺いたいと思います。はそこまでお願いします。","respondent":"染谷子ども家庭支援センター長","answer":"子育て世帯への家事支援用品購入支援、それから子育てサポート事業につきまして、なぜ対象が１・２歳なのかという部分につきましては、まず家事支援用品購入支援につきまして、都の家事育児ヘルパー等利用助成という既に実施している事業の中で。","id":"exchange-022"},{"speaker":"田中委員","kind":"確認","question":"今のご説明で何となく分かったような分からないようなというところだったのですけれども、ゼロ歳児に対する保健センターの出産応援事業の１０万円の部分については、当事者の方たちから申請方法とかが不明だったという声もあって、実際にまだ手に届かないといった声も聞かれている中で、この２つの事業についてはどういった周知方法がされるのかというところと、聞きたいのは、やはり漏れがないように。","respondent":"染谷子ども家庭支援センター長","answer":"対象の方への周知方法につきましては、広報紙、ＳＮＳ、ホームページに加え、今後転入をされる方につきましては、戸籍住民課、地域センターなどの転入手続の際にチラシを個別にお配りするような形で、漏れのないように周知を図ってまいります。","id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"次は、しあわせ食卓事業について伺いたいと思います。当事者の方に、何が届くと本当に助かるのかといったようなアンケートはとられないのかというところをまず確認したいと思います。事業者選定が７月から８月で、８月末に事業者決定ということだったのですけれども、選定の視点をどのように持つのかというところを伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"すぐ簡単に、子どもと一緒に料理ができるような中身も一緒に組んでやっていますので、そういうところも踏まえて業者選定ができればと考えています。送られる内容も食を中心として、また考えていきたいと考えています。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の補正についてはよかったなと思ったのですけれども、たしか一般質問の答弁の中でも３月までということで、先ほどの質問にもあったのですが、今後の状況を見て判断していくということだったのですけれども、多分そんなにすぐに景気がよくなるという言い方はあれですか、そういうものではないと思うので、１２月の補正ぐらいでまた補正として示されるのか。","respondent":"勝亦学務課長","answer":"給食に関してお答えいたします。検証、今後の考え方です。今回、補正でお認めいただきますと、２学期、３学期、年度内は全て１食１５円、中学生２０円というものを適用したいと考えておりますので、今後については来年度予算の検討の中で研究していくものかなと考えています。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"今の給食のところは分かりました。しあわせ食卓事業のところなのですけれども、こちらの周知も、まだまだ知られていない方がいるので、そんな事業があったのかという声を聞くときがまだあるので、これからの周知方法、より当事者の方に届くように、周知の改善など、どのように考えているか、伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"今回のしあわせ食卓事業につきましては、１２月にひとり親家庭へ医療証を各家庭に郵送しています。そちらをもう一度１２月に行いますので、そこでまた周知をしまして、そのほかにも、広報またはホームページ等でも引き続き周知を図っていきたいと考えています。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"ですから、そういう専用サイトを作ってやるのだけれども、先ほど課長のイメージの中で、ロボット掃除機とか食器洗浄機とかというお話があったのだけれども、場合によっては、例えば高額のものＡとＢとかに分けておいて、たすきがけのように、こっちから１品、こっちから１品とかにしたほうが、お釣りがどうしたとか、ちょっと値段がとか、私ちょっとしか使っていないからもったいないわとか、面倒くさいから。","respondent":"染谷子ども家庭支援センター長","answer":"先ほど頂きましたたすきがけ、組合せといった考え方につきましては、今後、事業を進めていくに当たって、事業者とも相談しながら検討を進めてまいりたいと思います。","id":"exchange-027"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、第１弾で、私たち公明党も、国においては１兆円規模でこういった物価高騰に対する補正予算等を組ませていただいて、それが地方創生臨時交付金の流れになってきて、これを有効活用しなければいけないということで、せんだっては濱野区長に会派として緊急要望を申し上げて、こういう形で補正予算を組んでいただいたという流れの中で、やはり今年２回目の小麦等の価格が決まった段階で。","respondent":"染谷子ども家庭支援センター長、飛田子育て応援課長、勝亦学務課長","answer":"区内共通商品券、どこのお店で利用できるのかをどのように伝えるかという部分につきましては、商店街振興組合連合会のご協力を頂きまして。そういう意見も多数ありましたので、そこは反省させていただきまして、賞味期限のほうも、食品によっては短いものもあるのですけれども。そういった意味では、価格の動向ですとか国の動向を見ながら、機動的に、財政当局とも連携、検討して、保護者の負担等々。","id":"exchange-028"},{"speaker":"若林委員","kind":"質問・要望","question":"寄附した企業、それからクラウドファンディングをこれからやるというところで、そういった方たちのお金が本当に希望するひとり親家庭等に行ったのだなと実感できる取組をぜひお願いしたいと思います。今ご答弁があったように、機動的に、財政当局ともというお話もございましたので、ぜひ今後の動向を注視していただいて、取組、準備を進めていただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松澤副委員長","kind":"質問","question":"これは都の中で、食器洗い機とか洗濯機とか乾燥機とか、そういう指定があるのか、それとも、家事育児という大枠の中で、それは各自治体で考えて、そういうものに使っていいですよというのを決めるのかを教えてほしいのが１点と、安藤委員含めて、今、いろいろな周知の部分のお話がされていて、確かにホームページとか広報紙というのはすばらしいことなのですけれども、やはり見られない方は見られないし。","respondent":"染谷子ども家庭支援センター長","answer":"次の周知の関係ですけれども、広報紙、ＳＮＳ、それからホームページに加えて、お子さん、ご家庭の方が足を運ばれるような場所での周知についても検討はさせていただきたいと考えていますし。","id":"exchange-030"},{"speaker":"松澤副委員長","kind":"質問","question":"そうすると、自治体で考えなければいけないという部分で、１歳・２歳のご家庭の今欲しいものというのはなかなか分からないではないですか。私なんか、子育てが過ぎて大分たってしまっているので、何が必要だったかなんて思い出せないのですよね。","respondent":"染谷子ども家庭支援センター長","answer":"様々な事業者と話をしていく中で、先ほど申し上げた一部の例示に加えて、幅広く各家庭が選択いただけるような、そういった形での用品の選定に当たってまいりたいと考えています。","id":"exchange-031"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"田中委員","kind":"確認","question":"家事支援用品購入支援事業。私、てっきり東京都でウェブサイトを作って、それを品川区のホームページなどで広報していくと思ったのですけれども、そうではなく、品川区でウェブサイトを開設するということですか。その内訳とかを伺いたいのですけれども、この事業丸々ではなく、開設に対する事業者選定とかもいろいろあるでしょうし、その部分を確認させてください。","respondent":"染谷子ども家庭支援センター長","answer":"こちらの事業につきましては、都の補助事業ではありますけれども、区が主体的に実施する事業となっておりまして、ウェブサイトの開設につきましても区で行うものになっております。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成はしますが、周知がとても大事だなということと、あと、ウェブサイトの部分で、やはりなかなかそういうのが苦手な方もいるので、そういう方への周知等も含めて、丁寧にしていただきたいなということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"令和４年陳情第３３号、品川区の教育現場における給食および昼食時の感染症対策制限緩和と区の感染症ガイドラインにもとづくアンケート実施についての陳情","agenda":"令和４年陳情第３３号、品川区の教育現場における給食および昼食時の感染症対策制限緩和と区の感染症ガイドラインにもとづくアンケート実施についての陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、２ページ目にマスク着用の文章が書いてありまして、ここでも登下校時もマスク着用と書いているのですが、登下校時のマスク着用についての現状の指導と実態はどういうふうになっているのか、併せて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"ただ、お子さんも保護者も様々なお考えの方がいらっしゃるので、一度指導はするのですけれども、あまりしつこいと、またその辺りも、お子さんやつけたい保護者には納得いただけない場合もあるので、実態はつけているお子さんもいると認識しています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"１８ページの下校時は必ずマスクの着用を徹底するというのは、以前はどうなっていたのか、もう一度お伺いしたいのですけれども、現在は、熱中症で、かなり矢継ぎ早に国からも、指示、ガイドラインなども出ていて、外でということなので、熱中症のことを考えて、外してください、外していいですということを、周知しているということですが、これまでの長い時間もあったので、とは言ってもすぐ外せない、あと。","respondent":"矢部教育総合支援センター長","answer":"繰り返しますけれども、登下校は基本的に、今、この季節で矢継ぎ早に通知が出て、外すように指導しています。ただ、実態は今お伝えしたとおりです。その前の１４版の表記については、調べしますので、お預かりいたします。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。参考までになのですが、オミクロン株の子どもへの影響というのは相当問題になりましたし、そういった影響で、現在のマニュアルについては、黙食を徹底するというかなり厳しめのものになっていると思うのですけれども、２３区の状況などについて、もしつかんでいるところがありましたら、どんな感じなのでしょうか。伺います。","respondent":"矢部教育総合支援センター長","answer":"先ほどのガイドラインの２７ページは、子どもの心を把握するための手だてです。今、全体的にやっているのはそのようなアンケートでございまして、それぞれお子さんたちの心のケアのために行っているということで、アンケート調査の実施はしていると考えています。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"実際に子どもたちがどういうふうに考えているのか、感じているのかということも。特にコロナという未曾有の事態で、本当に子どもたちは、一度しかない子ども期にそういう体験をしているわけですから、そこについては、私は、差別の問題も含めて、区として、区教育委員会としてアンケートを実施すべきと思うのですけれども、その必要性についてはどうお考えなのでしょうか、伺います。","respondent":"矢部教育総合支援センター長","answer":"アンケートも大事なのですけれども、毎日対応しているのは教員ですので、今、目の前にいるお子さんがどうかというのは、ふだんの生活を見たり、保護者とお話ししたり、その子との会話、また、お友達関係を見て、そこで、その場で行うことが一番肝要だと考えておりますので。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、やむにやまれぬ思いでこういう陳情が出ていると思うのですけれども、黙食に関しては、実際どういうふうに感じているのかというのはしっかり聞くべきだと思いますけれども、いかがでしょうか。ちゃんと子どもにどう思うのと聞くというのが大事なことです。そういうことが重要視されている時代だし、求められている時代だと思うので、ぜひやってほしいと思うのですが、最後、もう一度伺います。","respondent":"矢部教育総合支援センター長","answer":"それができないのだったら、私たちもまた一緒に考えなければいけないと思うのですけれども、お電話でお伺いしている中では、学校のほうにはお話ししたということも様々聞いておりますので、ぜひ学校のほうにもご相談を遠慮なく頂ければなと考えております。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"学校のほうでは、やはり感染リスクがあるので、黙食を徹底してほしいというその気持ち、その状況もすごくよく理解します。そこについてと、あと、アンケートについてはぜひ実施していただきたいと思います。なので、ぜひ実施はしていただきたいと思いますし、また、子どもたちが今どういう気持ちで生活しているかということが分かるような公表もしていただきたいと求めたいと思います。いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"アンケートにつきましては、これは日頃の子どもたちの様子を見ながら、様々なアンケート、特別というのではなくて、アンケートを頂く中で、しっかり対応していきたいと思いますので、現状は考えておりません。","id":"exchange-040"},{"speaker":"渡部委員","kind":"質問","question":"本当に難しいですよね。それは今朝、ラジオで聞いたアンケート結果だったのだけれども、そういう答えが逆に返ってきたときに、どう対応するのですかという話ですよ。厳しくしてほしいという家庭があるから、そのお子様がお母さんに言われているのだとかうちの人に言われているのだというので、学校の先生がいろいろ注意をしてくれていても、その子はマスクをしているという現状があるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問","question":"それと、課が違ったと思いますけれども、毎月の子ども施設を含めた区内の学級閉鎖とか、ああいう状況が事細かに議会の中でも報告いただいていますけれども、１５になる前後ですかね、区内の学校とか子ども施設の感染状況は、別に科学的に分析しようなんて思いはさらさらないですけれども、参考までに、区教育委員会はどういうふうにデータを捉えられているのかなと。そこはお聞きしておきたいです。","respondent":"勝亦学務課長","answer":"そういった中で、現状ですと、年度改まりまして、４月に約５００人、５月に入りまして約２５０人、今、６月ですけれども、１日５名から１０名程度、現状ですと１６０人程度の患者が出て、徐々に落ち着いてきているという状況の認識です。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"傾向性とか考え方が一定分かりました。今のこの１５の対応が本当に正しいのかどうかということは、誰も、それは当然答えはないのですけれども、さっきありましたが、子どもたちが、黙食であったり、授業の中であったり、ある意味で与えられた環境といいますか、その中で今のこういう対応をするということについて、子どもたち同士とか先生と何かお話合いをするとか、意見を話す場はあるのでしょうか。","respondent":"矢部教育総合支援センター長、中谷指導課長","answer":"担任と生徒で生活ノートというのをつくってやり取りをするとか、スクールカウンセラーによる保護者への講話、そのようなこと、様々取り組んでいるところですので。そのような成果につきましても全校で共有できるようにしてまいりたいと思いますので、引き続きやっていきたいと考えています。","id":"exchange-043"},{"speaker":"松澤副委員長","kind":"質問","question":"田中委員がおっしゃっていたように、本当にこれは難しい問題だなと私も思っています。うちの子どもの話をしますと、４人いて、一番上が９年生なのです。外して行っていいのだよと。だから、やはりそういうのをしっかり周知して、学校の範囲を超えてしまうかもしれないですが、地域で見守るということ、声かけをするということはとても大事なことだと思いますので、そういったお考えはどうでしょう。","respondent":"矢部教育総合支援センター長","answer":"地域の方は、コミュニティスクールということもありまして、年４回、５回でしたか、町会長も含めて何度も集まるので、そのような情報はきちんと伝えていく必要があるなと感じていますので、ご提案は持って帰ります。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問・要望","question":"本日結論を出します。そのような活用をしながら、クリアしていただきたいなというのがあります。ですから、そのための工夫、言葉ではなくて、食べるときは口を開くのだから、声を出してしまったら感染する可能性があるのだけれども、難しいけれども、食べたらマスクをして、ちょっとお話ししたりはできるのだよという、指導なのか、そういうのをやっていただきたいなと思います。長くなりました。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択という判断をいたします。教育委員会、このバランスをとる、こういった判断は非常に難しい。一方で、こういう陳情のお声もあるという中で、当然専門的な知見、それは国、文部科学省の見解ということになると思いますが、しっかりとバランスをとって、どのようなバランスをとろうとも何かしらの声は当然ある。その中で、賢明にご判断いただきたいなという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"ですから、そこはやはり重く受け止める必要があると思いますし、そういうところを踏まえて、子どもの最善の利益、感染リスクを避けるということも含めての子どもの最善の利益というのは何なのかというのは、本当に悩ましいところだと思うのですけれども、今回、当事者からの切実な声ということも受け止めて、しっかり考えていく必要があるのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"要望なのですけれども、まず差別防止の部分、声かけしていただいていると思うのですが、マスクを外していたり鼻マスクをしている子に対しての声というのは子どもから聞いたりもするので、それは差別だよとか、こういう子もいるよというような周知とともに、先ほど来、意見のあった、お外ではとか一定の距離があればとか、マスクは外していいのだよということの周知をぜひ徹底していただきたいということと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"今、マスクの話をしましたよね。本当に学校とか園で皆さん頑張っていて、園なり学校なりで問題を解決しようとやっていただいていると思うのです。だけれども、これは当然教育委員会とか子ども未来部、当たり前ですが、議会も一緒になって、皆さんで考えていますよという、意思表示だったと思いますので、ぜひお伝えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5070#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":47845,"voices":167}},{"id":"r04-20220627-5","meetingId":"r04-cm06","date":"2022年6月27日","dateIso":"2022-06-27","committee":"総務委員会","time":"午前１０時００分～午後 ３時５４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(9)から行います。 それでは、(9)第５６号議案、八潮中央保育園大規模改修工事請負契約","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(9)から行います。 それでは、(9)第５６号議案、八潮中央保育園大規模改修工事請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"八潮中央保育園の大規模改修ということなのですが、老朽化ということで、文教委員会の資料を見ると、４０年以上ということで書かれていたのですけれども、４０何年なのかということが分かったら教えていただきたいのと、旧耐震基準の建物なのかどうなのかということについても伺いたいと思います。","respondent":"初貝保育教育運営担当課長、小林施設整備課長","answer":"この建物は、建設からおおよそ４０年経っているというところと、あとは、保育園の大規模改修工事の計画を立てているかですけれども、全体のところ、今年度、保育園のところの建て替え検討も進めておるところですけれども、４０年以上。つきましては、耐震補強が必要かどうかという判断になりますと、耐震基準が守られてありますので、耐震補強は必要ないかというふうに認識しております。","id":"exchange-001"},{"speaker":"西本委員","kind":"確認","question":"今のところも含めて、もう一度確認したいところがあるのですが、全体の建て替えの見直しはこれからということなのですが、いつ頃まで具体的な計画があるのか。これはずっとと先ほどおっしゃっていたのですけれども、これはずっとなのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"全体の建て替えについてのスケジュールは、今年中に出るというスケジュール感なのか、それとも、今年そういう検討をして、そのスケジュールは、来年、再来年なのか、その時間のスケジュール感を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"今回この契約の契約金額の妥当性ということなのですが、すみません、工事のことにそんなに詳しいわけではないので、この工事概要に書かれている内容が、この契約金額で行われるということの審査だと理解しておりますが、例えば、内装全面改修工事となっていますけれども、内装全面改修というのは、この２０ページの図に、バリアフリートイレとかがあるのですけれども。","respondent":"小林施設整備課長","answer":"そういった観点から申し上げますと、機能につきましては、約４０年ぐらい前の建物ですので、それから新しくなって機能アップされているというふうに考えてあります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"はい、分かりました。全面改修という、そういうことですね。ゴムチップのことも分かりました。もし落っこちたりしたときに安全なということで、遊具の下でクッションが効くものですね。ゴムチップについては、これは意見が分かれるところなのですけれども、できることなら自然の形のものであってほしいというのが私たちの主張ですけれども、その点については了解いたしました。","respondent":"小林施設整備課長","answer":"それと併せまして、空調機器につきましても、やはりここ５年、１０年で大きく省エネ性能が高まってありますので、今回、全面改修をするに当たりまして、そういった設備機器につきましても全面的に改修がありますので、そういった観点から申し上げますと。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"すみません、先ほど聞けばよかったのですけれども、また所管を越えたら言ってください。それとも、例えば、いろいろな工夫をしてくれるということの条件の中で選ばれているのか、それはどこまで契約するときに加味されているものなのでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"今ご指摘がございましたトイレの改修に関しましては、まず、保育園を改修するときに、トイレの数であったり、そういったものは人数当たりどのくらい設置しないといけないかというところもありますので、その基準と、あとは、今の中で、そういっただれでもトイレというか。","id":"exchange-006"},{"speaker":"西本委員","kind":"提案","question":"そうすると、保育課のほうから、ある程度こういう形にしてくださいという形で、その契約されたところはそのとおりにやるという形で、提案型とかではなくてということですね。何を気にしているかというと、トイレのプライバシーの問題です。","respondent":"小林施設整備課長","answer":"いろいろな考え方がある中で、この施設につきましては、こういったやり方をしましたが、今後、様々な施設の設計を進めているところですので、引き続き、施設運営者等の声を聞きながら、適切なトイレづくりについては詰めてまいりたいというふうに考えております。","id":"exchange-007"},{"speaker":"西本委員","kind":"意見","question":"意見を１つ。所管課の内容に入ってしまったらごめんなさい。ですので、改築をするのだったら、その状況も踏まえて設計していかないと、そういう施設をせっかく改修するのに、非常にかけ離れた施設になってしまうので、そこは状況を踏まえて設計をしていただきますように、これはお願いという形でしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"湯澤委員","kind":"確認","question":"１点だけ確認をさせてください。２０ページの更衣室、休憩室とあると思うのですけれども、４０年前は結構女性の方が多かったのかと思うのですが、今は男性も働く中で、これだけ見ると分からないですけれども、更衣室は、男性、女性と分かれているということでよろしいでしょうか。","respondent":"小林施設整備課長","answer":"更衣室につきましては、確かにおっしゃるとおり、従来は男女共用とか、あるいはカーテンとかで仕切られた中での更衣室があったかというふうに思いますが、今回改修するに当たりましては、男女、それぞれ扉を分けて、壁も分けて整備する計画となっています。","id":"exchange-009"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ほかの区立保育園でも、結構、男性職員が「入りますよ」と言ってから入るということを聞いたことがあるので、こういうふうに新しくするに当たっては、今後も建て替えとかリニューアルはあると思いますので、更衣室、それから今、西本委員が言ったように、トイレに関して、子どもたちもそうですけれども、男性職員とかが多くなると、それぞれいろいろあるかと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを見ると、便所棟のバリアフリートイレのところには、多分、ユニバーサルシート、介護用ベッドはついているような感じで見えるのですけれども、常に私たちも障害者団体の方から、区内の主な施設には、必ず１か所ユニバーサルシートをつけていただきたいということでご要望を伺っているのですけれども、その確認もさせていただきたいと思います。","respondent":"高梨公園課長、小林施設整備課長","answer":"それと、便所についてなのですけれども、まず、現在のバリアフリートイレの車椅子利用の頻度ですが、当該公園は運動施設に特化したところがございまして、今、管理者からのヒアリングでは。バリアフリートイレの中のユニバーサルベッドですが、今回、設置をしています。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"これ、管理事務所棟の中に更衣室があるのですけれども、これはシャワー室はついているのでしょうか。その中にトイレはあるのですか。そこだけ。","respondent":"高梨公園課長","answer":"新しく改築する管理事務所棟の中の件ですが、まず、シャワー室はついてあります。男女それぞれ別にシャワー室を設けておりまして、更衣室の中に、またトイレもそれぞれ個室のトイレを、男女それぞれ別で設ける形とさせていただいています。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"私は無料でやってほしいと思っているのですけれども。運動をしている中で体調を崩されたりしますよね。そういう場合の休憩する場所とかは、暫定的にここ、というふうにないのか、今だと、そういう場所はなかったように思うのですけれども、多分、こういう天気が続くので、体調不良という方も往々にして出てくる可能性がありますが、そこら辺の安全を含めての対応はどうされるのでしょうか。","respondent":"高梨公園課長","answer":"新しい施設につきましても、先ほど施設整備課長からもありましたとおり、一定、今の建築物よりは広くなりますので、そういった救護スペース等を含めて、これから中の配置等を検討してまいりたいというふうに考えております。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"ウィークデーはガラガラで、いざ使うとき、土日は、すごく混んで駐車ができないというような状況も出ております。何か利用者に対して、そんなに交通量が多くない場所に限って、そういうことも警察にお願いするか、あと、区のほうで、もう少し広げられるような工夫というのは、それぞれの公園で、これ（八潮北公園）も含めてそうなのですが、何か考えられているのか、それだけお聞かせください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問","question":"整備するならば、駐車場のほうもするのかなと思ったのです。すみません、それでちょっとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問","question":"車椅子の人が入ろうと思うとドアが閉まってきてしまう。実際に使えるのかどうかというのは、設計の段階でそれがあれば、何もそんな苦労はしなくて済むのかなということがありますが、その辺についてどうなのでしょうか。そうでないと、この契約金額がまた増えたりとか、直さなければいけないということがあるのではないかなということを大変懸念するのですけれども、その辺についてはいかがでしょうか。","respondent":"小林施設整備課長","answer":"様々な意見もあるかと思いますが、まずはこの状況でやらせていただいた上で、必要な意見等、あるいは届けられた意見等を踏まえながら、次の設計に生かしていけたらというふうに考えてあります。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"それに対して、出来上がってみたら、そういう状況だということなので、これについても、また私が叱られるだけならいいのですけれども、区がお金を出す、契約して、そのお金を使ったことに対してのお叱りなわけですから、それについてはぜひこれからでも改めて、そういう本当にニーズのある方たちに対してご意見を伺っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"湯澤委員","kind":"質問・要望","question":"すみません、ちょっと確認をさせていただきたいのですけれども、２６ページの便所棟のトイレの図は、これ、女子トイレのほうは、便器が４つなのですか。それとも実は男女が逆とか。それとも複数人入れるのでしょうか。","respondent":"小林施設整備課長、高梨公園課長","answer":"便所棟です。大変申し訳ございません。これは、男子と女子、逆です。大変申し訳ございません。今後、需要の高まり等を見て、例えばそういった大会等、まとまった利用があるときには、既存の男子更衣室、女子更衣室を専用にするであるとか、まずは運用の中で対応していきたいというふうに考えています。","id":"exchange-018"},{"speaker":"湯澤委員","kind":"意見","question":"ぜひお願いしたいと思います。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"人工芝のほうなのですけれども、芝の張り替えで２億７,７２０万円、芝の張り替えと防球ネットとか、様々あるのですけれども、この人工芝というのは、前のものはいつ頃変えて、どれぐらいの耐用年数なのか、今回張り替えた場合、何年くらいもつものなのかについて教えていただきたいと思います。","respondent":"高梨公園課長","answer":"前回の人工芝の張り替えは、平成２１年度に実施をしています。当時も現在もほぼ一緒なのですが、耐用年数は約１０年から１２年ということでメーカーのほうからは言われております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、これは様々で２億７,７２０万円になると思うのですけれども、人工芝の張り替えだけで幾らぐらいになるのか、教えていただければ。","respondent":"高梨公園課長","answer":"電気の関係等もあって、きれいに分かれているわけではないので概算という形になりますが、約２億円ほどが人工芝に充てられる金額です。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問","question":"今の八潮北公園のことなのですが、主な工種で、人工芝で２億円というと、残りの７,７２０万円がその他だと思うのですけれども、防球ネット工は幾らぐらいなのでしょうか。","respondent":"高梨公園課長","answer":"防球ネットの設置に関しましては、ネットだけではなくて、それを支える支柱等の建設等がありますので、残りの金額約７,０００万円については、防球ネットの関係の工事費という形です。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"確認","question":"はい、分かりました。物すごい大がかりなのかなという感じがします。ちょっと契約の部分なのですが、今後の使い勝手でということで、先ほどもほかの委員からいろいろ、また追加でお金がかかってもとあったので、あえて確認します。どのぐらいの高さの位置の上部になるのですか。周りを囲うというネットではなくて、まさにその上、天空になろうかと思うのですけれども、その高さはどのぐらいなのでしょうか。","respondent":"高梨公園課長","answer":"地上より１１.７ｍ、約１２ｍ弱のところにネットを張ろうというふうに考えてあります。当然、ネットですので、テニスコートの真ん中ではたるみがありますので、たるんだ状態でも９ｍ以上は確保したいというふうに考えてあります。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問","question":"今、一番最後のところで、テニス協会から出されている指針に基づいた高さということで、私もテニス出身なので、競技場ではロブというボールを高く上げてプレーするラリーがあるのですけれども、そのぐらいをとられているのであれば、プレーに支障はないのかなと思いました。ひとつ関心があるので。野球の競技上、どういうボールがテニスコートのほうに来るのでしょうか。その辺りも参考に教えてください。","respondent":"高梨公園課長","answer":"フェンスを高くすればといったところで比較検討したところですが、理論上、相当高いフェンスを設置しても、どうしても場外飛球というのはゼロにならないということで、テニスコートのほうを守る方式を採用させていただいて、今般、工事をすることになったところです。","id":"exchange-024"},{"speaker":"つる副委員長","kind":"意見","question":"そうすると、テニスコートなども、その周りの支柱とか上にネットを張るときは、一定程度使えなくなってしまうという期間があるという理解でよければ、違ったらご答弁いただいて、そのとおりだったら、別にご答弁は結構です。時間の短縮で。","respondent":"高梨公園課長","answer":"そのとおりですが、参考までに、工事契約後、今年８月から年内いっぱいぐらいまで、この２面についてはテニスコートの利用を中止にする予定です。","id":"exchange-025"},{"speaker":"大倉委員","kind":"確認","question":"すみません、今、話を聞いていて、防球ネット（の高さは）１２ｍということで、よく風が吹くと支柱に負担がかかってネットとかが倒れてしまうといったことがよくあるのかなと思うのですけれども、そういったところは大丈夫なのでしょうかという確認です。","respondent":"高梨公園課長","answer":"今回は、ほかのキャッチボール場等でも採用しているところが多くなっていますけれども、ワイヤーで下ろせるタイプ、それから強風であるとか、雪が想定される際には、下に下ろして養生ができるようなタイプで考えているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"浜川中学校の校舎改築ということなのですけれども、現在の浜川中学校の築年数を教えていただきたいと思います。以前は小中一貫校でも１００億円くらいだったと思うのですけれども、上がっているのであれば、その理由も伺いたいと思います。そういうことも想定した設計になっているのか、その点についても伺いたいと思います。","respondent":"森（雄）学校施設担当課長","answer":"理由ですけれども、もともと現状の普通教室が９教室でございまして、新校舎は２１教室、プラス転用可能な多目的室３室ということで検討しております。校庭ですけれども、現状、３,０３０m2に対しまして、改築後は３,０５０m2と、ほぼ変わらない状況です。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"学校改築の全体の計画は、令和１１年度までに６校が新しく順次竣工していくというふうなことで総合実施計画には書かれているのですけれども、その後、８校が新規にさらに改築の計画がされるということなのか、そこら辺の全体の計画がどうなっているのかについても伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ここが５９年で建て替えということで、学校は改築するのに大体６０年近くにもなるのだなと思ったのですけれども、おおよそ何年ぐらいで改築は計画されるものなのか、その点と、それから、改築した後の耐用年数は何年くらいもつ建物になるのか、その点についてもお聞かせください。","respondent":"森（雄）学校施設担当課長","answer":"改築が終わった後、何年ぐらいもたせるかというところですけれども、これは長寿命化のこととも関係していますが、５０年経って大規模修繕、模様替えを行いまして、８０年、１００年ぐらいまで延ばしていきたいというふうには考えてあります。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"改築の外構工事もこの契約金額の中に入るということなのですが、それについてちょっと教えていただきたいのです。それから、フェンス、門扉等の設置とあるのですが、これもやり替えるということなのですか。全部取り替えるということなのでしょうか。よく意味が分からないので教えていただきたいのですけれども、これは、各教室に衛生器具設備というのは、どういうものが入るのか。","respondent":"森（雄）学校施設担当課長","answer":"もう１棟も既存がありますけれども、平米があったりとか、状況がよくないものがありますので、造り替えて設置をし直していく形になります。機械設備のご質問ですけれども、当然各教室に給水はございません。廊下、便所等に給排水がある形になります。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。中水設備は、雨水利用ということなので、私たち生活者ネットワークとしては、ぜひ推進してほしいということでずっと意見を言っています。それから、さっきまとめて聞けばよかったのですけれども、４５ページの電気設備工事のほうも、発電設備と太陽光発電設備と別に書いてあるのですけれども、これはどういうことなのか、教えていただきたいと思います。","respondent":"森（雄）学校施設担当課長","answer":"防犯カメラにつきましては、今も一定程度あるはずなのですけれども、新設では９台取り付けまして、出入口部分、昇降口の部分、駐輪場の部分、エレベーターの中、屋外避難階段等に設置する予定です。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"それぞれありがとうございました。中水設備は最近の考え方ということですけれども、品川区は割と前からトイレの水に雨水を利用するということを推進しておられますので、生活者ネットワークとしては、ぜひこれからも推進していただきたいというふうに思います。防災などのこともそれぞれ配慮されているということですし、太陽光発電も設置されるということを確認いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"民間の会社だと、これだけコストが上がっているときに、これだけ大規模な工事をするというのは、一番コストが高いときですから、高騰しているときに工事を進めるということはなかなかやらないのですよね。結局、今、校舎の改築工事だけでも６０億円かかる。だけれど、区としては、今どんなに高騰しようがやらなければいけないというようなスタンスなのでしょうか。その辺についてご見解をお聞かせください。","respondent":"森（雄）学校施設担当課長","answer":"金額が高いのになぜ工事をするかですけれども、浜川中学校は９教室が２１教室になるというところで、このままいきますと、子どもが入学できないという事象が発生いたしますので、今工事にかからないと、子どもが入学できない状況になってしまう。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、品川区全体を見たら、どんどん改築工事が毎年少しずつでも進んでいると思いますけれども、やはりその辺の経費的なものも考えて進めるべきことではないかと。やはり民間は民間で、できるだけ経費がかからないように進めているという状況もありますから、その辺については、やはりご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"コスト、契約金額が非常に高いということで、これ、近年、３０％上がっているということなのですが、今の現状を考えると、もっと上がると思うのです。品川区の持ち出しだけが多くなるというのはどうかと思うのですけれども、今後のコスト上昇に向けての対応策をお聞きします。","respondent":"森（雄）学校施設担当課長","answer":"できる限り工事費が圧縮できるように、細かい資料、それから工事の内容を含めまして検討して、できる限り少ないコストで建物が建つように、日々、検討しています。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"その努力は必要だと思うのです。ただ、現実的に考えたときに、高騰すると思うのです。落札した状況の中で、落札した企業の方々も努力はしていただけると思います。見直しの期間はどういうふうに考えているのですか。","respondent":"東野経理課長","answer":"工事請負約款、いわゆる契約条項の中にスライド条項、物価の変動による場合ですとか、それから、労務単価の変更による場合、そういった場合のスライド条項というものを設けておりますので、事業者のほうから申請があった段階で、その協議を行い。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"往々にして品川区独自の予算から出さなければいけないという事態も出てくる可能性もあると思っているので、そこは子どもたちの教育現場ですから、老朽化も激しくなっているといいますか、必要性はあると思いますので、そこの兼ね合いを、うまく調整を図っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それは様々な高騰だったのかと思うのですけれども、不調になった原因が何だったのかということも伺いたいのが１つと、それから、こういう学校の改築の場合の国や東京都からの補助金は、どれくらいどういう形で来るのか、その点についても教えてください。","respondent":"森（雄）学校施設担当課長","answer":"規模に応じてなのですけれども、その規模も我々が思っているよりはるかに小さい規模までしか補助金がつきませんので、それ以外は区で拠出して学校を改築しているところになってあります。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、例えばこの浜川中学校だと、おおよそ何％ぐらいが国や東京都から補助金が出るのか、その仕組みがよく分からないので教えていただきたいのですけれども。この場合、何％ぐらいになるのか、お願いします。","respondent":"森（雄）学校施設担当課長","answer":"確かなことが言えなくて大変申し訳ないのですけれども、大体３億円かそのぐらいだったような。前回の学校でもそのぐらいでした。今、６０億円かかっていても、補助金としてはそのぐらいの規模感です。何十億円もということではございません。資料がなくて大変申し訳ございません。","id":"exchange-039"},{"speaker":"つる副委員長","kind":"質問","question":"もしそうでないとかも含めて、あと、この部分の土地が、東京ガスの所有なのかとか、もしくは学校の敷地内に、そういうものはそもそも置いて整圧してやっていくものだと思うのですけれども、別の場所でガバナがあってなかなか道路の整備とかで調整が必要だとかということがかつてあったので、この辺りの位置も変えるのかなと思ったときに、その辺の工事費用はどちらがもつものなのでしょうか。","respondent":"森（雄）学校施設担当課長","answer":"どの学校でもあるかと言われますと、恐らくないのではないかと思ってはいるのです。この学校については、ガスガバナがある状況というところですけれども、緑地の部分等をうまく使いまして、直ちに計画に支障が出ているということはございません。","id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問","question":"工事費用というのは、こういう場合はどちらがもつものなのでしょうか。今、貸与とありましたので、土地をお貸ししているということですが、設備自体は、学校に供給されるだけではなくて、このガバナから多分近隣のご家庭のガスのメーターまで担っているものだと思いますけれども、そういう用途、使用からするならば、工事費用の考え方はどういうものなのでしょうか。","respondent":"森（雄）学校施設担当課長","answer":"すみません、ちょっとそこら辺の資料を詳しく持ってございません。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"すみません、あと１点だけ。都区財政調整関係で、学校の改築のときに、これは東京都の協議事項の中に入っていたと思うのですけれども、それを踏まえて、先ほど、３億円とかという補助金、これは国からのでしょうか。補助金の在り方は、東京都との交渉事項に入っていたと思うのですけれども、それはどうなっているのでしょうか。都区協議の中に入っていましたよね。それはいかがなのでしょうか。","respondent":"黒田財政課長","answer":"財調の工事につきましては、工事費単価は全体の平均で算定されておりますので、区の都合で工事費の単価が高い場合については、それは区の予算で支出するというような状況になっていますが、あくまでも財調は、特別区が標準的に実施する工事について算定されるというものです。","id":"exchange-042"},{"speaker":"西本委員","kind":"質問","question":"ということは、この浜川中学校はどうなるのですか。その算定の中に入らないということですか。そういう何かしらの対応があるという理解でいいですか。","respondent":"黒田財政課長","answer":"ですので、標準的な工事については財調算定されているものです。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"そのレベルを知りたいのです。６０億円かかるわけです。６０億円の中で、先ほど、３億円ということもあったし、一体、区に都からどのくらいお金が来るのか。そうすると、ほとんどが、仮に３億円だとしたら、５７億円が品川区のお財布から出すという理解でいいのですか。","respondent":"黒田財政課長","answer":"詳細な単価につきましては、大体工事費につきましては、どの工事も平均で３３万円から３４万円ぐらいのところが工事の財調単価として決まっていますので、そういった意味で、それを超える部分の工事については、当然、区の都合の工事でありますので。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"具体的な金額は、今は出せないということなのでしょうか。でも、知りたいのは、どれだけ補助金があって、どれだけ私たちのところから出さなければいけないのですかという話です。都合は都合で分かるのですけれども、でも、都区間の協議の中では、学校改築の中に入っているわけです。それが全然進んでいないという理解でいいですか。","respondent":"黒田財政課長","answer":"すみません、浜川中学校で幾ら財調から算定されるか、現時点で数字を持っていないですけれども、都区協議は毎年度、いわゆる工事費の単価が現状に合っていないのではないかというところで都と協議はしておりますが、それは全体の財調協議の中で決められるということですので。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"財調算定は、基本的なところを財調で算定されて、品川区が特別に区独自にプラスでやりますみたいな、そういうところだけが区の基金から出さなくてはいけないというふうなことで考えて、基本的には財調と補助金、補助金は３億円なのでほとんど出るとはいえないようなものなのかと思うのですけれども、基本的には、ほとんどは財調算定されるという考え方でいいのか、その点だけ。","respondent":"桑村副区長","answer":"財調というのは、都区でいろいろやり取りしているわけですけれども、２３区でどのくらい改築が必要なのかということを都と区でやり取りされます。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"築年数の確認をお願いしたいのと、今回、大規模改修すると、耐用年数がどれぐらいになるのかについても伺いたいと思います。そして、そのユニバーサルシートが設置されたときも、そのユニバーサルシートが設置されていますよということが分かる表示も入り口にしていただきたいというご要望もいただいているのですけれども、そういう設定になっているのかについてもお聞かせいただきたいと思います。","respondent":"小林施設整備課長、篠田文化観光課長","answer":"構造の変更ですが、今回、建物自体の構造については変更することはございません。フレーム等についてはそのままです。私からは、運営に関する部分のご質問に対してお答えいたします。入館者数ですけれども、ここのところ、コロナの関係で閉まっていたりしたところはあるのですけれども、通常ですと、観覧者が年間で１万人から１万５,０００人ぐらいです。","id":"exchange-047"}]},{"id":"topic-02","title":"第５８号議案、電線共同溝等工事（競馬場通り）委託契約","agenda":"第５８号議案、電線共同溝等工事（競馬場通り）委託契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その確認を１点お願いしたいと思います。契約なので、どれぐらいのメートル数でどれぐらいのお金が発生するのかというところなので、メートル表示はぜひしていただきたいと思います。今後はそういうところでお願いしたいということがあります。それから、基本協定で、競馬場通りのこの２００ｍに限った基本協定ということになっているのか、その点についても伺いたいと思います。","respondent":"森（一）道路課長","answer":"随意契約ですけれども、東京電力パワーグリッドが持つ既存の施設を活用するということでございまして、東電タウンプランニングにつきましては１００％子会社であり、そこの設計、施工を担当してるですので、今回、それで随意契約で進めさせていただきたいです。","id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、この品川区の無電柱化推進計画というのがありましたので、これを見てみたら、やはり競馬場通りのところは４００ｍというふうになっていたので、その一部なのだなと思ったのですけれども、そうすると、この基本協定は４００ｍということで結んでいるのですか。東京電力パワーグリッドの共同溝は、ここの２００ｍだけではなくて、どこまで造られているものなのか。","respondent":"森（一）道路課長","answer":"費用につきましても、その分低減できるというふうに考えておりますので、具体的な金額としてまでは出していませんけれども、低減できる方向で進められるというふうに判断しています。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"違うと思うのですけれども、無電柱化するに当たり、１ｍ当たり幾らぐらいかかるとかという、そういうおおよその目安が、高い場合と安い場合みたいな感じでもいいのですけれども、そういうものが分かったら教えていただきたいと思います。それから、国道や都道の無電柱化の現状はどうなっているのかということも教えていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいのですが、日本で無電柱化というのは、電線共同溝を造る場合、整備費用というのは、１km当たり約３.５億円、４億円でできていると。そうすると、ちょっと金額的に、整備しても１kmで４億円かかるのに、今回お借りするのに４億円かかるというのは、ちょっと計算が合わないと思うのですけれども、何か理由があるのでしょうか、教えてください。","respondent":"森（一）道路課長","answer":"そういったものを含めますと、費用としては大分嵩んできているというふうに思っています。国のほうでも様々、東京都のほうでもいろいろな新技術が研究されておりますので、今後ともそれを活用しながら、コストの低減も目指していきたいと考えています。","id":"exchange-051"},{"speaker":"須貝委員","kind":"質問","question":"すみません、質問が悪かったのかもしれないのですが、今回、従来、東京電力で造ってある設備ですか、そこを利用させてもらうのですよね。そうすると、そこに埋め込むだけで、これだけかかってしまうものなのですか。その金額の誤差を教えてください。","respondent":"森（一）道路課長","answer":"それもしっかり活用していくことになったのですけれども、そういった部分で、その本体工事が一部低減される以外に、あるいは、ほかのガス管であったり、水道管の支障移設であったりとか、そういうところでは基本的に出てきますので、それで例えば半額になるとか。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、２００ｍのうち６０ｍで、あとは１４０ｍを新たに造るということでいいのですよね。共同溝に入るものは、どのようなものが入るのかだけ教えてください。","respondent":"森（一）道路課長","answer":"共同溝の中に入線する企業のケーブルの予定は、東京電力の電力線、ＮＴＴの電話線、ケーブルテレビ品川の電線、あとはＫＤＤＩの線というふうなものが、今、予定しています。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"それによって関係性が大分変わってくるし、お金のやり取りも変わってくるのではないかと思うのですけれども、その関係性について聞きたいのと、この断面略図がよく分からないのですが、大きい四角のところが共同溝だから、今言った ＮＴＴ、ケーブルテレビとか、そういうケーブルが入るところということでいいのですか。右側の、電線共同溝一般部というのは、これは何なのですか。これは道路の線なのですか。","respondent":"森（一）道路課長","answer":"こういった図になります。１ｍというのは、土被りでございまして、この一般部の上に土が１ｍ乗っている、１ｍ下に一般部のケーブルが入っているというような図を表しております。","id":"exchange-054"},{"speaker":"西本委員","kind":"質問","question":"分かりました。ちょっと技術的な話になってしまうかもしれないですけれども、結局、地震とか災害など、こういうものは大丈夫だという認識でよろしいですか。","respondent":"森（一）道路課長","answer":"基本的には、埋設管については、例えば今申し上げた特殊部と一般部の継ぎ目のところに、地震が起きても動く、可撓性のあるといいますけれども、動くものが挟まって設置されておりまして、そこで地震の揺れを吸収できるようになっています。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"今あるから、「そこをどうですか」と言われて、「では、品川区も」ということだったと思うのですけれども、これは今後どういう動きになっていくのか。このままやってくれて、そこに乗ってしまえば、割と安くできるのかなと思うのですけれども、いや、そうではなくて、「やるからお金を頂戴」と言われてしまうと、その計画も立てていかなければいけないと思うのですけれども、どういうイメージなのでしょうか。","respondent":"森（一）道路課長","answer":"今後については、推進計画の中で設定している路線について電線共同溝の整備を進めていくのですけれども、その中で活用できる管なり、マンホールなりというものが、東京電力なり、ＮＴＴのものがあれば、それをしっかり活用して。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"国も関わってくるかもしれないですけれども、その関係性はどうなのでしょうか。それは結局、今は既存のものがあるから使おうよということで済んでいるのですけれども、でも、いずれは、大きな話になってきたときに、品川区も少しお金を出してよという話になってくるのか、そこら辺はまだ見えていないのですか。どうなのでしょうか。","respondent":"森（一）道路課長","answer":"品川区としましては、東京都のガイドライン等を用いながら、４路線について電線共同溝の事業を進めていくのですけれども、その進めていく中で、電線共同溝として、管渠なりマンホールなりを設置することになるのですが、その設置する代わりに。","id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"その話はそうだろうなと思うのですけれども、今後、それを取りまとめてやっていくのは、東京都のガイドラインがあるから、そのガイドラインに沿った形で東京都で進めていくものに対して追随していくという感覚でよろしいですか。","respondent":"森（一）道路課長","answer":"基本的には、このガイドラインに則って進めていくのですけれども、その現場現場で使えるものがあるかないかということもありますし、施工状況も違いますので、それについては、区のほうで、１つの手法として既存ストックの活用というものもありますし。","id":"exchange-058"},{"speaker":"吉田委員","kind":"確認","question":"ですから、今回、随意契約だというのは、たまたまといいますか、今のお話だと、今回は東京電力の既存のものが使えるので、そこの関連のところに随意契約でやるという考え方でいいか、それだけ確認させてください。","respondent":"森（一）道路課長","answer":"今回の路線について活用できる既存ストックがあるということで、事前の測量、設計等で分かっておりますので、それについて、この路線については、東京電力の設備を活用するというスキームで行っていきたいというものです。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"賃金水準の変動ということで、労務単価が上がったということで、今回の変更になったわけですけれども、上がった額というのは、前の契約と今回の契約の差額というのは４９１万９,０００円というものなのですが、これはどれぐらい上がったかというと、平均で何％ぐらい上がったというのがあるのか、その点について伺いたいと思います。労務単価というのはどこでどのように決められるのかも教えてください。","respondent":"東野経理課長","answer":"設計労務単価ですが、こちらにつきましては、国土交通省、国のほうで定めた労務単価があります。そちらでいきますと、全国でいくと全職種で２.５％の増が、今回示されております。東京都下におきましては１.９％の増ということで、報告が上がってあります。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"今、平均で６００円というのは、時給で６００円ということでいいのか、その確認をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろ建設組合の皆さんからもご要望をいただいていますので、そういうところは区としてもぜひ取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"西本委員","kind":"質問","question":"仕組みを教えてください。これ、受注者より協議請求があったと。それとも、こちらから誘導していけるものなのか。逆に言うと、国が動かなければ、物価が上がったりしたときに、なかなか現実に合った賃金という形になっていかない。要は、国が動くことによって、初めてこちらも応じるような仕組みができるというか、そういう状況になってしまっているのか、その辺はいかがですか。","respondent":"東野経理課長","answer":"聞いているところでいきますと、区のほうであらかじめこの工事が対象になるというのをつかみまして、あなたのところの会社ではどうされますかという形でお伺いしているということで、丁寧な対応を行っているところです。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問","question":"安心しました。なかなか分からない部分があると思うので、こちらから「どうですか」とお声をかけるのはありがたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"須貝委員","kind":"質問・要望","question":"労務単価は増えていないようです。元請けだけに流れているということがありますので、その辺に対して、行政機関としてはしっかりその辺を指導するようにして、やはり確認できればするようなことをして、本来のきちんとしたこういう契約に基づいて、こういう特例措置に基づいて今後もやっていくなら、やはりきちんとした対応を私はしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]},{"id":"topic-03","title":"第４３号議案、職員の育児休業等に関する条例の一部を改正する条例","agenda":"第４３号議案、職員の育児休業等に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明資料が少し分かりにくくて、具体的にどうなるのかというのが見えないのです。それで、そういう厚生労働省の資料なども見ながら具体的にお聞きしたいのです。会計年度任用職員の方は、前回の委員会で約１,３００人とお聞きしましたけれども、会計年度任用職員以外の方で、この条例の対象になる非常勤職員という方は、どんな労働形態の職員になるのか。その点をお願いします。","respondent":"崎村人事課長","answer":"１点目の、資料が分かりにくいというところで、これは法改正を受けてのものになりますので、どこまでやるかというところはご意見として受け止めさせていただければと考えています。","id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど言われましたように、これまで原則、子どもが１歳までというのが、最長で２歳までということで、今までは１回ということになっていたのが、２回まで取得可能ということで考えていいのでしょうかというのを教えてください。それから、区の職員の父親の育児休業取得率というのは、先ほどの産後パパ育休、出生後８週間以内に４週間取れるという、それを取っている方がどれくらいかということ。","respondent":"崎村人事課長","answer":"ですので、取得の率として、出生した５７日以内に取得しているかどうかというのは、この数字の中では分からないのですけれども、男性職員の育児休業の取得率としては、今、ご紹介したとおりです。","id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、今回は会計年度任用職員と再任用の方というのがこの条例では対象になるということなのですけれども、ちなみに、会計年度任用職員の半数が６０歳以上ともお聞きしたのですが、会計年度任用職員や再任用職員の方で、昨年とかで子どもが生まれた人数というのはどれくらいあったのか。そこら辺の補充の考え方がどうなっているのかについてもお聞きします。","respondent":"崎村人事課長","answer":"人的措置といいますか、育児休業を取得するときの職員の代替というところのご質問かと思うのですけれども、育児休業を１か月以上取得をするような方については、人材派遣を配置するですとか、年度末まで育児休業を取得することがその段階で分かっているような場合については。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０代・３０代の方も１１％いらっしゃるということであれば、１,３００人の１１％ですから、そこそこいらっしゃると思いますので、本当に育児休業を取りやすい職場の環境をつくっていただきたいと思います。それと、育児休業を取得したときの手当がどうなるのか。給与は出なくなると思うのですけれども、それに代わってどれだけ保障されるのか。そのことについても教えてください。","respondent":"崎村人事課長","answer":"こちらが大体育児休業の開始から半年までが標準報酬日額の３分の２、１日当たり３分の２が支給されまして、育児休業の開始から１８１日以降、６か月以降から１歳になるまでが２分の１支給されるというものです。","id":"exchange-069"},{"speaker":"須貝委員","kind":"意見","question":"職員の育児休業等に関する条例の一部を改正する条例ですけれども、これは本当に働く方にとっては、非常勤職員、それから会計年度任用職員の方にとっては非常に喜ばしい条例だと思います。ただし、民間の中小零細企業で働いている方はすごく多いわけですよね。民間労働者の大手は対応できると思いますが、その辺、その格差についてどのように思われるか、ご見解だけお聞かせください。","respondent":"崎村人事課長","answer":"人事当局からお答えするのはなかなか難しいご質問をいただいたところですけれども、今回の法改正については、まず民間のほうから昨年の６月に法改正がありまして、そういった男性の育児休業の取得促進、それが女性活躍推進にもつながるといった観点で法改正がされまして。","id":"exchange-070"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、そういう方もいらっしゃるということは、やはり行政機関としてもよくお考えの上、どうしたら中小零細企業で働く区民の皆さん、企業者の皆さんが、よりよい子育てができるようになるか、育児休業等に対しての対応策をいろいろ検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問・要望","question":"少し気になるのが、この制度は推進する方向でよいと思うのですけれども、具体的に自分がその対象になって、こういう権利を取得したのだということの案内というのか、こういう制度があるのかという、ほかの制度もいろいろあるので、みんな必要なのだと思うのですけれども、改めてこういう条例改正が行われたということについては、周知はどういう形で行われるのか、教えていただきたいと思います。","respondent":"崎村人事課長","answer":"それについては、出生サポート休暇という、不妊治療休暇も含めた段階でお話をさせていただきましたけれども、こういった仕事と育児の両立を図るというものについては、小まめに案内をすることが必要と考えておりますので、１０月１日の施行に向けて、また全庁に周知するとともに。","id":"exchange-072"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのようにお願いしたいと思います。皆さんは私よりは理解力がおありになるのだと思いますけれども、改めてその辺についてやっていただきたいのです。そういう方向けの資料の作成とか、そういうことについてはどうなのでしょうか。ぜひ分かりやすいものにしていただきたいと思っての質問なのですけれども、いかがでしょうか。","respondent":"崎村人事課長","answer":"失礼いたしました。今回の法改正に当たりましては、国のほうでも民間向けに、また、公務員向けにＱ＆Ａというものも作成されて、区のほうにも届いておりますので、また細かい具体的な事例等々も含めながら、周知のほうを図っていきたいと考えております。","id":"exchange-073"}]},{"id":"topic-04","title":"第４４号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","agenda":"第４４号議案、職員の特殊勤務手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この概要説明なのですけれども、東京都の云々ということで、２行目に「家庭訪問、面接等を行った際に支給する手当額が引き上げられた」という説明があるのですが、これは家庭訪問、面接を行った際にだけこの手当が出るというものではないと思うのですけれども、この文言だと、「家庭訪問、面接を行った際に支給する」と書かれているので、その点がどうなのかをお聞かせいただきたいと思います。","respondent":"崎村人事課長","answer":"概要の説明のところで「家庭訪問、面接」と書かせていただきましたのは、これは東京都の条例が、こういった手当を支給する際に、これまで家庭訪問のみだったのが、家庭訪問、面接および一時保護というふうに対象が拡大になったことから、そこに記載をさせていただきましたが。","id":"exchange-074"},{"speaker":"吉田委員","kind":"確認","question":"つまり、１日というのは８時間勤務としてそれだけ、いわゆる福祉職とか、そのような児童相談所の勤務に従事したら、１日、これが上限ですから、必ずしもこの金額ではないということなのでしょうか。だから、あくまでどれだけ仕事をこなしても、その時間内の勤務であれば、上限これだけという意味でいいのでしょうか。その辺、改めて確認させください。","respondent":"崎村人事課長","answer":"こちらの条例で適用しておりますのは、上限額ということで、９５０円と定めておりますけれども、実際に支給する額というのは規則で定めておりまして、規則では同額規定をしています。時間によって減額をされるといったものではないということです。","id":"exchange-075"},{"speaker":"吉田委員","kind":"確認","question":"時間によって減額されることもないけれども、どれだけ働いても、１日これは超えないということなのでしょうか。児童相談所のお仕事の内容を考えると、増額になったことは本当に望ましいことだと思うのですけれども、もともとの増額の趣旨からいって、これで十分なのだろうかという思いがあったものですから、改めて確認させてください。","respondent":"崎村人事課長","answer":"説明が不十分で申し訳ございません。例えば、ケースの軽重によって額が変わるといったことはございませんで、一律、この児童相談所の業務に従事した際には支給をされるといったものです。","id":"exchange-076"},{"speaker":"西本委員","kind":"質問","question":"品川区で、仮に１,０００円という形になれば、有利ではないですか。限度はあるかと思うのですけれども、そういう取決めというのはどこまであるのかということと、それから、適用ということで、４月１日よりということなのですが、該当すれば、（今は）６月だから２か月分がまとめて来るという、過去に遡って計算するという形で、該当する方というのはどれぐらいいらっしゃるのでしょうか。","respondent":"崎村人事課長","answer":"何人対象がいるかということですけれども、今年度、４月１日現在で９名、他自治体の児童相談所に派遣しておりますので、その方に支給する分については、４月１日の勤務以降の分について差額を支給するというものです。","id":"exchange-077"}]},{"id":"topic-05","title":"第４５号議案、品川区特別区税条例の一部を改正する条例","agenda":"第４５号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その上で伺いたいのは、１つは住宅ローン控除の見直しなのですけれども、住宅ローン控除というのは随分前からできている制度だと思うのですが、なぜ適用期限がこうやって区切られて、さらに延長みたいな形になっていくのか。そして、この延長というのがなぜ４年なのか。そこら辺は国の制度なのですけれども、どのように国が説明しているのか、分かったら教えていただきたいと思います。","respondent":"提坂税務課長","answer":"それで、なぜ４年延ばしたかということについては、その辺は明確にお答えすることはできませんけれども、新築住宅を建てる場合、４年間あれば間に合うだろうというか、通常はそんなにかからないと思いますけれども。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５％以下だったら、住民税と合わせても１５％だけれど、株のほうだと２０％ということになるので、所得の少ない人は総合課税のほうがプラスになるのかと思うのですけれども、そのようなことで考えていいのか。多くは分離課税なのかと思っているのですけれども、そこの３種類の課税方式で、それぞれ何％ぐらいの方が３つの方式を取っているのか、そのところが分かったら教えていただきたいと思います。","respondent":"提坂税務課長","answer":"申告分離課税については、「上場株式等」と書いてありますけれども、譲渡損失との損益計算ということで、これが３年間繰越し可能ということなので、損益が出た方についてはこの方式を選んでいただくのが有利かという考え方はあります。","id":"exchange-079"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、総合課税方式になれば、最高税率は４５％で、４５％という方は、４,０００万円を超えた部分に関してかかるのが４５％ということなので、それプラス住民税で１０％、合わせて５５％の税率になるところが、分離課税だと２０％ということなので、本当に私は格差をなくすというところからも、総合課税方式にすることで格差をなくすことにつながるのではないかと思うのですけれども。","respondent":"提坂税務課長","answer":"住民税率１０％については、配当控除が２.８％ということで、それを差し引いて７.２％、これを総合して１７.４１という数字が出て、ほかの方式より有利になる場合があるということでご説明したものです。","id":"exchange-080"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本当に格差が広がり、貧困が広がるというのが大本の問題としてあるわけですから、やはり株でもうかった分に対しても総合課税にして、格差をなくしていくという方向であるべきだということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"吉田委員","kind":"質問","question":"住宅ローンもそうですし、こういうことの説明とか、そういうのはどのようにされるのかというのを伺いたいと思います。それで、特に(2)と(3)については、(3)は特に記載をしていただかなければいけないわけで、そういうことの説明とかがかなり大変かと思うのですけれども、その点について教えてください。","respondent":"提坂税務課長","answer":"(3)につきましては、今申し上げたような周知方法に併せまして、それぞれの方が給与支払者にこの申告書を出すということがありますので、雇用主のほうにも周知を図っていきたいと考えています。","id":"exchange-082"},{"speaker":"吉田委員","kind":"質問","question":"先ほどのご説明にも繰り返し出てきましたけれども、例えば(2)も、どれが損でどれが得というのは、同じ方であっても、その状況によって随分違ってくるので、同じような条件であっても、そのときの状況によって、損だったり得だったりするということがあるわけで、その辺のことも全部理解していただいて。","respondent":"提坂税務課長","answer":"こちらの制度につきましては、所得税と住民税と連携しているものですので、まず、国税庁のほうでもホームページ等で細かい説明ですとかしおりとかを作ることが考えられます。","id":"exchange-083"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろ大変だと思います。社会保険の関係で、もう亡くなりましたけれども、私も高齢になった両親の代わりに窓口に行ったりすることがあって、そうすると、ほかの窓口に当事者の方がいらしていると、窓口で説明されている方が物すごく苦労されて、声がだんだん大きくなってしまうのです。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、今こうやって物価が急上昇したり、年金生活者や多くの低所得者層の方が増えているではないですか。分かる範囲でいいのですけれども。","respondent":"提坂税務課長","answer":"所得税なり住民税のご負担が重いというのは重々承知しておりますが、その中で、納期限内の納付が難しい方につきましては、国税も地方税も共に、真摯にその方のご事情をお聞きして、分割納付のご相談ですとか、猶予という制度がありますので、その辺を適用させていただいて。","id":"exchange-085"}]},{"id":"topic-06","title":"令和４年請願第７号、軍備拡張をやめるよう国に求める意見書提出を求める請願","agenda":"令和４年請願第７号、軍備拡張をやめるよう国に求める意見書提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"意見陳述をしたいということであれば、ぜひ事前に聞いてから、それを参考にしながらというか、その意見も踏まえた上で委員同士の議論ができると思いますので、最後に聞くというのではなくて、初めにお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"吉田委員","kind":"質問","question":"品川・生活者ネットワークも、やはり委員間討議はとても大事だと思うのですが、その委員間討議に当たっても、この請願者の思いというのを先に伺って、それを踏まえた議論にしたいと思います。ぜひ先に意見陳述をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"西本委員","kind":"確認","question":"委員間の話合いを重視すべきだと思うので、その中において、どうしても判断がつかないと、もう少し確認したいという項目があれば、意見陳述の方法もあるかと思いますが、事前に聞くよりは、むしろ逆で、話合いの中で、聞く必要があるという場合には聞いてもいいと思いますけれども、始まる前に聞くということは、話し合う中で二重になってしまうかもしれないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-088"},{"speaker":"湯澤委員","kind":"意見","question":"請願の文章を読ませていただいて、理由もしっかり記されていたり、内容については理解できるものだと考えています。ご意見はしっかり伝えられているのではないかと思いますので、委員間での議論をするのがいいのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-089"},{"speaker":"須貝委員","kind":"意見","question":"今まで様々、委員会で、こういう意見陳述の場をつくっていただけないかという区民の皆さんの声は、本当にありました。私はそういうやり方でやってきました。説明をする。それは十分、私もほかの場所でこういう話を聞いたり、一緒にお話ししたりしていますので、それはそれでそういう形で酌んでいますから、それ以上またここで意見陳述をしていくというのは、私はやり方としていかがなものかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"須貝委員","kind":"意見","question":"ごめんなさい。それで、それをしていただくかどうかは先に決めたほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"西本委員","kind":"意見","question":"今、決めることは、意見陳述を受けるか受けないか、そういうことでいいのですね。だから、先に聞こうか、後で聞こうかということではなくて、受けるか受けないかということですね。分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"湯澤委員","kind":"意見","question":"先ほどは失礼しました。改めてですけれども、請願の文章を読ませていただきまして、理由もしっかりと記されている、そして、内容についても理解ができていると考えていますので、ご意見はしっかりとこの中で凝縮をされているかと思います。委員同士での議論で進めていくべきと判断しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５年以内に対ＧＤＰ比２％、つまり、防衛費を２倍を確保する必要があるということで述べられましたし、自民党は公約も掲げられたのです。そこら辺のところはどう考えられているのか。私は、こういうことになると、果てしない軍拡競争になっていくのではないかと思うのですけれども、そういう点について、自民党や公明党がどう考えられているのかということで、ご意見を伺いたいと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"須貝委員","kind":"意見","question":"本来なら、この請願の内容は、やはり国会できちんとやるべき話だと私は思います。私は今まで憲法９条は、きちんと日本国民として守るべきだ、厳格に守るべきだと思っていました。そして、家を奪われた。これはやはり考え直さないと、今、我々議員としてあるべき立場で、品川区民を守るためにはどうするのだというのは、我々の一丁目一番地だと思うのです。それがこの２１世紀に、世界で初めて覆されたのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国会でもやるべきだと思います。ああいう形でこの２１世紀に起こっているわけですから、あれだけまちが破壊され、命が奪われていくという、そういうことを目の当たりにして、どうしたら世界平和をつくっていけるのか、日本のこの平和をどうしたら守っていけるのかというところを国民みんなが考えて、本当に考えて突き詰めてやっていかないと、平和というのは守ることができないと思うのです。戦争にさせない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"既に国連という平和機関は、地に落ちましたよね。一方的に攻めてしまって、恐らく１週間か２週間で併合しようと思ったのでしょう。ですが、今、必死になって、ヨーロッパ、アメリカ各地から軍備をくれ、兵器をくれとやっているではないですか。でも、もう外交というのは、普通の外交が通じない国が現れた以上、これは考え直さないと、今までの議論はもう通用しないのではないのですか。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問","question":"これは私見なので、反論があったらぜひお願いしたいと思いますが、私は、全ての戦争は防衛という名目の下に始まっていると思います。それを、場合によっては軍備もというような政党が、食料の自給とかエネルギーの自給を、戦争したいと思っている人ほどまずそれを考えなければいけないのに、そこの政策が全くなくて、軍備だけ増強して、なぜそれで勝てると思うのですかということをはっきり伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今これだけお金がないと言って国債を発行しているというときに、５兆円、６兆円がどこから出てくるのですかということなのです。そういうところで、今回、日本もそういう形で５兆円、６兆円と軍事費を増やしたら、そこのところは、本当に国民の暮らしを、今でもこれだけ大変で、今でもみんなが行き詰まっている、追い詰められているという状況を、もっと深刻にするのではないのですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"},{"speaker":"須貝委員","kind":"質問","question":"鈴木ひろ子委員とお互いに話し合っていていいのかどうか。何しろヨーロッパでも軍事費を増やしたというのは、まさかこの２１世紀にあんな攻撃をする国が現れるなんて誰も思わなかったのです。だから、平和外交、日本だってたくさん外交したではないですか。だって、天然ガスだって石油だって、全部そちらから輸入していたではないですか。食料だって。日本なんかはどうですか。これはずっと平行線だから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"湯澤委員","kind":"意見","question":"自民党ということもありましたので。請願内容にあるように、自民党としても、東アジアに戦争を起こさない、平和の外交こそ必要であるということは思っておりますし、また、世界平和を願う思いは同じであると認識をしているつもりです。いずれにしても、安全保障については、現在行われている参議院議員選挙でも争点になっていますので、ここでの民意に国はしっかりと耳を傾けていくべきかと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これについてはどう思われていますか。それで、今回のロシアのプーチン大統領が、核兵器の先制使用も辞さないということを何度も言っているわけではないですか。そういう立場で、今回のウクライナの戦争を目の当たりにする中で、方針もそのような方向に切り替えていくべきなのではないかと思うのですけれども、そこのところも全く逆ではないですか。そういう点ではいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"今の質問に対するものではないですが、意見として、須貝委員がおっしゃったように、これは私たちで話をするべきレベルではないということがあります。でも、平和というのは何だろうと思ったときに、みんなが同じ土台に立った上での平和ではないですか。それは誰もが選択するのではないのですか。だけど、話もしません。だって、相手が受け入れてくれなかったら、話合いにもならないわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"平和ぼけかどうかということについては、私たちは私たちの観点なりに、平和ぼけではないと考えています。でも、外国に握られているのです。残念ながら、今の外交能力はどうなのかというところはありますので、そのように食料もエネルギーもみんな握られてしまっているわけだから、その辺についてどうなのかというのはありますけれども、先ほどのご発言はぜひその方向で進めていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"つる副委員長","kind":"提案","question":"政府の見解としても、首相の、記者からの質問等も含めて、これはあり得ない、と理解していますし、これは御党の国政におけるお立場の方々も含め、御党としては、沖縄の返還等のとき、協定そのものについては確か反対という立ち位置であったと思いますが、その決議において公明党が当時出させていただいた、国是と言われていて、各政党が言われている非核三原則、これについては公明党からの提案があり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本日結論出すで、態度は不採択です。そうした部分からも、改憲というところではなく、軍備拡張路線ではないというところの、やはりそうした部分があるので、そういう意味からでも、これについては不採択として。その上で、ここに込められているそうした気持ちというのはしっかりと酌んだ形で、自党に所属する国会議員にはしっかり伝えていきたいと。これは付言させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"結論を出すということで、採択でお願いしたいと思います。それから、憲法９条は、日本が侵略国だったわけですから、アジアで２,０００万人、そして、この日本で３１０万人もの人生、命を奪った戦争の上に、二度と戦争はしないという戦争放棄と、軍隊を持たないという憲法９条、憲法をつくり、全世界の信頼を勝ち取ってきたというのが憲法９条だと思います。外交は無意味ではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すということで、採択を主張いたします。先ほど意見を述べさせていただきました。正直に言って、もっと言いたいところはあるのですけれども、この請願には十分賛同できると思います。意見を出すことは必要だと思いますので、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"大倉委員","kind":"意見","question":"いろいろお話を聞かせていただいて、この日本をどうやって守っていくのだというところは、いろいろな考え方があって、いろいろな取組も既にされていると思いますし、これからまたさらに実際にウクライナで起きたような出来事を見たときに、こうやって心配をされて、今まさに世論、参議院議員選挙もやっていますけれども、いろいろな方々がこういうお話をしていくというのは非常に重要だと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。先ほどいろいろと意見を言わせていただきましたが、この考え方というのは、平和実現するにはどうするかというのは、政党それぞれの考え方があると思うのです。ただ、主張は主張で自由ですから。それが広がるかどうかというのは、国民次第というところもあるのだろうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"}]},{"id":"topic-07","title":"令和３年度品川区一般会計予算繰越明許費繰越計算書","agenda":"令和３年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"西本委員","kind":"質問","question":"繰越しということで、主には国が要因というのがほぼ１００％なのかなと思ったのです。令和３年度に執行という形で来るわけですよね。だけど、現場としては１か月もない状況でできるわけがないということだと思うのですけれども、そこら辺は大丈夫なのでしょうか。できなかったら回収、没収、そういう規定はないのでしょうか。","respondent":"黒田財政課長","answer":"国庫補助金等に関連して繰越しするのは、国のほうと調整しまして、区の歳入は国の歳出ですので、国が繰越ししているような前提がありますので、その辺は調整しまして、繰越しについては確認を取っているというところでございまして、執行が完了した段階で、当然。","id":"exchange-111"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"せんだって兵庫県尼崎市で市民約４６万人の個人情報が入ったＵＳＢメモリが一時紛失した問題ですが、これ、まず、尼崎市が大手の会社に、こういう仕事をやってくれということでお願いをしました。でも、ＵＳＢメモリは、その下請、さらにその会社の委託先にお願いをしたということなのですが、品川区もこういう状況なのか。もし今日分からなかったら、明日でも結構なのですが、教えてください。","respondent":"久保田企画部長","answer":"今の件につきましては、今日、情報推進課長も出席しておりませんので、内容を確認した上で、明日、ご答弁します。","id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":90765,"voices":426}},{"id":"r04-20220628-6","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"区民委員会","time":"午前１０時００分～午前１０時３１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","topics":[{"id":"topic-01","title":"（仮称）八潮まちづくり懇談会の開催","agenda":"（仮称）八潮まちづくり懇談会の開催","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"それともう一つは、まだはっきりした構想として見えていないのですけれども、団地の再生ということで考えてもいいのかなと私は思ったのですが、団地の再生というのは全国各地でいろいろ問題になっていると思うのですけれども、そういうことを多分、専門にしていたり、経験済みの方が全国にいらっしゃるのだと思うのですが。","respondent":"中西八潮まちづくり担当課長","answer":"それから３つ目の、団地再生で専門家の方のご意見ですが、こちらの懇談会の中で、例えばこういう講演会をやってみたいというお話が出てくれば、皆様とご相談をしながら、そういったものも検討してまいりたいと考えています。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"ですから、そういう努力をなるべく早い段階からやっておいたほうが、後々結局はスムーズにいったということになるのだろうと私は思うのですけれども、そういうお考えというかお気持ちは、これから始めようという区としては、念頭に置かれているというか、お考えになっているでしょうかという点と、それから、そのやり方の一つとして、よく考えられることですけれども。","respondent":"中西八潮まちづくり担当課長","answer":"広く意見をというお話ですが、まずは地域団体の方、それから各施設の方が、顔が見える関係で、少し連携が取れるような部分ができて初めて、八潮の将来像を考える土台づくりというところを目がけてやっていきたいと考えておりますので、まずそこが整理できてから。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"だから、もう４０年近くになるのですけれども、今さらのように呼びかけてみたら、やってもいいよという方が、４０軒ぐらいのマンションですが、その中でも七、八人、新たに出てきてくださったのです。そういうことがありますので、八潮のまちというのは、私のマンションなどに比べるどころの規模ではないですから、なおさらやっていただきたいと思います。強く要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"塚本委員","kind":"確認","question":"最初に一つ確認なのですけれども、会の構成で、八潮学園、保育園、幼稚園等の八潮地区内に所在する各施設の代表者と。明晴学園は対象として入っているかどうかというのを教えてください。","respondent":"中西八潮まちづくり担当課長","answer":"明晴学園も今回、お声がけさせていただきまして、出席いただく形です。","id":"exchange-004"},{"speaker":"塚本委員","kind":"確認","question":"分かりました。この八潮みらい懇談会ですが、まずは会の構成をされる代表の方々をしっかり会わせて、今後の八潮についてある意味でフラットに、予断を持たずにやろうということでご説明があったので、承知いたしました。確認しておきたいのは、区がそこに対してはどういう関わり方をするのか、立ち位置についてのご説明のことだけ、最後にお伺いします。","respondent":"中西八潮まちづくり担当課長","answer":"区の立ち位置というところでは、この懇談会の事務局という形ですので、懇談会という形でやりますので、会の運営等々、また資料の提供等々は、私のほうでする予定です。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"こういう形で懇談会を開催することというのはすばらしいと思うのですが、何をやるにしても、人口動態というのは大事ですから、根幹ですから、直近で分かる範囲でいいのですけれども、八潮地区の人口はどのぐらいいらっしゃるのか、それで分かれば、大体３段階ぐらいに分かれて、１８歳以下とか、生産人口と、あと高齢者の人口が分かれば、その内訳を教えていただきたいのと、会の構成で、八潮学園、保育園。","respondent":"中西八潮まちづくり担当課長","answer":"目的のところに提言をというお話ですが、まずは懇談会の中で土台づくりを進めていく中で、少し皆様とご相談をしながら、どこの地点をゴール地点にしていくか、どういう形で進めていくかというところも含めて、これから検討してまいりたいと考えております。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"その辺も八潮の特徴の一つだと思うので、その辺も含めて、提言というか、まちづくりに関しての特徴というか、またお困りのこととか、いろいろ出てくると思うので、区が事務局サイドに入るというお話はあったのですけれども、ご意見をきちんといただいて、行政に反映していかないといけないと思いますので、その辺についてもいかがでしょうか。","respondent":"中西八潮まちづくり担当課長","answer":"確かに高齢化というところで、自治会の成り手がなかなかないというお話も聞いてありますので、そういった意味では、地域センターとしても支援をしてまいりたいと考えております。","id":"exchange-007"},{"speaker":"小芝副委員長","kind":"質問・要望","question":"藤原委員の質問に補足で質問させていただきたいのですけれども、先ほど高齢化率が３７％というところで、運河をイメージした勝島エリアの高齢化率は、たしか５％いくかいかないかというところで、どうしても勝島に住んでいる方は当然、八潮にも行きやすい。","respondent":"中西八潮まちづくり担当課長","answer":"そうしますと、勝島から八潮学園に通っていらっしゃるお子様もいらっしゃいますので、少しそういったところでご意見を頂戴できるかなとは考えてあります。","id":"exchange-008"}]},{"id":"topic-02","title":"ＬＩＧＡ.ｉブラインドサッカートップリーグ２０２２の開催","agenda":"ＬＩＧＡ.ｉブラインドサッカートップリーグ２０２２の開催","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"目的の中にも出ているのですけれども、これは東京オリンピック・パラリンピックのレガシーの一つだと考えてもよろしいのでしょうか。","respondent":"辻スポーツ推進課長","answer":"委員おっしゃいますとおり、東京２０２０大会のレガシーの大きな一つとして捉えております。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"もし伺っていることがあまりにもかけ離れていたら、委員長に止めていただければいいのですけれども、オリンピック・パラリンピックが去年終了して、組織委員会もたしか解散したというニュースが報道されていましたが、品川区においても、課長が前職でやられていたオリンピック・パラリンピック担当の課というのがあったわけですけれども、それも今の時点ではなくなってしまって。","respondent":"辻スポーツ推進課長","answer":"決算関係のものに関しても、スポーツ推進課で担当して実施するということになっております。","id":"exchange-010"},{"speaker":"塚本委員","kind":"確認","question":"この前、体操の競技だったか、何か分からないけれども大量に買われていたのですが、実際にはその日、誰も来ていなくて空き席ばかりで、あれは収支的には何があったのか、もしかしたら別に来なくても、収支はお金を払われているので大丈夫という話なのかもしれないのですが、真相は分からないのですけれども、運営自体は多分、品川区がやるわけではないと思うので、このリーグの。","respondent":"辻スポーツ推進課長","answer":"今回のＬＩＧＡ.ｉに関しましては前売りのチケットで、前売りで決済といいますか、料金はもう支払ったという形にはなりますので、予約席を売ったのにお金を取りはぐれるといいますか、そういった心配はないと聞いています。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10372,"voices":44}},{"id":"r04-20220628-7","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"厚生委員会","time":"午前１０時００分～午後 ０時１３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"意見","question":"初めに、予定表１、報告事項を聴取いたします。本件につきまして、理事者より一括して説明願います。","respondent":"菅野高齢者福祉課長、池田国保医療年金課長","answer":"2)感染症の影響により、生計主の事業収入等の減少が見込まれ、下のアおよびイの要件を満たす第一号被保険者については、一部減額または全額免除となります。私からは、新型コロナウイルス感染症の影響によりまして、世帯の主たる生計維持者の収入が減少見込みとなることによりまして。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこはやはり大変なところだと思います。収入が減った額で保険料が算定されるとはいえ、１０９万円の収入の方に、１５万円の年間保険料の請求が来るわけです。減免されて、生活を支援されることはありがたいのですが、もう少し区のほうからも国に対して、３割減ったままの収入が続いている方に関しても、ぜひ減免を続けていくことを求めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"池田国保医療年金課長、菅野高齢者福祉課長","answer":"昨年の収入ではなく、昨年の収入と比べて１０分の３減る見込みがある方に対して、減免する形になってまいります。私からも、コロナで３割収入減の見込みの方への減免について、お答えします。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国保については、今現在もただでさえ高い国保料ということで、毎回引き下げを求めています。そして１８歳以下の子どもの保険料、均等割の廃止ということも求めていますけれども、やはり、コロナと物価高騰が今ダブルで来ている状況ですので、ぜひさらなる減免、支援策を、国にも求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ＰＤＣＡサイクルがどういうふうにされて、分かりやすくしてほしいという要望を、私たちはしていました。２ページのところ、障害者グループホームを５か所、新規開設を行ったということですけれども、重度の方や医療的ケアが必要な方のグループホームの要望も、結構あると思うのです。実績があれば教えていただきたいのと、これは誰に対して、どのように周知して、どう使われたのか、知りたいです。","respondent":"松山障害者支援課長","answer":"区としましては、これまでも民間のグループホームを区内に誘致したり、あるいは開設を実施してきたところ、５か所とも、主に精神障害者の方、あるいは軽度の知的障害者向けのグループホームを開設することができました。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"新規事業所の誘致を図るということですけれど、具体的にどこに対して、どのような働きかけをするのか、あれば伺いたいのと。それで、その下の行動援護は、ずっとゼロで、令和３年度の見込みは１人で８６時間とあるのですけれど、ずっとゼロなのはなぜなのかということと、都内にサービス提供できる事業所というのは、あるのでしたか。確認させてください。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"保育所等訪問事業所の誘致についてです。障害児通所支援事業所と定期的に相談を行っていまして、実際に興味を示している事業所があるということは聞いております。重度障害者等訪問支援ですけれども、こちらは区内に事業所はございません。都内のほうも事業所は本当に少数となっておりますので、今後とも、事業者誘致に努めていきたいと考えております。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それと、１５ページの障害児相談支援についてですけれど、これを請け負っているのは品川区の中で１か所かと思うのですけれど、今、障害児相談支援事業所というのはどれくらいあるのか、伺いたいと思います。その災害時個別支援計画を作成済みで、自家発電装置は実際に何件給付実績があるのか、今の時点で分かれば教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"１点目ですけれども、障害児の相談支援、いわゆる計画相談、ケアプランを作る事業所ですけれども、子どものほうは９か所あります。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。それと、移動支援のところでお伺いしたいのですけれども、以前、従事者を養成するという研修を、区で委託してやるということだったと思うのですけれど、今年度は行われるのか。どこかに委託されるのか、それとも区独自で行うのかを伺いたいです。","respondent":"松山障害者支援課長","answer":"１点目、移動支援従事者研修についてです。今年度も引き続き、品川区立心身障害者福祉会館に委託をしておりまして、移動支援従事者研修を実施していただく予定です。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。そうすると、心身障害者福祉会館で移動支援の研修ということで、前年度とか前々年度はされたのでしょうか。最後に伺いたいと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館におきましては、令和２年度、３年度と実施いたしまして、それぞれ１５名の方に、受講していただきました。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"大きく２点お聞きしたいのですけれど、まず保育所等訪問支援です。その背景には、質の整っていない事業所があったり、ここに通いたいのだというご家族の意向があったりして、結構自前の方がいらっしゃるのですけれど、そこに対する区の考え方をお聞かせいただきたいと思います。","respondent":"松山障害者支援課長","answer":"１点目の、保育所等訪問支援の今後の周知についてです。周知に当たりまして、地域自立支援協議会の子ども支援部会のほうで、事業所同士、話をしまして、やはり保育所等訪問支援の関係機関への周知が必要だということで、共通認識を図りました。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"それぞれありがとうあります。保育所等訪問支援ですけれど、先ほど校長会へもということだったので、中学校は人数が少ないかもしれないですけれど、小中学校への周知を図っていただきたいと要望いたします。それで、今、すまいるスクールが抜けてしまっているのです。それと、セルフプランなのですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"６ページの児童学園ですけれど、指定管理者が関わるのですけれど、相談事業についてはほかの委員の方もこれまでにご指摘されていますが、例えば相談まで時間がかかるとかありましたけれども、その点で今後、次の指定管理者に、機能の充実とありますのでどういった点を求めているのか、ということがあれば、お願いします。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"就職よりも、その後、安定して働き続けることができるかというのが大きな点だと思いますので、そこを保つためにも今後、企業や職場への障害者に対する理解の促進にも、力を入れてまいりたいと考えております。相談待ちにつきましては、お子さんの貴重な発達の機会ですので、できる限り短縮するよう、相談支援から支援の間の流れを、関係機関を踏まえてもう一度検討し、整理しています。次に、保育所等訪問支援についてです。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。一般就労への移行は、課長がおっしゃったように就職した後の定着の部分の支援と相談が必要と、難しいけれども非常に大事なところなので、ぜひそういった、就労支援の事業所にもそういったアドバイスというか、区でも支援しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３ページのサービス給付実績と利用件数のところで、先ほど丁寧に説明いただいたのですけれど、住所地特例は、特定施設と特養ホームのところで何人ぐらいいるのか、分かれば教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"特定施設の住所地特例の方ということですけれども、制度的な説明につきましては、１０ページに注意書きとして記載しています。第一号被保険者のところで住所地特例は、令和３年度で１,２０５人となっております。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"確認","question":"そうすると、計画には第９期から第１１期で１５０人から２００人だと思うのですけれども、１期３年間なので、第９期から第１１期で９年間になると思うのですけれど、この９年間で１５０人から２００人と、計画としてはそう考えられているということでいいのでしょうか。要するに、９年間で１５０人から２００人という整備計画で、これが品川区の計画ということでよろしいのか、そこを確認させてください。","respondent":"寺嶋福祉計画課長","answer":"特養ホームの整備計画につきましては、考え方として２つありまして、まず、一定程度まとまった敷地がないと建設ができないというところも踏まえまして、ある程度現実的な数字を出すです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、計画的に増設を、目標を立てて進めていただきたいというのは、改めて求めたいと思います。それと、別の質問になるのですが、１３ページの配食サービスです。２年が経過した今、区内の高齢者の状況というのは、区としてはどのように見られていて、コロナの状況次第になってくると思うのですけれども、どういう対策が総合的に必要になってくると考えているのか、教えていただきたいと思います。","respondent":"菅野高齢者福祉課長、川原高齢者地域支援課長","answer":"ただ、認定の件数としましては、今のところ、そんなに大きな伸びはありませんで、今後、だんだんコロナがあけていくことによって、認定件数も伸びてくる可能性があるのではないかというところで、その辺りしっかりと状況を見極めて。今年度は実施している状況です。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"先ほどご説明いただいた減免制度と違って、こちらの傷病手当は、延長期間が３か月となっているのはなぜなのか。先ほどの保険料の減免は１年を通してなのに、こちらは３か月というのはなぜなのか、伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"もともと、この傷病手当金につきましては、被保険者の方が感染した際に休みを取りやすい環境の整備ということ、それから感染拡大の防止ということでできたものでございまして、国のほうから、こちらの傷病手当金をつくる際に発せられました通知によりますと。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"意見","question":"この傷病手当は、この間、延長、延長という形で来ていると思うのです。それで収まる状況ではないというのが分かっているのに、なぜかと思うところですが、そこは国が決めていることなので、分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"コロナですけれど、またここ最近、東京都の新規感染者数が２,０００人を超える、前の週を上回ることが続いていると思うのですけれども、今、東京都でもインフルエンザと同時に感染が広がっていくということも言われている中で、本当に先が見えないことなので、どこまでというのはあると思うのですが、やはり備えておく、感染爆発させない対策が必要だと思うのですけれども、区としては。","respondent":"坂野保健予防課長","answer":"はワクチンを進めていくということが、対策としてはあるのかなと思います。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"提案","question":"今、ご説明があったように、第６波まで経験しているというところでは、第４波の時から第５波が来るから対策を、第５波の時は第６波の対策を、押さえ込もうと言ってきたのですが、感染が爆発して医療逼迫が起こる状況になってしまったので、助かる命が助からないという状況をつくり出さないためにも、今から何をという提案はなかなかないですけれど。","respondent":"秋山保健整備担当部長","answer":"３回目の接種ですけれども、もちろん３回目の接種も含めて促進させていきたいと考えています。","id":"exchange-021"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、個人情報保護評価の対象となるのは様々あって、予防接種がその対象で、その対象人数が３０万人を超えなければ、この評価はしなくていいものなのでしょうか。それで、パブリックコメントということで、区民に意見聴取というのは、どういう意見を求められて、何を発すればいいものなのか、そしてこの評価というのは、区がやるのですか。すみません、そのところを教えてください。","respondent":"秋山保健整備担当部長","answer":"これは、全てやらなければいけなくて、ある程度ニーズが大きくなると重点項目評価、３０万人以上になると全項目評価ということで、対象人数によってＰＩＡのレベルが上がっていくというふうにお考えいただければと思います。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、この特定個人情報保護評価は、この間品川区でやられたことはあったのでしょうか。第三者点検は、区が委員会をつくってやるとおっしゃったのですが、そうすると第三者が区なので、これ自体を評価するというのは、評価書を作るのは区がやるということになる、そして区が、第三者点検をする、ということなのですか。","respondent":"秋山保健整備担当部長","answer":"その作った評価書に対して、第三者の点検を区が受けなさいということで、品川区の場合はこの第三者点検については、品川区情報公開等審議会がありますので、その下部組織として、ＰＩＡの第三者点検の会議体をつくっておりますので、そこでパブリックコメントの意見を付して。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問","question":"ほかにありますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"委員の皆様よりいただきましたご意見、ご要望を踏まえ、正副委員長で検討させていただきました結果、今年度の厚生委員会の所管事務調査につきましては、お手元に配付のとおり、「認知症対策について」、「障害児者支援について」、および、「がん対策について」の３項目とさせていただきたいと思います。以上、簡単ではありますが、説明させていただきました。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問","question":"予定表３、その他を議題にします。初めに、(1)、議会閉会中継続審査調査事項についてですが、お手元の申出書案のとおりでよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あくつ副委員長","kind":"質問","question":"(2)、委員長報告についてです。昨日の議案審査の結果報告については、正副委員長にご一任いただけますでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3634#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":33449,"voices":83}},{"id":"r04-20220628-8","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"建設委員会","time":"午前１０時００分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(2)令和４年７月区営住宅入居者募集","agenda":"会議の運営上、予定表の順番を入れ替えまして、(2)令和４年７月区営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の募集は４戸ということで、その場所をご説明いただけたらと思います。今回募集される住宅の傾向というのですか。この間の募集倍率などもご説明いただけたらと思います。","respondent":"竹田住宅課長","answer":"過去の倍率ですが、直近では今年１月に募集がございまして、このときが平均で３７.８倍ということです。ちなみに昨年の７月が平均で３５.６倍、その前の令和３年１月が９１.３倍、令和２年７月が７４.３倍となっています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"とても高い倍率だなと改めて思いました。ぜひ区営住宅の増設に向けて、区としてもやっていただきたいと思います。それがやはり住民に良好な住宅を提供するということになると思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"こんの委員","kind":"質問","question":"１点だけ、今後の募集の仕方というところで、こんなことはできますでしょうかというところをお聞きしたいのですけれども、今これは配布、紙媒体でのやり取りになっていますが、やはり電子という流れの中で、この公表の時期に、ホームページで空いているお部屋を見られる、あるいは申込書のダウンロードができるなどということが今後必要になってくるのかなと思われます。その点はいかがお考えですか。","respondent":"竹田住宅課長","answer":"区営住宅についても、そういった点を今後検討していかなければならないと思いますが、区営住宅はご高齢の方の応募が多い。あるいはパソコン等のシステムの環境をお持ちでないという方もいらっしゃるので、そういった点も含めて、今後導入に向けて考えていきたいと考えています。","id":"exchange-003"},{"speaker":"こんの委員","kind":"提案","question":"高齢者の方の申込みが多い。それもそうだろうというふうには思います。高齢者の方の代わりに、お知り合いの方や地域の方、パソコンを持っている方がお手伝いということもできるかな、地域での支え合いができるかなと考えることもできるかなと思います。今後こうしたことも考えていかれたらどうかなという提案というか、要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-02","title":"令和４年８月都営住宅入居者募集","agenda":"令和４年８月都営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"先ほども伺いましたが、応募倍率をこちらでも伺いたいのと、あと７月２２日にプレス発表ということですが、今回の傾向というのですか、区内の傾向等、分かるところがありましたらご説明いただけたらと。","respondent":"竹田住宅課長","answer":"倍率ですが、今回ポイント方式で行われますが、前回は２月にポイント方式が行われております。このときは、８団地１９戸。倍率が一番低いもので２倍、一番高いもので７３.０倍となっております。全く分からないですが、例年どおり行われるものと考えております。","id":"exchange-005"}]},{"id":"topic-03","title":"広町二丁目土地区画整理事業の進捗","agenda":"広町二丁目土地区画整理事業の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"資料のところで少し伺いたいのですが、Ａ３の資料で、権利指数というのが、従前の場合は権利指数、仮換地後の場合は評価指数となっておりますが、おおむね一致していますが、完全には一致しません。そこを伺いたいのと、あと、仮換地をしたときのＢ－２街区が、区有地と共有地に分かれていますが、これはどこが区有地、どこが共有地になるのか、ご説明いただけたらと思います。そこを伺いたいと思います。","respondent":"多並都市開発課長","answer":"位置については、これからまた具体的な説明を受けますが、基本的にはこの北側に設置される予定と、今は聞いております。１１５億円の事業費ということで、先ほどご説明させていただきました。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"区有地と共有地のところでは、Ｂ－２街区の北側に共有地の部分が来る考え方ということですよね。南側が区有地、単独の区有地になるという。改めて確認させていただきたいと思います。今回、保留地の位置が明らかになりましたが、Ｂ－２街区の一部にも保留地の部分があります。ちょっとそこを伺いたいと思います。資料で見ると、宅地の持つ性格というところに入るのかなとも思いますが、そこを伺います。","respondent":"多並都市開発課長","answer":"各権利者、おのおのがやっていきます。今、その説明の中では、北側に共有地を設置するという説明を受けており、これからそれを行っていくというところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"分け方としては、この３つずつぐらいの分け方になるということですか。考慮する項目はどういうものがあるのかを、ちょっと伺いたいと思います。保留地のところはなかなか答弁しづらいのかもしれませんが、そうすると、売却先はどこか全然違うところ、ほかの民間の企業などに売られてしまうといったことはないということでよろしいのでしょうか。","respondent":"多並都市開発課長","answer":"その中に形状に関することがありまして、りんかい線については、先ほどご説明させていただいた０.７を乗ずると書いてあります。これを基本としながら行っていくと。","id":"exchange-008"}]},{"id":"topic-04","title":"品川区まちづくりマスタープラン改定に向けた検討状況","agenda":"品川区まちづくりマスタープラン改定に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"Ａ３資料の６ページで、将来の都市構造ということで若干修正があるというお話だったと思います。今回これを見ると、新たに立会川、中延が拠点に加わっているのかなと思います。この変更点と、特に立会川、中延を拠点とした理由を伺いたいと思います。７ページでは、開発によって質の高い都市空間を創出すると書いてあります。再開発を進めるのはやめるべきだと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ひと中心の質の高いです。全体的に、例えばですが８ページの分野別のまちづくり方針のそれぞれの分野において、まちづくりの目標と方向性を現計画でも定めております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"６ページの将来都市構造のところで、中延も新たに加わっているのかなと思います。そこの理由を伺いたいと思います。そうではないやり方というのもあるわけですから、ぜひ、そうした再開発に頼らないまちづくりを進めていくべきだと思いますが、いかがでしょうか。１つは、先ほど来言っている開発などを行っていくということはやめていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区としても、今現在位置づけている荏原中延駅ですとか戸越公園等の位置づけと同じぐらい中延駅は拠点性を持っているという認識もしております。地域生活拠点ということになるかと思いますが、今回新たに拠点として位置づけすると。上位計画との整合という観点からです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"２３区の中でも、再開発事業に投入した税金の額はトップクラスとなっております。そうした再開発ではないやり方。組合施行になると、同じような仕組みで、強制的に所有権を取られてしまうというのもあるので、そういったところは控えていただきたいと思いますが、住民合意でしっかりまちづくりを進めていくということがやはり重要だと思います。そこを重視していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"資料４ページのまちづくりの課題について、確認というかイメージを具体的に教えていただきたいのですが、何点かあります。ここに記載されているのは、イメージとしての言葉の表現になっているので、それをより具体的にちょっとイメージを教えていただきたいというか、具体的に教えていただきたい。質問です。だれもが安心して住むことができる住宅施策の充実が求められていますと。その３つを教えてください。","respondent":"鈴木都市計画課長","answer":"１０年ぐらい前から、そうした自然が持つ機能もしっかり活用していきましょうというところで、これは、近年のまちづくりの方向性を示す考え方として、国でもしっかりうたわれています。そうしたところを整理して書かせていただいております。住まいのところです。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"イメージが分かりました。この後、次の会議のときに、そうした具体的なものが出るということなので、イメージは分かりました。この視点は非常に大事だろうと思います。どうかこの点、具体的に住める、また住みたい、住み続けたいという気持ち、思いを具体的に今後も支援できるような、また、充実できるようなものに、マスタープランとして方針をしっかり決めて進めていただきたい。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはまちづくりマスタープランなので、そこまでどうなのかなというのですか、例えば９ページなどは、成果が書いてあるわけです。これでいいのかというのがあるではないですか。こういうのを読んでいると、あるではないですか。これ、すごくいいものができるのだろうと期待をしていますけれども、そういう部分の表現方法とか、今後どうしていくかみたいなものというのは、何かあったら教えていただきたい。","respondent":"鈴木都市計画課長","answer":"より地区別の木密、そうでないところと、やはり木密の地域の中でもちょっと取組みを進めていかなければいけないところはそうなのですが、その辺の色分けが、ちょっと現行計画では、土地利用の方針でも。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。１５ページを見ていて、これはいいのかなとちょっと思いましたが、都市生活と住まいの方向性というのがあり、空き家について書いてあります。これはこれでいいのですが、これ、八潮の０というのは、空き家という概念がもともとないですよね。書くなら、空き家よりも空き住戸というのもあるではないですか。これは要望だけにします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"自転車安全利用指導員事業","agenda":"自転車安全利用指導員事業","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"５か所の交差点でやられているということで、選定方法の中に交通事故多発地点も踏まえてと書いてありますが、やはりこの５か所が多いのですか。というか、どのくらい多いのかというところをちょっと伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"ご質問のこの５つの交差点で事故がどのくらい多いのかです。警視庁が提供している事故の発生状況、ヒートマップというものがあります。具体的な事故件数というものはこちらでは把握しかねるのですが、そのヒートマップの密度の濃いところを優先して選んでおります。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"なるほど、分かりました。少しずつ区内でも自転車が関与している事故件数が増えているということですが、その背景的なところなど、今分析しているところがあれば伺いたいのと、今回、違反別の件数として逆走が１８５件、徐行違反が１６５件ということですが、これが具体的にどういった違反なのかをご説明いただければと思います。","respondent":"工藤交通安全担当課長","answer":"２点ご質問頂いたと思います。１点目の背景です。資料左上のグラフを見ていただきたいと思います。平成２９年から令和３年までの事故の自転車関与の件数をグラフにしております。平成２９年、平成３０年、令和元年と、おおよそ横ばいという推移です。","id":"exchange-017"},{"speaker":"芹澤委員","kind":"確認","question":"ちょっとだけ確認です。イヤホンというのは、直ちに駄目というのではなく、たしか音が聞こえるかどうかみたいな話であったと私は認識していますが、どういう感覚で指導員の方がやってらっしゃるのかなというのと、今、高齢者の方も自転車に乗るタイミングが結構多いかと思います。そういった方々に対しての指導というか、指導員への啓発というのはどのようにされているのか、お聞かせください。","respondent":"工藤交通安全担当課長","answer":"両方の耳にイヤホン着装というのはなかなかいらっしゃらないのかなというところがあります。明確に補聴器だと分かれば、それはもう指導はしません。両方の耳にしていれば、一旦止まっていただいて、確認をした後、対応するという要領で行っております。","id":"exchange-018"},{"speaker":"こんの委員","kind":"確認","question":"実施方法について確認させてください。警察署と連携して制服を着た警備員ということですが、そうすると警備員の方は警察のＯＢとかそういう関係の方なのか。警備員はどういう資格を持っている方なのかというのが１つです。先ほど、実施されている時間帯は昼間というお話がありました。昼間の何時頃で、１か所何分ぐらいそこで指導されているのかということ。その場所と実施方法を確認させてください。","respondent":"工藤交通安全担当課長","answer":"こちらの方々については、警察ＯＢではございません。ただ、警備員として、区民への適切な対応、あとは服装等、交通法規の講習を受けた者が実施しております。これは余談ですが、併せて救命救急士の資格を持った方も１名入るようにしております。活動時間です。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"警察の重点地区路線を基に決定したということですから、それはそうなのだろうと思いますが、イトーヨーカドーの前とかこの区役所前の交差点とか、やはり自転車が行き交うたくさんのところがあります。本当にその場で取り締まってほしいぐらいの勢いでやらないと。たしかあれは私が役所に来る時間ですから、出勤の時間です。そういう点についても、どんなふうにお考えなのか、その点も教えてください。","respondent":"工藤交通安全担当課長","answer":"この社員の方々には、４月に試験的実施をする前にも、交通法令や区民応接等の研修を受けていただきました。１０月にも再度研修を受けてもらう予定です。なので、一般の方が指導員をできるかといったら、それはちょっとできないと。現在のところはそういうところです。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"最後の点は、確かに非常に難しいです。まちの中でそういうことが行われているということが分かると、やはり注意するようになります。警備員さんたちも本当に安全にこれからも進めていただきたいと思います。は選定した場所でやってみて、これが抑止力になる、また効果が出るのかというところは、私も非常に注目していきたいと思いますので、どうか今年１年、まずは頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは、今、啓発も含めてやっているということでありますが、まず、自転車が関与する事故をどれぐらい減らしていこうとお考えなのかという、まずそこがあるではないですか。全体としてどれぐらいあると思われているのかというのもあるではないですか。そういうことはたくさんあると思いますが、では、これを最終的にはどうしようかというのがあるではないですか。そういうのをどうお考えになっているか。","respondent":"工藤交通安全担当課長","answer":"はっきり言って想像もつきません。違反しているのが何台というのは、お答えできない状況です。ただ、指導員が活動している中での肌感覚では、１０台に１台ぐらいは自転車利用者は違反しているのではないかという。これはあくまでも肌感覚のお話ですが、そんな感覚を持っていると。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これはどういうことがいいのかというのはありますが、例えば城南小学校の通学時間は、あそこは旧東海道で、標識が一応あるのです。これはよく分からないけれど、一月に１回でも継続していれば、効果はずっと長もちすると思うのです。警察のこともよくご存じでしょうから、そこら辺のところも警察と連携してやっていただければありがたいと思っています。これは要望だけにします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西村副委員長","kind":"質問","question":"走っている方にも声をかけていただいているということで、その場で注意していただくということが大切かなと私も思います。今、石田委員もおっしゃっていましたが、本当にスピードを出す自転車がとても危険だなと思う中で、よく意見が出ますが、デリバリーの方とか、子どもを前にも後ろにも乗せている、いわゆるママチャリの方をどれぐらい発見されて、指導されたかという状況が、もし分かれば教えてください。","respondent":"工藤交通安全担当課長","answer":"指導員の方もこれはおっしゃっていましたが、なかなかそこら辺は難しいのだろうなと思います。奥様方にお声をかけて注意をすると、分かりましたとすごく素直に聞いてくれますが、こちらのほうもやはりデリバリーと同じぐらいの割合でいるのではないかなと感じております。","id":"exchange-024"},{"speaker":"西村副委員長","kind":"質問","question":"ママチャリは、特に自転車自体もすごく重く、そこに子どもが乗ってさらに重くなっていて、大変危険だなと思っています。１点だけすみません。電動キックボードが最近区内でも増えています。こちらも何か指導される対象になっているのか、対象外なのか。それだけ最後にお伺いします。","respondent":"工藤交通安全担当課長","answer":"歩道を走ればそれは違反になりますので、走っているのを見かけたら一旦は止める。ただ止めて、交通法規について注意喚起するということで指導をしますが、今のところ指導員が電動キックボードを止めて注意喚起を行ったということは、現在までございません。","id":"exchange-025"}]},{"id":"topic-06","title":"電線共同溝等工事の委託（競馬場通り）","agenda":"電線共同溝等工事の委託（競馬場通り）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"この競馬場通りのところは、品川区の無電柱化推進計画だと、整備延長が約４００メートルということになっていますが、今回２００メートルの契約になっている理由を伺います。","respondent":"森道路課長","answer":"その後、第２工区としてなぎさ会館までの区間を施工するという予定にしております。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"１点だけお聞きしたいと思います。先ほどの工事の手法から見て、予算についてです。今まで一般的な方法を取っていた。でも、今回は既存のものを使わせていただくということです。これまでの手法でしたら、この金額より契約金額が高くなると予想されますが、その点はどのような感じになるのでしょうか。","respondent":"森道路課長","answer":"今回の手法につきましては、この２００メートルの区間のうち約６０メートルで、東京電力パワーグリッドの施設が使えるだろうと今、考えております。","id":"exchange-027"},{"speaker":"こんの委員","kind":"意見","question":"ということは、今ご説明いただいたように、無償で活用するというのは大変にありがたいお話だなと思います。とにかく大事な工事ですので、無事故で進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"芹澤委員","kind":"確認","question":"すみません。単純な確認です。今回の手法について先ほどもお話がありました。既存管路というのは、そもそも何が入っているのでしょうか。今回、工期が短くなると伺いましたので、今後、無電柱化を進めるに当たって、品川区内の既存管路を活用できると非常にいいのかなと思います。どれぐらいあるのかというのも、もう把握されてらっしゃるのか、教えてください。","respondent":"森道路課長","answer":"今回の手法につきましては、工期も短く、安くできるだろうと考えておりますので、今後、対象となる路線でそういったものがあれば、積極的に使っていきたいと考えています。","id":"exchange-029"}]},{"id":"topic-07","title":"八潮北公園野球場等改修工事および管理事務所改築工事","agenda":"八潮北公園野球場等改修工事および管理事務所改築工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"資料についてですが、もう少し野球場の面積や建物の図面といったところも、ぜひ載せていただきたいなと。今後の説明では資料で見せていただきたいなと思いますので、よろしくお願いします。いかがでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":37195,"voices":102}},{"id":"r04-20220628-9","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"文教委員会","time":"午前１０時００分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"学校改築の進捗","agenda":"学校改築の進捗","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"３点お伺いします。１つは、学級標準が３５人になりましたけれども、それ以後の建て替え、改築の実施設計ということで、３５人学級編制になったことで、学校の設計に当たって、従来と違った、新たに考慮していることなどは何かあるんでしょうかということを、まず、お伺いします。どういう考え方を持っていらっしゃるのかということをお伺いするのが２点です。","respondent":"森学校施設担当課長、矢部教育総合支援センター長","answer":"３点ご質問を頂きました。１番最初、３５人学級編制となり設計に変更があったかということです。基本的には、３５人ということで設計をしております。２点目の特別支援学級と教室の考え方ですが、様々でございまして、基本的には、大きな計画の中で、学級によっては、静かに学習させたいということで、できれば通常学級から離れてというご意見もあるし、逆に、何でそんなに離すのだ。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"そのようなお声というのは、やはり当事者の家族の方も、団体からも聞かれたりしますので、通いのほうは私もあまりよく言えないのですけれども、日常的に学校に入っている特別支援学級については、ぜひそのような配置を基本にしていただきたいのですけれども、いかがでしょうか。やはり早急に建て替え候補の中にぜひ入れていただきたいと要望いたします。","respondent":"矢部教育総合支援センター長、森学校施設担当課長","answer":"特別支援学校のお子さんも副籍で入っておりますけれども、そちらも、直接交流したいという方と、いや、もう本当に学校があるだけでいいという方がいらっしゃるので、その実態実態に合わせて、交流は進めているという現状があります。改築の順序等につきましては、就学人口数、老朽度具合、地域のバランス等を踏まえまして、適切に検討してまいりたいと思います。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問","question":"城南第二小学校のところから伺いたいと思います。先ほど、改築に当たって、体育館は新旧両方とも使えるというお話があったと思うのですけれども、プールはどうなのかなという部分を伺いたいのが１点です。先ほどの特別支援の質疑の中で、その地域性によって、通常級に近いところと、そうではないところがあるというお話だったと思うのです。図書室がどこにあるのかということも教えてください。","respondent":"森学校施設担当課長、矢部教育総合支援センター長","answer":"プールですけれども、まず、ステップ１の時点だとプールは使えますが、ステップ２に移ってきますと、プールは解体してしまいますので、使えなくなります。体育館は、新旧どちらかが常に使えるような状態で計画をしております。特別支援教室だけについては、やはりどちらかというとにぎやかなところが苦手なお子さんたちが多いので、静かなら近くてもいいのかもしれませんけれども。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"ステップ２のときにプールが使えないということでした。令和７年度の時点で使えないということです。そうなると、夏の期間がかかってくるときに、プールの利用というのは、近隣の小学校や学校から借りるのかというところを少し伺いたい。なので、子供たちにちゃんと理解が広がるようなお知らせをぜひしていただきたいなということを伝えたいと思います。何かあったら、お答えください。","respondent":"森学校施設担当課長、矢部教育総合支援センター長","answer":"プールの件は、委員ご指摘のとおり、令和７年度になりますと使用ができなくなりますので、近隣の学校に貸していただいてという対応になると存じます。特別支援教室の学級も、通常のお子さんたちの理解はすごく大事だと考えています。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"プールについては、現時点では、貸してくれる学校が決定していないということでいいですかということを確認したい。たしか、以前、今後の改築の資料が一覧であったかなと思うのですけれども、探し切れていなくて、もしあれば、いつの資料ですということを教えていただけたら助かります。","respondent":"森学校施設担当課長","answer":"ただ、児童・生徒が急増しているようなところでは、改築を進めなければならないと考えています。プールですけれども、今の時点ではまだ具体的には進めていないとは思いますけれども、近々、近隣のところで、学校のほうで調整を行いまして、借りていくような形になるかと思います。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"改築計画というものが、どこかに今後の改築はどこをやっていくというものがあるのであれば、お知らせいただきたいのですが、いかがでしょうか。","respondent":"森学校施設担当課長","answer":"しかし、委員がおっしゃるとおり、いずれ逼迫してくる状況になるかもしれませんので、その辺を含めて、ほかの地域でもさらに改築してほしいという、安藤委員が言われました三木小学校などありますので、その辺を含めてしっかり検討していきたいと考えています。","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問","question":"ご説明ありがとうございました。まさに、一般質問でも少し入れさせていただいているような話の中で、１つ心配なのは、結局、城南第二小学校の辺りは、まだ増える可能性もあり、今年の入学者数で見ても、実は、全員入学したら、当然、３クラスでは足らない。それで、多目的室を全部潰したとしても、４クラスということは１４０人。今回、多目的室をつくってでも４クラスで収めた。考え方をお聞かせください。","respondent":"森学校施設担当課長","answer":"城南第二小学校につきましては、２４クラスで、令和２１年度ぐらいまでは十分賄えるのですけれども、城南小学校のほうでかなり多くなってきますので、その辺も含めて、城南第二小学校でカバーできないかどうかという検討はしております。","id":"exchange-007"},{"speaker":"渡部委員","kind":"確認","question":"でも、良好な教育環境をつくるのが大前提なわけだから、そのような状況を逐一お伝えしつつ、そのようなこともあり得るというのは、僕は逆に言っていってもらったほうが、それは統廃合という考えではないですが、現実にある学校の中でどう回すかということなのだから、そういう作業も大変かもしれないけれども、やってほしいなという思いから一般質問もやりましたので、少し付け加えします。答弁は結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。聞き忘れていたことがあります。その部分の考え方、子どもたちの体への負担が少し大きくなっていることがあるなと思うので、もしお答えができるようであれば、それが１点です。その部分の考え方というか、どのような対策をされるのかというところを伺いたいと思います。","respondent":"森学校施設担当課長","answer":"高さというところですけれども、一応、普通教室は４階までとなってございまして、５階の部分は、特別教室になってありますので、基本的には４階までで、恐らく、２階が１・２年生、３階が３・４年生というふうに。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"工事が行われて、第四日野小学校についても、その窓ガラスの対策がされているのかというところ。これはもう要望なのですけれども、やはり子どもたちの荷物の重さというのを考慮していただいて、何かしらの対策を。子どもたちの荷物はとても重くて、特に中学生はすごく重くて大変そうだなと思うので、もう一回、そこのところをきちんと考えて、子どもたちの体に負担がないようにしていただきたいなと思います。","respondent":"森学校施設担当課長、矢部教育総合支援センター長","answer":"浜川中学校ですけれども、こちらは国道が隣にありますので、こちらの対応をすると同時に、遮音性について高まっている形になってあります。ただ、荷物につきましては、各学校、それぞれ実態を捉えて配慮しているように聞いています。いろいろな考え方もありますので、お子さんと保護者と対話しながら、適切に工夫していきたいと考えています。","id":"exchange-010"},{"speaker":"若林委員","kind":"質問・要望","question":"すみません、素人考えですけれども、授業以外の家庭や登下校を、ある意味活用して、過度な負担はいけないだろうけれども、ただ、適度な負荷は、子どもたちの体づくりのために必要だという言い方も当然あるのだろうなと思うのです。この辺はどのような考え方というか、知見があるのか、教えていただきたい。","respondent":"矢部教育総合支援センター長","answer":"荷物の件でお答えいたしますが、委員がおっしゃったように、そのような考え方の保護者もいらっしゃると思います。ただ、荷物を持つというのは、学用品を勉強のために持ってくるわけで、体力のために背負っているわけではないとは考えています。","id":"exchange-011"},{"speaker":"若林委員","kind":"確認","question":"今、地域との協働という意味で、まさにその協働をされている方々からも声が上がっているということで、そこに、おもんぱかって、古くなったからいい味を出しているねという声も一方ではあるのですけれども、そうはいっても、やはり学校選択の数字を見ると、やはり古い学校というのは、なかなか選択しづらいのかなという数字も見受けられるので、そこら辺の財政的な部分と、毎年、改築何校という考え方を。","respondent":"森学校施設担当課長","answer":"学校改築のペースですけれども、委員ご指摘のとおり、様々なご意見がありますが、やはり工事費用が非常に高騰している状況がございまして、今の予定ですと、年１校ペースを維持していくような状況です。","id":"exchange-012"},{"speaker":"松澤副委員長","kind":"質問","question":"少し素人考えですが、地べたに置くのと比べて、より太陽に近いと、もうそれだけで暑くなってしまうのかなという、子どもたちの熱中症があるという中で、そういった部分の心配が１点です。先ほどから話していました、学校改築計画というのは、地域というお話をよくするのですけれども、この地域というのは、要は１３地区をとっているのか、学校のブロックをとっているのか、そこだけ教えてください。","respondent":"森学校施設担当課長","answer":"地域についてなのですけれども、こちら、私の申しました地域というのは、ブロックに分けてあります。品川区内を６個のブロックに分けて、その中のバランスを見ているという状況です。","id":"exchange-013"},{"speaker":"松澤副委員長","kind":"意見","question":"そうすると、なかなか改築というのは進んでいかない。その６ブロックの中でも、やはりどこかで柔軟な考えを持っていただく部分がないと、どうしても、取り残されてしまうというのは、言い方が失礼ですけれども、なかなか改築が進まない学校というのが生まれてきて、それは少しバランスとは違うのかなというのが、個人的な意見なので、そのようなことも含めて、また、計画を考えていただければと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"}]},{"id":"topic-02","title":"その他のうち(1)所管質問","agenda":"その他のうち(1)所管質問","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"６月２３日の渡部議員の一般質問の「品川区の教育について」の中で、今、ご説明があったとおり、人口増によっての学校選択制についての部分で、ご答弁の中で、学校選択制の暫定的な停止などもあると。暫定的な停止のほかに、もう一点理由を述べられていたので、その１点を伺いたいです。暫定的な停止の暫定的についての考え方をお知らせいただきたいと思います。","respondent":"勝亦学務課長","answer":"暫定的な学校選択の受入停止という部分ですけれども、こちらにつきましては、各学校の状況におきまして、入学の予定や、就学人口など、学校施設の状況を見まして、学区外からいらっしゃる方は学校選択で入っていらっしゃいますが、学区内の方とは別に分かれておりまして、今後。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"これについて、なぜ質問するかというと、学校選択をし、きょうだいで同じ学校に通えないなど、学校選択の時期にはいろいろな相談を受けるのです。それで、前もって、きちんと地域、子ども、保護者への説明をするというのは、とても重要だと思うので、今のところ、現時点で予測が立っている部分について、報告をしていただきたいかなと思うのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"各学区の人口の状況や学校の状況を、今現在、１つ１つ精査しているところでございまして、直接そういった見通しが出てまいりましたら、早めにご周知等をさせていただきたいと考えております。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"現在、精査しているということでした。その精査の中には、今後のまちづくりもきちんと反映された精査なのかというところ、これからの再開発などでの影響もまた出てくると思うので、そういった部分も含めたことなのかというところを確認させてください。学区外、学区の考え方。ブロックではなくて学区なのかというところを少し確認させていただきたいです。","respondent":"勝亦学務課長","answer":"まちづくりを含めた検討かです。現状、把握できている再開発やマンション建設については、一定程度、人口の増、就学人口の増を見込んですけれども、先ほど、他の委員からのご発言がありましたように、計画外のものもあります。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"今、大変苦慮されているということで、本当にそうだと思います。でも、やはり子どもの保護者も、学校については、やはり選択性があるからという意識を持っている方もいるので、なるべく早く情報提供はしていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"確認","question":"すみません。少し確認したいのですが、現時点では、毎年選択はするけれども、結局、学区外から受け入れることはできないという現状は、かなりあると思うのです。現時点では、暫定的に選択の受入れを停止するということではないという理解でいいのでしょうかという確認です。どのような手続などを経て、そのようになっていくのかということを改めて教えて下さい。","respondent":"勝亦学務課長","answer":"今後、学区域の変更に当たっては、同様の検討が必要になってくるかなと考えています。","id":"exchange-019"},{"speaker":"松澤副委員長","kind":"意見","question":"今、学校選択制の暫定停止というお話になっているのです。その暫定停止の必要性というのはあるのか、ないのかという話をさせてもらうと、お話を聞いていると、今の制度と同じです。何でかというと、ここで、もし新たにこういうことをつくってしまうと、制度が結構複雑になるので、また、保護者が分からなくなるおそれがあるのではないかという２点です。","respondent":"勝亦学務課長","answer":"まだ、現段階で停止するという決定はしてございませんけれども、部分的にどこの学校を停止するといったことも決定してございませんし、今後、検討する中で判断してまいりたいと考えております。頂いたご意見も含めて、検討してまいりたいと思います。","id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"やはりお知らせしてもらうというのはとても大事かなと思うので、もし、学区外の受入れができなくなるという予測が立ったときには、早めの周知をしてほしいというのは、保護者の思いとして伝えたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"}]},{"id":"topic-03","title":"八潮中央保育園の大規模改修工事","agenda":"八潮中央保育園の大規模改修工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こうしていった経緯や理由を改めて教えていただきたいのと、ほかに同様の形態の保育園はありましたかということを伺います。２０２２年ぐらいまでは、そのような建て替えのための暫定地として活用しますということを説明されていたと思うのですけれども、その後、ここを子ども未来部として活用する要望などは出しているのでしょうか。伺いたいと思います。","respondent":"中元保育支援課長、初貝保育教育運営担当課長","answer":"こちらの形態の理由ですが、昭和５９年の開設当時は、まだ規制緩和の前でして、保育園の開設に関して、民間事業者は、まだ参入できないという時代でございました。今、仮園舎を使っております、旧八潮南保育園の後の使い方に関しまして、庁内で様々な検討をしているところで、いろいろな地域のニーズなどを踏まえて、今後、検討してまいります。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"大規模改修ということなのですけれども、中身はどのような改修がされるのかということがよく分からなくて、例えば、園庭などはどうなってしまうのか。狭くなってしまうのか、人工芝になるのかといったところなどを伺いたいのです。","respondent":"初貝保育教育運営担当課長","answer":"園庭に関しましては、まずは、今回は人工芝を予定しております。遊具の周りはゴムチップということで、落下したときに危険がなるべく低減できるような形の工事をしていく予定です。新築の建物ではないので、園庭に関しては、基本的には同じ大きさという形になっております。","id":"exchange-023"},{"speaker":"田中委員","kind":"質問","question":"園庭の広さが変わらないということは、少し安心しました。ただ、人工芝なのですけれども、やはり夏の暑さと静電気というものが、本当に子どもたちにとっては深刻でして、５月ぐらいからやけどしそうになってしまうということをよく聞くのです。なので、そういった対策がきちんとされるようにということも強く願いたいと思うのですが、何か対策は考えられているのかを伺いたいです。","respondent":"初貝保育教育運営担当課長","answer":"一方で、そうではないときも、例えば、人工芝に水をまくといった対応で、なるべく静電気や暑さを防ぐような対応をしています。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"少し確認したいのですけれども、今後、保育園の改修となったときには、もう人工芝生化していくという方針があるのかというところを確認させてください。","respondent":"初貝保育教育運営担当課長","answer":"人工芝生化というところは、園で改築を進める上で、それぞれ個別に検討しています。ただ、最近、建て替えをしているところは、人工芝の採用が多いという状況なので、周辺の環境や、園内の状況を確認しながら、それぞれ個別に検討しているという形で進めております。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"個別で検討されているということでした。その際には、やはり利便性とともにリスクの部分もきちんと話し合った上で、また、保護者と子どもたち、小さい子たちは少し難しいかもしれないですけれども、四、五歳になるとお話もできるので、園庭については、そういった話合いの場を経て、人工芝生化していくかどうかというのを検討していただきたいと思います。要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"設置の経緯も伺いましたが、当時、社会福祉法人が開設したということもありまして、安全対策もそうですし、やはり保育園や幼稚園のときから、特に自然の豊かな八潮というところですし、小さい頃から豊かな遊びの環境というか、保育環境にこだわっていただきたいなと思いますので、安易に、安易にしているつもりはないのでしょうけれども、人工芝にするよりは、保育園については、より慎重に、園の意向。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-04","title":"認可保育園の新規開設等","agenda":"認可保育園の新規開設等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"５月の文教委員会でも、４月の入園申請状況の報告もあったのですが、区が定めている６つの保育提供区域があると思うのです。この保育提供区域のうち、さらなる認可園の新規増設が必要だと考えている区域というのは、区としてはどこだと考えているのか。今回、来年４月の３園の計画が出ましたけれども、そことの関係で、これをどう見たらいいのかということを少し伺いたいと思います。","respondent":"中元保育支援課長","answer":"現在の就学前人口の状況で見ますと、今回の２番のさくらさくみらい品川シーサイドの住所は東大井ですが、この海岸沿いのエリア、また、３番の認可保育園に移行するウィズブック保育園天王洲がある東品川のエリアについては、今、少し厳しい状況かなというところがございまして。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"この２番と３番の新規の園は、具体的にお伺いしますけれども、保育提供区域というところのどこに当たるのでしょうか。そこら辺を教えていただきたいと思います。それと、待機児はゼロですと言いながら、来年４月には３園新設開設ということなのです。１園はマンションができるからということですが、その理由について率直に伺いたいのです。そこら辺について伺いたいと思います。","respondent":"中元保育支援課長","answer":"もちろん、来年も引き続きゼロにしていきたいというところがありますので、このような大規模な住宅が建つというときには、何らかの手当てが必要だという考えで、今回も建設をするものです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"すみません。区が保育提供区域というものをわざわざ分類しているので、３番のところはどこだったのかということを知りたいなということです。細かくて申し訳ないです。それと、もう一度伺います。ごめんなさい。来年は待機児がゼロになるか分からないということなので、やはりつくり続ける必要があるという認識なのでしょうか。もう一度伺います。","respondent":"中元保育支援課長","answer":"内陸部につきましては、ほぼ充足をしているところでございまして、やはりこの海岸地域のほうが、マンションが結構建っているところがありますので、そちらにつきましては、そのようなご相談がありましたら、前向きに検討していくです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、これから、まちづくり、再開発が起きるということを踏まえた計画があるのか、新規開設に向けた計画があるのかということを伺いたいのが１点です。この前、小山台住宅跡地の説明会でも、小山台のところに保育園が建たなくなった。ごめんなさい。提携している学校などがあるのかという確認と、２、３については、屋上園庭などをつくる予定があるのかというところを伺いたいと思います。","respondent":"中元保育支援課長","answer":"ただ、大きな建物が建つときに、一定程度の基準で、区のほうに床が提供されるときに、それだけのファミリー世帯が入る想定でしたら、保育園を検討していただきたいというのは、事前に情報を頂けますので、こちらからも所管と連携をとらせていただいているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"近くの公園等の利用があるということだったのですけれども、やはりその公園も、保育園で遊ぶところの取り合いが起きている状況の中で、まちづくりとともに、この保育園の設置というのも一緒に考えていただきたいなということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"渡部委員","kind":"意見","question":"３番の認証保育所からの移行で、皆さん、そのまま認可に移行できると思うのですけれども、２歳児が３歳児に切り替わるのが来年の４月でしょう。そのときは、自動的に、優先的に上げてしまうのか、ある程度３歳児での新規の登録をしてもらって、ふるいにかかるのかということだけ聞かせていただけますか。","respondent":"中元保育支援課長","answer":"利用申込をしていただいて、ただ、移行児の継続利用は認めているところですので、こちらにつきましては、まだはっきり確定ではお伝えできませんが、今のところ、そのまま定員も増えますので、ほぼ移行できる可能性が高いということで把握をしています。","id":"exchange-033"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"内容については、同意も大切なのでいいと思うのですが、こちらの調査項目にしたという理由というか、経過をもう少し教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"６月２４日の西本議員の質問で、保育園需要と区立保育園の今後の在り方について質問されました。区のご答弁が、今年度、区立保育園の在り方について検討していく中で示していくということでしたが、今年度、何を、どこで、どのような形で検討していくのでしょうか。スケジュール等や、その検討の会議体なども含め、もう少し具体的に伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園の在り方として区立保育園の役割や、適正な保育の供給などに関する検討を行い、その考えを整備していく予定です。その考えを基に、来年度以降、区立保育園の改築・改修に関する検討も進めてまいりたいと考えております。","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問","question":"その上で質問です。そのような名前でやっていくということですが、どのような方が参加する検討会になるのか、どのようなスケジュール感で、いつからいつまでで、何回ぐらいその検討をするのか、伺いたいと思います。それと、適正な保育の供給とありますけれども、適正というのは何を指しているのか。量ですか。そこら辺について、量なのか、質なのか、何を指しているのか、伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"今年度の検討の方向に関しましては、基本的に区の内部の関係している所管が集まりまして、その中で、プロジェクト、検討という形で進めてまいりたいと思います。回数に関しては、おおむね４回か、５回か、今、その辺りで検討しています。適正な供給量です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"確認","question":"供給量を考えていきたいということでした。そのようなことを言いたいのと、もう少し質問したいのは、内部のプロジェクトチームでということですが、その検討委員会のメンバーの方は、どういった方がメンバーに入るのかということを具体的にお伺いしたい。いつからいつまで検討して、議会にはどのような形で、いつぐらいに報告があるのかということを確認させてください。","respondent":"初貝保育教育運営担当課長","answer":"議会への報告等々に関しましては、その検討の中で、外部公表が議会に示せるようなしかるべきタイミングで、内容、進捗を鑑みながら考えていきたいといったところで、今、検討しています。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"もっと歯切れよく答弁していただければと思うのです。今年度、区立保育園の在り方について検討する中で示していくというご答弁だったと聞いたのですけれども、今年度中に議会に報告があるということではないのですか。その４回から５回というのも、ある程度回数まで想定するわけですから、いつからいつぐらいまでというのは、もう分かるわけです。お願いします。","respondent":"初貝保育教育運営担当課長","answer":"どのタイミングなのかというところは、検討の推移を見ながら、また、お示しさせていただければと考えています。","id":"exchange-038"},{"speaker":"田中委員","kind":"意見","question":"検討会は、区の内部の関係所管のプロジェクトで四、五回行われるということだったのですけれども、その検討会の議事要旨などの公開というのは、今、考えられているのかというところと、あと、区立保育園はどうあるべきかという部分は、現時点では、どのように考えているのかというところをお知らせください。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園の方向ですけれども、区立保育園は、区としては、乳幼児教育の中核をなすところだと考えておりますので、ある一定程度は必要だと捉えているところです。そういった区立保育園が担う役割といったところも、この検討の中できちんと見定めていきたいと考えております。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"障害児などの受入れも含めて、区立保育園が担う部分はとても大きいと思うので、まさか区立保育園をゼロにはしないと思うのですけれども、内部での検討もそうですが、議会、そして、子どもたち、保護者、地域の人たちにも、区立保育園が本当にどうあるべきかという議論は重要だと思うので、そのような議論がされる場が必要ではないかと考えますが、いかがでしょうか。","respondent":"初貝保育教育運営担当課長","answer":"区立保育園の役割というところに関しまして、今年度は内部の検討というところで進めするということで、あとは、様々な機会を見て、例えば、議会にお示しするタイミングが来れば、そこでもご意見等々を踏まえて、各保育園等から、ふだんからいろいろな意見を頂いていますので。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"区立保育園が担う役割の部分で、議会、現場は本当にそのとおりだと思うのです。地域や、子育て中の保護者の方たち、子育てを終えた方でも、子育てしてきた経験がある方にどのような保育が必要だったかという意見なども重要だと思うので、ぜひ地域の声も聞いていただけるように強く求めたいと思いますが、何かあれば伺いたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"そちらで、地域の方、保護者も含めて、アンケートを実施します。その中で、保育、子育てに関するご意見等を賜りまして、そういった内容も踏まえて、今回の在り方の検討に盛り込んでいきたいと考えておりますので、そういった機会も活用して進めていきたいと思います。","id":"exchange-041"},{"speaker":"田中委員","kind":"質問・要望","question":"今、アンケートを実施されるということで、少しは声が届くのかなと思って安心したのです。そのアンケートの周知や、子ども・子育て会議に出席される方の応募などはこれからでしたか。子ども・子育て会議の区民公募委員は、これからの募集ですか。アンケートも、より広く参加されたらいいなと思うので、その周知の部分についてお知らせいただきたいと思います。","respondent":"初貝保育教育運営担当課長","answer":"そちらのアンケートに関しましては、子ども・子育て支援事業計画を策定する中で、区内の子育てに関する方たち、ゼロ歳から５歳の子どものいる保護者を抽出して、今、７,０００人というところで、意向調査を実施する予定です。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5072#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":30160,"voices":143}},{"id":"r04-20220628-5","meetingId":"r04-cm06","date":"2022年6月28日","dateIso":"2022-06-28","committee":"総務委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"歳入のところでちょっと教えていただきたいのですが、１１ページの区分のところで、新型コロナウイルス感染症対応地方創生臨時交付金と、とうきょうママパパ応援事業補助金と、生活応援事業補助金と３種類書かれているのですけれども、この内訳のところを後のほうで見ると、全部都支出金となっていますし、歳入のところでも都補助金になっているのですけれども。","respondent":"黒田財政課長","answer":"令和４年度の新型コロナウイルス感染症対応地方創生臨時交付金につきましては、現在国のほうで交付の条件の内示額ということで、７億１,６５０万円ほど内示をいただいておりますが、この後、例年ですと年度途中に追加の交付等の決定もありますので、これで総額ではありませんが。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。それからあと、総務費のところで、１３ページのウクライナ避難民支援経費ということなのですけれども、これの具体的なご説明がなかったので、２１８万４,０００円ということなのですが、これをどういうふうに使っていくのかということを伺いたいと思います。それで、品川区に避難民が今実際にどれぐらい来られているのか、そのことも教えていただきたいと思います。","respondent":"古巻総務課長","answer":"人数的なところで言うと、あまりたくさんいらっしゃるというような見込みではないので、一応 ２０人分ということで予算を取らせていただきましたので。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ウクライナから避難されてきた方が本当に慣れないところですごく大変な思いをされているというのがネットでもかなりいろいろな事例みたいな形で出されていたりするのですけれども、例えば原発事故で福島から品川区に避難してきた方には区民住宅を提供したりとか、さまざまな支援があったと思うのですけれども、そういう点では区民住宅を提供するとか、それから、今。","respondent":"古巻総務課長","answer":"住宅に関しては、住むところがない方、要は都内に身寄りがない方に関しては、東京都のほうが都営住宅の提供などもしていますので、そういったところへつなげたりとか、さまざまな形で支援をさせていただいているという状況です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"総務委員会はこういう補正予算の総合審査ということなので、なぜ補正予算になったのかというところなのですけれども、建設委員会の資料を見ると、区内を通過する新線が令和３年１月に国土交通省から事業許可がされて、２０２９年開業を目指しているということでされているので、去年の１月に既に事業許可がされているわけですから、もしもこういう予算を組むとしても。","respondent":"黒田財政課長","answer":"その感じでいきますと、開業の予定を令和１１年というふうにしておりますので、調査・設計でありますとか工事の期間にそれぞれ３年程度ずつかかるということからしますと、もし区内に新駅を設置するということであれば、ＪＲの事業の調査・設計のところに。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、長期基本計画の中で新駅の設置に向けた要望を行っているので、これも検討するということであるのですけれども、そこのところは五反田、大崎、大井町のさらなる活性化を図るために働きかけるとともに新駅を設置していくと書かれているのです。この新駅設置がなぜ五反田、大崎、大井町の活性化につながるのか、その点についても伺いたいと思います。","respondent":"黒田財政課長","answer":"なぜ五反田、大崎、大井町の活性化につながるのかというところにつきましては、いわゆる今回事業許可を取っておりますのは東山手ルートになりますが、ＪＲのほうで大きな３つの計画を立てておりまして、西山手ルート、東山手ルート、臨海部ルートということで。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"新駅を造る場所というのは、大崎、大井町とか、八潮の東京貨物ターミナルのあたりではないところの可能性というのも探るということなのでしょうか。そうすると、どういうところに駅を造れる可能性を考えられているのか。","respondent":"鈴木（真）委員長、黒田財政課長","answer":"ちょっとごめんなさい。都市計画課として出している中で、企画部としてどこまで答えられるか。そこの仕切りがあると思うので、答えられる範囲で。予算の中で検討するのは、今３つのルートが計画されていて、どこに駅が、可能性があるかというところを土地利用の状況等を把握して検討するというところを予算で掲げておりますので。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、今のに続けて確認したいのですが、所管を超えたら指摘をしていただきたいと思うのですけれども、先ほど検討するのに委託ということで、関連事業者ということでした。これは品川区が選ぶという理解でよろしいでしょうか。","respondent":"黒田財政課長","answer":"品川区が委託契約を行いますので、品川区が委託事業者を選ぶです。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問","question":"それで、もう一つは、このルート、臨海部ルートというのを資料で見ているのですけれども、これは決まってしまっているのですか。このルートは、固定で、その上で検討するということの経費なのか。この中身が何をするのかよく分からないのですよ。この検討というのが。ここに品川区の住民がいないのに、何もお金をかけて検討する必要はないではないですか。何のために検討するのですか。いかがでしょうか。","respondent":"鈴木（真）委員長、黒田財政課長","answer":"先ほども言ったように建設委員会との兼ね合いがありますので、その辺を踏まえてお答えください。何のために検討するのかですが、先ほど申し上げたとおり、長期基本計画の中で、いわゆる羽田空港から東京の表玄関、都心のほうに輸送ルートとして鉄道が敷かれるということであれば。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"それからちょっと確認です。ウクライナ避難民支援なのですけれども、先ほど２０人程度ということでした。それから、歳入のところなのですけれども、財政調整基金のほうから出していますが、これは足りない分ということですかね。大体、都補助金が１０分の１０で来ているのだけれども、歳出のところの金額と、ちょっと足りないから財政調整基金から繰り入れるのですよという理解でよろしいでしょうか。","respondent":"古巻総務課長、黒田財政課長","answer":"ウクライナ避難民支援の関係で、人数につきましては見込みで２０人ということで、東京都からもいろいろ情報をいただいていますけれども、最大でそれぐらいかなという予測で予算を作らせていただいています。一般財源につきましては、例えばウクライナ避難民支援でありますとか、選挙の公費負担につきましては、一般財源で行うべき事業ということで計上させていただいているものです。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"都と交渉して、例えば１００人ぐらいになるなどという見込みが出てきた場合には、それなりの交渉をして、補正予算がかかるのかなというふうに思っているのですが、これからの柔軟性といいますかね、ということは東京都とそういう交渉をしているのかということと、それから選挙費のほうで、何でここに補正予算がかかっているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"相談のところです。基本、大分何か国語も入っていると、一度何語かと伺ったのですけれども、ウクライナ語というのはどうでしたか。ウクライナ語が入っていたかどうかの確認と、もしそういうことであれば、ものすごくお金がかかるということならばまた別なのですけれども、一言語、こういう状況ですからウクライナ語を増やすというようなことのお考えはないのか、お尋ねしたいと思います。","respondent":"古巻総務課長","answer":"これについては区役所で何台か持っていますので、今総務課のほうに借りていまして、場合によっては対応をということですが、大体英語ができる方というのも多いですし、日本人の支援者が一緒にいらっしゃっているというケースもあるので。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"前にタブレットのことを伺ったときも大体３か国語で間に合うというふうに伺ったことがあるので、英語とか、品川区においては韓国語と中国語で大体対応できると伺っていたのですけれども、事態が事態ですので、行った先に母語が用意されていたということになると、それだけでもすごくほっとするところがあるのではないかなと思います。この考え方は変わっていませんよね、というのを一つ伺いたいと思います。","respondent":"黒田財政課長","answer":"予算の考え方につきましては、今ご指摘がありましたとおり、当初予算のほうで１年間の事業の歳入歳出の計画を立てまして、予算の組立てをしておりますので、そこで議決をいただきまして、その後の状況の変化によりまして、それが国等の動きでありましたり。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問","question":"早い時期に動かないと品川区の考え方は入れ込めないねというふうになるわけではないですか。そうしたら、何で当初予算ではなかったのかということは、今のことを伺っても、本当にどうしても理解ができないのです。そうすると、長期基本計画で考えたときの考え方がそこまできちんと組み立てていなかったのかということになってくると思うのですけれども、やっぱり難しかったということなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の羽田空港アクセス線のことなのですけれども、ＪＲ東日本は今駅を造る方針はないということになっていると思うのです。それを区がこういうふうな形で検討して駅を造ってほしいということで要望して、ＪＲ東日本が、では造りましょうというふうになった場合は、駅を造る場合の負担というのは区も負担するようになるのか。ちょっとその点について伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけになるかもしれませんが、今の羽田空港アクセス線新駅可能性検討経費というのは、ぜひ品川区政にとっても品川区民にとっても何とか利益をもたらすように、私は頑張っていただきたいと思います。間に合うのか、間に合わないのか分かりませんが、必要に応じて、どなたか特命役員かなんかをつけてどんどん積極的に交渉していただきたいと私は思います。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"質問・要望","question":"うちからの質問だったか、他の議員の方からの質問だったか忘れてしまったのですけれども。物品購入のものに関わってということなのですけれど。細かい部分、すみ分けとして。区独自ということで、新型コロナウイルス感染症対応地方創生臨時交付金を活用しての２万円というのは、これは物価高騰の影響ということになっているのですけれども、そこの部分の捉え方をちょっと確認させていただきたいと思います。","respondent":"黒田財政課長","answer":"子育て世帯の家事支援用品購入支援および子育て世帯サポート事業につきましては、事業の組立てとしましては、今ご指摘があったとおり家事支援用品購入支援事業は、コロナ禍において家事育児ヘルパーのサービスが行き届いていない家庭に対していわゆる家事支援用品の購入をして。","id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"細かい部分での確認です。１点、ちょっと所管的な感じになるかもしれませんが、総合的にという視点で極力伺いたいのですが、今確認させていただいたように、用品購入のときに対象家庭があくまでも保育サービスを利用していないことが条件なのですが、例えば申請した後、この物品購入を受けた後にサービスを受けることもできないという設定でしたね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"避難民の方が来られてというので、ごみの出し方が分かっていないようなので、どうやってお伝えしたらいいですかねみたいな話もあるというふうに聞いておりまして、２０人ということなので、そういう方たちの不安が募らないように、何かその辺の日本のルール、マナーみたいなところの伝え方とかはやられているのだと思うのですけれども、どのようにされているのかなというのを教えていただければと思います。","respondent":"古巻総務課長","answer":"ごみの出し方ということで、今委員からご指摘がありましたけれども、そういったことにつきましては、まだ個別にいろいろ対応できるぐらいの人数でありますので、そこは個別に対応させていただいているということと、あとは一般的には、英語版。","id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"それはＬＩＮＥをお伝えして、しっかりやっていただいて、英語もしゃべれるというようなお話だったので分かるのかなと思いますが、今後２０名予定されている中で、なかなかそういうことも難しい方もいらっしゃるかもしれないので、何か分かるようにきちんとお伝えしていただければと思います。そこはよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さらにまた、先ほどもありましたけれども、区民の状況というのは大変厳しい状況がありますので、さらなる支援の検討を求めて、この補正予算全体としては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"結論からいいます。理由を言わせていただきたいと思います。品川・生活者ネットワークは以前も総合審査というところで項目としては１つだけ反対だったのですけれども、ただ、補正予算の中にそういう形の、何だか全体は反対しにくいというか、全体は賛成が多い補正予算の中に、あるべき形ではない形で補正予算で入れてしまうということは、やはりこういうやり方はあってはならないのではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(3)品川区長選挙および品川区議会議員補欠選挙における執行計画","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更し、(3)品川区長選挙および品川区議会議員補欠選挙における執行計画","exchanges":[{"speaker":"吉田委員","kind":"提案","question":"と申しますのは、最初に提案されたときの次の選挙のときにちょっと調査をかけたのです。せっかく選挙管理委員会のほうで税金を使ってそういうものを用意されたのに活用されていなくて残念だったなと思ったことがあるので、ぜひそういうものはきちんと活用していただきたいという思いで現状を確認させてください。出せるのだけれども、出していないのでしょうか。その辺についても教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"投票事務の事務長の説明会が必ず選挙ごとにやっておりますので、その席で改めて徹底できるように周知をしてまいります。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"「遅い」と叱られたのですけれども、誰かが読んで作るということがあると思うのですけれども、もちろん届出がないうちに選挙公報を作るわけにいかないので、一定制約があることは重々承知しているのですけれども、その辺の仕組みといいますか、ちょっと私はそういうシステムのことが疎いのですけれども、誰がそういう音声にして、どういう形で視覚障害者のお手元に届くのか。","respondent":"鈴木選挙管理委員会事務局長","answer":"したがいまして、委員からもご指摘がありましたように、立候補の手続が終わってからでないと調製、配布の準備ができませんので、どうしても選挙期日間近になってしまうというのが現状です。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"わかりました。どういうふうにしたら私たちとしても早く届けられるか。だから、努力しなければいけないということですよね。具体的にどうしたら早く当事者のお手元に届くのかということは、また後で伺いたいと思います。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"１点だけ。ちょっと確認をしてほしいのですが、公営ポスター掲示板の設置場所に対しては、いろいろご尽力くださったり、ご苦労されていると思います。それはよくわかります。このたび、参議院議員選挙から、小山３－２３－２３あたりにあった公営ポスター掲示板が、荏原５－１－２の荏原中央公園内に移転したみたいなのですね。お願いします。それだけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"大倉委員","kind":"質問・要望","question":"投票率向上というところで、以前、投票済証かなんかを新しくして、またそういうものを啓発に使っていきますというお話だったかと思うのですが、それについてホームページを見てもなかなかちょっと出てこないのですけれども、これからどういうふうに活用されていくのか、考え方があれば教えていただきたいと思うのです。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご質問の投票済証の発行ですが、ご指摘のあったいろいろなご意見だとかアイデアをいただいたことは私どもも引き継いでおりまして、この秋の区長選挙と区議会議員補欠選挙につきましては、区のオリジナルの投票済証、具体的には区の観光大使をやっていますシナモロール。","id":"exchange-026"},{"speaker":"大倉委員","kind":"意見","question":"そうやって新しく取組みをしながらさまざまな整備、また投票に行ってもらうというところで非常にすばらしい取組みをしていただいているなと思っています。何かあれば。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のように若い方への投票行動の呼びかけや、商店街との協力関係というのは区全体にとってもいいこととなると思いますので、まず今回秋に実施をして、投票済証の反応だったり、また課題がないかというようなところも検証した上で、今後さらに活用ができるのであれば。","id":"exchange-027"},{"speaker":"湯澤委員","kind":"質問","question":"今回区長選挙のほうでも、配布期間が令和４年９月２６日から１０月１日ということで、投票日の前日までに配布するということになっているかと思うのですけれども、参議院議員選挙のときにも「選挙公報はいつ来るの」という声がありまして、今、期日前投票なんかもかなり盛んに行われているので、結局、期日前に行こうかなと思っても、選挙公報が届かないと。","respondent":"鈴木選挙管理委員会事務局長","answer":"それと、品川区の場合は、全世帯に個別の全戸配布をいたします方法として、品川区シルバー人材センターにお願いしているというのがありまして、やはり区としても支援している団体ですのでお願いをしているという経緯はあるのですが、二。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"例えばある程度確定したデータができた場合にＬＩＮＥで、それこそシナモロールと併せて、今度の選挙についてはこういう方たちがこういう主張をされていますみたいな発信などというのはルール上できないのか、理屈上できないのか、既にやっているのか、よくわからないのですけれども、多分ホームページとかに出されたりもするのでしょうし、そういった活用というのはできないのですか。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙公報につきましては、法の規定によって作成・配布するのが定められているので、一般的な ＳＮＳなどをどこまで活用できるかというのは、ちょっと確認をさせていただきたいと思います。ただ、現時点ではまだそこは活用していないという手法になります。","id":"exchange-029"}]},{"id":"topic-03","title":"八潮中央保育園大規模改修機械設備工事請負契約","agenda":"八潮中央保育園大規模改修機械設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですが、契約金額が１億３,０９０万円ですよね。これに対して大洋テクニカと中央工設が入札されたということなのですが、ＪＶ２社で組む必要があるのですか。金額もそうなのですが、工事内容はそんなに大きくないのに、何か理由があるのでしょうか。","respondent":"東野経理課長","answer":"設備関係の工事請負契約につきましては、１億３,０００万円以上のものにつきましてはＪＶ工事ということで規定をしています。","id":"exchange-030"}]},{"id":"topic-04","title":"台場小学校空調設備改修工事請負契約","agenda":"台場小学校空調設備改修工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"工事内容なのですけれども、屋上に設置されている冷温水発生器というのはどういう機能というか、どういうものなのか、教えてください。ごめんなさい、基本的な知識がないので、この設備がどういう目的で設置されていて、このたび多少不具合が出たとか、更新時期が来たとか、そういうことだと思うのですけれども、その辺についても教えてください。","respondent":"小林施設整備課長","answer":"大体この機械自体が耐用年数というのが定められておりまして、およそ１５年ぐらいです。この施設につきましては、１８年程度既に経過していますので、機器の状況とか数字が結構悪くなっているということで今回改修工事を行うです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"基本的に、これは小学校の屋上とかにはみんな設置されているものなのでしょうか。それとも、特別にこの学校にそういうことが必要で、そういうふうに設置されているのか。すみません、学校の現状に全然詳しくないので教えていただければと思います。","respondent":"小林施設整備課長","answer":"全ての学校がどうかというところまでは把握できておりませんが、通常大きな施設で、１か所の場所で、要は冷たい空気とか温かい空気を作る場合については、こういったような大きな機械、冷温水発生器みたいな大きな機械を使ってまとめて作り出すということは一般的です。","id":"exchange-032"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今お話を聞きまして、私としては安心しました。ただ、１点だけ、これは一緒なのですかね。尼崎市はまず大きな会社に情報、そういう管理ですか、整理とか何かを協力会社としてまずそこに一括してお願いする。情報の整理ですね。それをさらに外部に、ほかの会社に、その協力会社の別の会社に委託するということはありなのですか。それも一切なしということですか。それだけ。","respondent":"宮澤情報推進課長","answer":"委託業務の再委託の考え方です。基本的には禁止しておりますが、やむを得ない場合と許可がある場合は許可を与えているです。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"皆さん、それが一番心配しているところなのです。どこでどう漏れるか。区としては厳格な規則を作って運営されていると思いますが、やはり人はそこで必ず介在していますから、その辺、さらなる厳重なチェックができるように、くれぐれも細心の注意を払っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"そういうお答えですよね。そこをどうするのですかという話になるのですね。特にデータの解析とかデータの整理とかといったら、庁舎の中で全部やるのですかという話ですよ。ただ、先ほどの指紋認証とかがあるので、誰でも開けられるというわけではないということを考えれば、ある程度対応はあるのかなと思うのですが、今後そういう業務というのはいっぱい増えると思うのですけれども、どう考えられるのですか。","respondent":"宮澤情報推進課長","answer":"そういった形で個人情報の外部持ち出しというのは、業務上必要な範囲というところで適切に管理しながら対応しています。","id":"exchange-035"},{"speaker":"西本委員","kind":"意見","question":"そういう決まり事をきちんとしていなかった、しかも飲みに行ってしまったなどというのはとんでもない話であって、そういうことは徹底して周知をすれば、そういう状況にならなかったというか、そちらのほうが今回は大きかったのかなと思うのですけれども、それも含めて対応していただきますよう、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":34712,"voices":108}},{"id":"r04-20220629-14","meetingId":"r04-cm06","date":"2022年6月29日","dateIso":"2022-06-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、私たちは超高層ありきではなく、低層、中高層で検討すべきだという意見をずっと申し上げていますけれども、今回のこの計画ですと、低層部分というのは、ニュースだったりこの間の第８回の資料の中の１２ページだったかのところに書かれているこういう図で、低層階というのは何階までを低層階ということで示されているのか、その点についても伺いたいのと。","respondent":"大友新庁舎建設担当課長","answer":"こちらですけれども、フロアとしては３階に取りつく予定になるかと想定しております。まだ設計しておりませんので、１階のフロア高によって変わってくるかと思いますが、想定上では３階になるかと想定しております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この２,５００m2に対して、今の平米数がどれくらいかというのを教えてください。それで、低層が六、七階から１０階ぐらいだと。そうすると、中層階と高層階とあと地下ということで、４層に分かれているのですが、中層階と高層階というのはそれぞれ何階ぐらいになるのか、何階ぐらいを中層階、高層階と考えられているのか、その点についても伺います。","respondent":"大友新庁舎建設担当課長","answer":"ご質問の第２点目の、低層階、中層階、高層階というところの分けですけれども、誠に申し訳ありません、ご指摘をいただいた資料をもってご説明すると、第８回の資料で提示をしていますゾーニングの方針で、使い方をある程度書かせていただいております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それからあと、区民協働交流スペースというのが歩行者デッキの下のところに書かれているのですけれども、これはそうすると３階以下、１階、２階のところの部分が区民協働交流スペースというふうになるのでしょうか。それで、そういう部分というのは区民サービスに使うほうが、区民サービスにつながっていくかなという思いがあるのですけれども、この区民共働交流スペースというのはどういう中身なのか。","respondent":"山下新庁舎整備課長","answer":"災害発生時等々におきましては、そういった場所を罹災証明書の発行でしたり、災害時について比較的自由に使えるスペースとしてしつらえられたらという考え方が基本にございまして、このようなお示しをしています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"いろいろ私も第８回の策定委員会の、議事録が既にホームページに上がっていましたので、これは読ませていただいて、かなりたくさんの委員の皆さんがいろいろ様々な意見を言われていて、それに区がどう答えられているのかというのも見させていただいたのですけれども、その中で、改めてそれを踏まえて申し上げたいと思ったのが、この１番の区民サービスのところで、ここには窓口機能の配置ということで。","respondent":"山下新庁舎整備課長","answer":"実際来庁される頻度ですとか、そういった割合を考えますと、一番入ったすぐのところにあるのが利便性としては高いかなというところは一定ありますけれども、高齢者福祉、障害者福祉の部門といったところでは、来庁される方のご容体といいますか。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その点について伺いたいと思います。いろいろなところで障害者の方の配慮がやはり必要だと思うのですけれども、その配慮が具体化される形で、ぜひその障害者の方々から、庁舎の設計に当たって意見を聞く仕組みを作っていただきたいと思うのですけれども、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ところが今の発言は、聞いていると、よく見ても基本設計、それから実施設計まで入り込んでいる部分の発言がほとんどで、安藤委員がその発言をしたのはいいけれども、それは今、基本計画策定委員会でやっていても、それは区民の方もいらっしゃったりいろいろな方がいるけれども、ここは行財政改革特別委員会で、議員がしっかりそのルールは守ってやろうよという中でこの特別委員会もできているわけだから。","respondent":"若林委員長、山下新庁舎整備課長","answer":"そういう原則のもとで本委員会が行われているということで、改めて認識をさせていただいて、鈴木ひろ子委員の質疑については、確かに設計のほうに入ってきている部分もある。別紙１にお示ししております相談ブースのところですけれども、見た目には相談されている方々が映るようなイラストをしつらえとしておりまして、このようなイメージになっておりますけれども。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"提案","question":"私からは３つ、確認を含めてお伺いをしたいと思います。その前に、共産党の鈴木ひろ子委員から様々、非常に新庁舎に対しての前向きなご発言があったことについては、非常に歓迎をしたいと思いますし、ぜひ新庁舎、すばらしい庁舎ができるようにというところで、様々なご提案とかご意見、どんどん述べていっていただきたいと思っています。この３点をお伺いしたいと思います。","respondent":"山下新庁舎整備課長","answer":"３点目のＪＲのレンガの倉庫ですけれども、新庁舎整備に関わるところに近いのですが、実際各所管のほうでその対応をやられているとは聞いておりまして、進捗の事細かなところまでは承知しておりませんけれども、対応は進んでいるものと捉えております。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"例えば品川区として、まだ新庁舎ができるのは先ですけれども、このワンストップサービス、今表にはこの２種類がお示しされていますけれども、他の人口規模が同等な自治体ですとか、事務取扱とか、何か研究とかをされていて、イメージとしてもうこれはいい、こちらがいいみたいなのが、ある程度あるのかどうなのかというのをちょっと１つお伺いしたいところだったのですけれども。それと、やはり転入・転出。","respondent":"山下新庁舎整備課長","answer":"まだどちらのほうが優位かというところまで結論は出ていないところですけれども、例えば職員ローテーション型のワンストップにおきましては、特定の処理が重なった時に。","id":"exchange-008"},{"speaker":"渡部委員","kind":"質問・要望","question":"課長さんのお口からも出てきたそのスーパーマン方式というのは小さい自治体だったらいいかもしれないですけれど、これだけの規模の自治体で、それはスーパーマンをしこたま用意しておかないと回らなくなりますので、難しいのかなというのもあるのですが、先ほど申し上げたそのお悔やみの部分と。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"ご説明があったかもしれないですけれど、ちょっと聞き漏らしていたらすみません。裏面の新庁舎の規模のところで、現庁舎規模から線が出ていて、赤い点線と青い点線があるのですけれども、この赤と青というのは何か意味の違いというのは特にあるのですか。そこについて、最初に教えてください。","respondent":"大友新庁舎建設担当課長","answer":"赤の線と青の線の違いについてですけれども、こちらのほうは第８回の時に少し変更をした部分が赤になっておりまして、変更がないところが青のままという形で色分けをしてお示しをしているような状況になります。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問・要望","question":"どれぐらいの使用率というか、駐車場が今よりは広がるのでどうなのかなという感じはあるのですけれども、結構最近駐車場もいろいろ入れない時があったりするので、現駐車場でいっぱいになっているというのがあったりするので、もしかしたら第２駐車場をうまく活用するということも検討していただく必要があるのかなということも思いますので、これは意見として述べさせていただきたいと思います。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"入るという内諾の協定締結に向けまして、今動いているという状況です。先ほどほかの委員からもございましたけれど、まだそのワンフロア当たりの平米数といったところも、設計ではないところから決まっていないこともございまして、かちっとその数字を決めてしまうと。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。今ある国や都の機関は基本的に継続というか、新庁舎にそのままということがありましたので、そこは区民サービスの維持という意味では大変に安心をいたしました。スペース等は拡充になるので、どこがどれだけ広がるかというのは、いろいろな方々のご意見というか思いもあるでしょうから、なかなか落としどころはいろいろだと思いますけれども、引き続きよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前回の調査事項概要の説明の時だったと思うのですけれど、このスケジュールで、７月に第９回が行われて、８月にパブリックコメントということになると思うのですが、このパブリックコメントの前に説明会をぜひやっていきたいということでのご答弁をいただいたと思うのですけれども、それはいつ頃、どのような形で説明会をされていくのか伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"基本計画素案が固まりますのが、そういった意味では７月１９日以降というところになりますので、そちらをもって説明をする場というのは設けていきたいというところで、今、種々調整に当たっているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"８月のパブリックコメントの前に説明会が行われるということでよいのですよね。できれば何回かやっていただきたい。その日ということだと都合が悪くて来られないという方もいらっしゃるのではないかなと思うので、区民にとっての、区民の財産の庁舎を造るわけなので、ぜひそういう形では区民に示す形で、ご意見もいただけるということでの説明会をしていただきたいと思うのですが、いかがでしょうか。","respondent":"山下新庁舎整備課長","answer":"そこで、パブリックコメントを実施している最中、できれば複数回の開催をということで今種々調整に臨んでおりまして、新型コロナウイルス感染症でしたり、その他いろいろな諸事情、諸状況があるかと思うのですけれども、やはり今回満を持してといいますか。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会を各地域、複数回ということでしていただくというのは本当によかったと思っているのですが、ぜひパブリックコメントに反映できる形で、パブリックコメントが行われる前に説明会をやっていただきたいということで、これはちょっと要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えてください。資料の５番の新庁舎の規模の赤枠の考え方を教えていただきたいと思っています。この保健センター管轄区域を再編成して、この一部機能２,０００m2をというのは、これまで我々議会としても、コロナがあったりしてそういう対応ができるような形で強化をしたほうがいいのではないですかという判断をしていただいたのだと考えています。これで文書・物品の削減量を５０％にしていこう。","respondent":"大友新庁舎建設担当課長","answer":"各委員会などで必要な機能を盛り込んでいった合計になっておりますが、今後ご指摘のとおり、まだ必要な機能が追加されることがあったり、新庁舎のオフィスでもっと文書を削減できるのではないかとかいうことで、今は５割となっているのですけれども。","id":"exchange-016"},{"speaker":"西村委員","kind":"意見","question":"これに関しては、子育ての部分ではワンストップサービスで、今回は細かく具体的な話はありませんけれども、どこに何を相談していいか分からないというのが、特に子育て分野かなと思いますので、例えば子育てナビゲーターみたいな詳しい方がいらして、お願いしたいなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"西村委員","kind":"意見","question":"もう１点だけ、相談機能の充実のところです。本庁舎以外の行政拠点とテレビ電話などで相談できる設備の導入の部分で、すみません、以前もご説明があったら申し訳ないのですが、例えばどのような支援が考えられるのかお聞かせください。","respondent":"山下新庁舎整備課長","answer":"いわゆる子育てにおけるワンストップサービスといったところにつきましては、所管のほうでもいろいろ検討を進めているところだと思います。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/893508?Template=document&Id=6132#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":23928,"voices":49}}]);
